def diagnose(err, what):
    """From an exception to a sentence and a few things to try.

    what is the thing the user asked for, in their words: 'Save', 'Cut',
    'Whole raster'. It goes in the headline because 'something failed' is not
    a sentence anybody can act on."""
    text = error_text(err)      # the class name is already in there
    for must, mustnt, sentence, remedies in TROUBLE_RULES:
        if all(word in text for word in must):
            if mustnt and any(word in text for word in mustnt):
                continue
            return sentence, list(remedies)
    return ("%s stopped with an error that has no advice written for it yet."
            % what,
            ["The message underneath is the machine's own words, and is "
             "usually the fastest way in.",
             "Nothing already saved is affected: a failure here leaves the "
             "campaign as it was before the command.",
             "Press Copy report and send it on. A report with the versions in "
             "it is enough to find this without the file."])


def fixed_font():
    """A font whose letters are all one width, for reports whose columns
    line up: Consolas where Windows has it, the system's own otherwise, at
    the size of the rest of the window."""
    f = QFont("Consolas")
    f.setStyleHint(QFont.StyleHint.TypeWriter)
    if not QFontInfo(f).fixedPitch():
        f = QFontDatabase.systemFont(QFontDatabase.SystemFont.FixedFont)
    try:
        f.setPointSizeF(QApplication.font().pointSizeF())
    except Exception:
        pass
    return f



class Trouble(QDialog):
    """The window that opens when a command fails.

    Three parts, in the order a person needs them: what was being done and
    what went wrong, then what to try, then the detail, folded away. The
    detail is the part nobody reads and everybody needs the moment they ask
    somebody else for help, so it goes on the clipboard with one button."""

    def __init__(self, err, what, parent=None):
        super().__init__(parent)
        self.setWindowTitle("%s: %s did not finish" % (NAME, what))
        sentence, remedies = diagnose(err, what)
        self.report = self.build_report(err, what, sentence)

        box = QVBoxLayout(self)
        box.setSpacing(10)
        # A word wrapped label is as tall as the width it is given, and Qt
        # only asks when the layout is told to. Without this the dialog is
        # sized for one line of each paragraph and the advice is cut in half,
        # which of all the things to lose is the worst one.
        box.setSizeConstraint(QLayout.SizeConstraint.SetMinimumSize)

        headline = self.paragraph(sentence)
        f = QFont(headline.font())
        f.setBold(True)
        headline.setFont(f)
        box.addWidget(headline)

        said = self.paragraph("%s: %s" % (type(err).__name__, err))
        said.setObjectName("quiet")
        box.addWidget(said)

        box.addWidget(self.rule())
        try_this = QLabel("What to try")
        f2 = QFont(try_this.font())
        f2.setBold(True)
        try_this.setFont(f2)
        box.addWidget(try_this)
        for i, remedy in enumerate(remedies, 1):
            box.addWidget(self.paragraph("%d.  %s" % (i, remedy)))

        self.fold = QToolButton()
        self.fold.setText(" Detail")
        self.fold.setCheckable(True)
        self.fold.setArrowType(Qt.ArrowType.RightArrow)
        self.fold.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextBesideIcon)
        self.fold.setAutoRaise(True)
        self.fold.toggled.connect(self.show_detail)
        box.addWidget(self.fold)

        self.detail = QPlainTextEdit()
        self.detail.setReadOnly(True)
        self.detail.setPlainText(self.report)
        self.detail.setMinimumHeight(220)
        self.detail.setMinimumWidth(TROUBLE_W)
        # In the fixed font of the system, as the Check report is, and
        # wrapped: paths and the traceback were cut off at the right edge.
        try:
            self.detail.setFont(fixed_font())
        except Exception:
            pass
        self.detail.setLineWrapMode(QPlainTextEdit.LineWrapMode.WidgetWidth)
        self.detail.hide()
        box.addWidget(self.detail)

        buttons = QDialogButtonBox()
        copy = buttons.addButton("Copy report", QDialogButtonBox.ButtonRole.ActionRole)
        copy.setToolTip("Put the whole report on the clipboard, versions and\n"
                        "traceback included, ready to paste into a message.")
        copy.clicked.connect(self.copy_report)
        save = buttons.addButton("Save report...", QDialogButtonBox.ButtonRole.ActionRole)
        save.setToolTip("Write the report to a text file.")
        save.clicked.connect(self.save_report)
        buttons.addButton(QDialogButtonBox.StandardButton.Close)
        buttons.rejected.connect(self.reject)
        buttons.accepted.connect(self.accept)
        box.addWidget(buttons)

    def paragraph(self, words):
        """A label that wraps, and that says how tall it needs to be.

        Qt will not work the second part out on its own: a wrapped label
        reports the height of a single line unless its size policy is told
        that height depends on width, and then the dialog is built around a
        sentence and clips the other four."""
        label = QLabel(words)
        label.setWordWrap(True)
        label.setTextInteractionFlags(Qt.TextInteractionFlag.TextSelectableByMouse)
        policy = label.sizePolicy()
        policy.setHeightForWidth(True)
        policy.setVerticalPolicy(QSizePolicy.Policy.MinimumExpanding)
        label.setSizePolicy(policy)
        # The width is pinned here rather than on the dialog, because a layout
        # under SetMinimumSize decides the dialog's minimum itself and would
        # throw any width set from outside away.
        label.setMinimumWidth(TROUBLE_W)
        label.setMinimumHeight(label.heightForWidth(TROUBLE_W))
        return label

    def rule(self):
        line = QFrame()
        line.setFrameShape(QFrame.Shape.HLine)
        line.setFrameShadow(QFrame.Shadow.Plain)
        line.setProperty("rule", True)
        return line

    def build_report(self, err, what, sentence):
        lines = ["%s %s build %s: %s did not finish"
                 % (NAME, VERSION, BUILD, what),
                 "",
                 "reading: %s" % sentence,
                 "%s: %s" % (type(err).__name__, err),
                 ""]
        for name, value in environment():
            lines.append("%-12s %s" % (name, value))
        lines.append("")
        lines.append("when: %s" % time.strftime("%Y-%m-%d %H:%M:%S"))
        lines.append("")
        trace = traceback.format_exc()
        if not trace or trace.strip() == "NoneType: None":
            trace = "".join(traceback.format_exception_only(type(err), err))
        rows = trace.splitlines()
        if len(rows) > TRACE_LINES:
            rows = (rows[:4] + ["   ... %d lines left out ..."
                                % (len(rows) - TRACE_LINES)]
                    + rows[-(TRACE_LINES - 5):])
        lines.extend(rows)
        # pasted into public issues, as the Check report is
        return without_home("\n".join(lines))

    def show_detail(self, opened):
        self.fold.setArrowType(Qt.ArrowType.DownArrow if opened else Qt.ArrowType.RightArrow)
        self.detail.setVisible(opened)
        self.adjustSize()

    def copy_report(self):
        try:
            QApplication.clipboard().setText(self.report)
            log("report copied to the clipboard")
        except Exception as err:
            log("could not reach the clipboard: %s" % err)

    def save_report(self):
        where = os.path.join(
            os.path.expanduser("~"),
            "%s_report_%s.txt" % (PREFIX, time.strftime("%Y%m%d_%H%M%S")))
        path, _ = QFileDialog.getSaveFileName(
            self, "Save the report", where, "Text (*.txt)")
        if not path:
            return
        try:
            with open(path, "w", encoding="utf-8") as fh:
                fh.write(self.report)
            log("report written to %s" % path, loud=True)
        except Exception as err:
            log("the report itself could not be written: %s" % err, loud=True)

_TROUBLE = {"open": False, "signature": None, "when": 0.0}


def in_a_storm(err, what):
    """True when this exact failure has just been shown."""
    signature = (what, type(err).__name__, str(err)[:200])
    now = time.time()
    if _TROUBLE["open"]:
        return True
    if (_TROUBLE["signature"] == signature
            and now - _TROUBLE["when"] < STORM_SECONDS):
        return True
    _TROUBLE["signature"] = signature
    _TROUBLE["when"] = now
    return False


def is_ghost(err):
    """A call that arrived from a panel that no longer exists.

    Qt deletes the widget and leaves the Python object holding the connection,
    so a leftover from an earlier launch answers a signal and finds its own
    window gone. It reads as an error and is not one: there is nothing for the
    user to do about a thing that is already dead."""
    return isinstance(err, RuntimeError) and "has been deleted" in str(err)


def trouble(err, what, parent=None):
    """Log it, then put it in front of the user with something to try.

    Never raises. A reporter that can fail is a reporter that turns one bug
    into two, and the second one has nowhere to be reported."""
    try:
        log("%s failed: %s: %s" % (what, type(err).__name__, err))
        log(traceback.format_exc())
    except Exception:
        pass
    # A ghost gets a line, not a window. Versions 3.11 to 3.13 leave one
    # behind at every relaunch, and this function is reached even by their
    # code, because the console runs every version in the same namespace: so
    # this is also where their ghosts are put to rest.
    if is_ghost(err):
        try:
            log("%s came from a panel of an earlier launch and was ignored. "
                "Restart QGIS once to be rid of it for good." % what,
                loud=True)
        except Exception:
            pass
        return
    try:
        if in_a_storm(err, what):
            log("%s failed again: %s" % (what, err), loud=True)
            return
    except Exception:
        pass
    try:
        _TROUBLE["open"] = True
        window = Trouble(err, what, parent or window_of_qgis())
        window.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, False)
        run_dialog(window)
    except Exception:
        # The window itself could not be built: say it where something will
        # still be read, and carry on.
        try:
            QMessageBox.critical(None, NAME, "%s did not finish.\n\n%s: %s"
                                 % (what, type(err).__name__, err))
        except Exception:
            try:
                print("[%s] %s failed: %s" % (NAME, what, err))
            except Exception:
                # no console either: the log still has it
                log("%s failed: %s" % (what, err))
    finally:
        _TROUBLE["open"] = False
        _TROUBLE["when"] = time.time()


def window_of_qgis():
    try:
        return iface.mainWindow()
    except Exception:
        return None


def hook(owner, signal, handler):
    """Connect, and write down the connection so that it can be undone.

    A signal that belongs to the project, to the canvas or to a layer outlives
    the panel that listened to it. Qt does not mind: it keeps calling. So a
    second launch would leave the first panel still listening to layersAdded,
    and the first thing that added a layer would reach into a window whose C++
    side had been deleted an hour earlier. The Python object is still there,
    holding the connection alive; only the widget underneath is gone.

    Undoing a connection needs the very object that was connected, and since
    3.11 that object is a fresh wrapper made on the spot: disconnecting the
    bare method could never match it, and failed silently every time. It is
    remembered here instead."""
    signal.connect(handler)
    owner.__dict__.setdefault("_hooks", []).append((signal, handler))
    return handler


_OWN_HANDS = [0]


class own_hands(object):
    """A rollback or a removal of layers that RasterLabel does itself, on
    purpose: the No of its own "Save before closing?", a frame that could not
    be written taken back, a package let go of before it is moved.

    The panel listens for buffers emptied without a save, so that the recovery
    file of the work in them is kept instead of deleted, and it must be able to
    tell those apart from its own: QGIS asking "Save the changes?" on the way
    out and being told Discard looks, from a layer, exactly like the close
    without saving that was asked for here."""

    def __enter__(self):
        _OWN_HANDS[0] += 1
        return self

    def __exit__(self, *exc):
        _OWN_HANDS[0] -= 1
        return False


def by_own_hands():
    return _OWN_HANDS[0] > 0


def unhook(owner):
    """Let go of everything hook() wrote down. Never raises: this runs while
    something is already being taken apart."""
    gone = 0
    for signal, handler in owner.__dict__.pop("_hooks", []):
        try:
            signal.disconnect(handler)
            gone += 1
        except Exception:
            pass
    return gone


def alive(obj):
    """Whether the C++ side of a Qt object is still there.

    sip knows; without sip the question is asked of the object itself, and a
    dead one answers with the RuntimeError we are looking for."""
    if obj is None:
        return True                     # nothing to outlive
    try:
        from qgis.PyQt import sip
        return not sip.isdeleted(obj)
    except Exception:
        pass
    try:
        obj.objectName()
        return True
    except RuntimeError:
        return False
    except Exception:
        return True


def room_for(slot):
    """How many positional arguments this slot will actually take.

    None means as many as you like: the slot has a *args, or it is something
    whose signature cannot be read, and in both cases nothing has to be
    trimmed."""
    try:
        import inspect
        params = list(inspect.signature(slot).parameters.values())
    except (TypeError, ValueError, ImportError):
        return None
    for p in params:
        if p.kind == p.VAR_POSITIONAL:
            return None
    return sum(1 for p in params
               if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD))


def shielded(slot, what):
    """The same slot, with the error window behind it.

    Every button in every bar is connected through this. A command that
    raises would otherwise leave a traceback in the log panel and a user
    looking at a button that did nothing.

    The arguments are cut down to what the slot can hold, and that is not a
    nicety: it is what keeps every button working.
    clicked carries a bool. Connect a bound method that takes none and PyQt
    reads its signature and drops the bool for you; put a plain function with
    *args in between and PyQt sees something that will take anything, hands
    over the bool, and every command in the program dies on
    'takes 1 positional argument but 2 were given'. So the signature is read
    here instead, exactly where PyQt stopped being able to read it."""
    fits = room_for(slot)
    owner = getattr(slot, "__self__", None)

    def run(*args, **kwargs):
        # A leftover from a previous launch is not a failure to report: it is
        # a ghost, and the only right thing to do with it is nothing.
        if owner is not None and not alive(owner):
            log("%s ignored: it belongs to a panel that is gone" % what)
            return None
        try:
            return slot(*(args if fits is None else args[:fits]), **kwargs)
        except Exception as err:
            trouble(err, what)
    run.__name__ = getattr(slot, "__name__", "slot")
    run.wrapped = slot
    run.room = fits
    return run


def shield_tools(*classes):
    """Put the same net under what the mouse does on the canvas.

    A map tool that raises inside canvasPressEvent takes the exception into
    Qt, which prints it and carries on with the tool half through whatever it
    was doing. Wrapping the four entry points keeps that where it can be
    seen."""
    for cls in classes:
        for name in ("canvasPressEvent", "canvasMoveEvent",
                     "canvasReleaseEvent", "canvasDoubleClickEvent",
                     "keyPressEvent"):
            original = getattr(cls, name, None)
            if original is None or getattr(original, "shielded", False):
                continue
            wrapped = tool_net(original, cls.__name__, name)
            setattr(cls, name, wrapped)


def tool_net(original, tool_name, event_name):
    what = "%s (%s)" % (tool_name.replace("Tool", ""), event_name
                        .replace("canvas", "").replace("Event", "").lower())

    def run(self, *args, **kwargs):
        try:
            return original(self, *args, **kwargs)
        except Exception as err:
            trouble(err, what)
    run.shielded = True
    run.__name__ = event_name
    return run


def check_qgis():
    """Say, once, whether this QGIS is one the plugin knows.

    Older than what it was built on is allowed: most of it will work, and a
    refusal helps nobody who cannot upgrade today. But it is said out loud
    before the first thing goes wrong, because an unexplained failure two
    hours later is much worse than a warning now."""
    version = qgis_version()
    if version >= BUILT_FOR:
        log("QGIS %s, Qt %d: known ground" % (qgis_version_text(),
                                              qt_generation() or 5))
        return True
    if version == (0, 0):
        log("this QGIS does not say which version it is; carrying on")
        return True
    log("QGIS %s is older than the %d.%d %s this was built for"
        % (qgis_version_text(), BUILT_FOR[0], BUILT_FOR[1], BUILT_FOR_NAME),
        loud=True)
    return False


class OldQgis(Exception):
    """Raised only to be shown: it carries the version mismatch into the same
    window everything else uses, so there is one place where problems appear
    and not two."""
    pass


def warn_old_qgis():
    err = OldQgis(
        "QGIS %s is older than the %d.%d %s this plugin was written on."
        % (qgis_version_text(), BUILT_FOR[0], BUILT_FOR[1], BUILT_FOR_NAME))
    trouble(err, "Startup")

# ---------------------------------------------------------------------
# ---- stats -----------------------------------------------------------
# ---------------------------------------------------------------------

ST_NAN = float("nan")


def st_finite(values):
    """The values as a float array, with NaN and None left out."""
    out = []
    for v in values if values is not None else []:
        if v is None:
            continue
        try:
            f = float(v)
        except (TypeError, ValueError):
            continue
        if math.isfinite(f):
            out.append(f)
    return np.asarray(out, dtype=np.float64)


def st_spread(values):
    """Median, first and third quartile, and how many values were defined.

    Linear interpolation between the order statistics (Hyndman and Fan's type
    7, numpy's default), the same rule R's quantile() uses by default, so a
    reader checking a number in R gets the same number. A frame whose value
    is undefined is left out and not counted in n."""
    v = st_finite(values)
    if not v.size:
        return {"median": ST_NAN, "q1": ST_NAN, "q3": ST_NAN, "n": 0}
    q1, med, q3 = np.percentile(v, [25.0, 50.0, 75.0])
    return {"median": float(med), "q1": float(q1), "q3": float(q3),
            "n": int(v.size)}


def st_percentile_ci(samples, level=0.95):
    """(low, high) of the bootstrap replicates, by the percentile method.

    Efron's percentile interval (Efron and Tibshirani 1993, chapter 13): the
    (1 - level)/2 and (1 + level)/2 quantiles of the replicates. A replicate
    whose statistic is undefined is left out; with none left, both ends are
    NaN."""
    v = st_finite(samples)
    if not v.size:
        return (ST_NAN, ST_NAN)
    tail = (100.0 - level * 100.0) / 2.0
    lo, hi = np.percentile(v, [tail, 100.0 - tail])
    return (float(lo), float(hi))


def st_bootstrap_stat(values, fn, n_boot, seed, level=0.95, min_n=2):
    """A statistic of a sample with its bootstrap interval.

    The sample is drawn again n_boot times with replacement, the same size
    as itself, and fn is computed on each draw (Efron 1979). fn takes a float
    array and returns a number, NaN when it is undefined. What comes back
    says how it was done: the estimate on the sample itself, the interval or
    None, the number of replicates and the seed, how many replicates gave a
    defined value, and why there is no interval when there is none."""
    v = st_finite(values)
    out = {"estimate": float(fn(v)) if v.size else ST_NAN, "ci": None,
           "n": int(v.size), "n_boot": int(n_boot or 0), "seed": seed,
           "level": level, "n_valid": 0,
           "method": "percentile; resampled with replacement", "reason": ""}
    if not n_boot or n_boot <= 0:
        out["reason"] = "no resampling asked for"
        return out
    if v.size < max(1, min_n):
        out["reason"] = "fewer than %d values" % max(1, min_n)
        return out
    rng = np.random.default_rng(seed)
    idx = rng.integers(0, v.size, size=(int(n_boot), v.size))
    reps = np.array([fn(v[row]) for row in idx], dtype=np.float64)
    out["n_valid"] = int(np.isfinite(reps).sum())
    out["ci"] = list(st_percentile_ci(reps, level))
    return out


def _st_exact_upper(ranks2, w2):
    """P(W+ >= w) and P(W+ <= w) under the null, exactly.

    ranks2 are the ranks doubled, so a tie's half rank is a whole number, and
    w2 is W+ doubled the same way. Under the null hypothesis each rank is
    positive or negative with probability one half, independently, so the
    distribution of W+ is the count of the 2**n sign patterns giving each
    sum. That count is built one rank at a time, which is exact with ties as
    well as without, and cheap for the n <= 25 it is used for."""
    total = int(sum(ranks2))
    counts = np.zeros(total + 1, dtype=np.float64)
    counts[0] = 1.0
    for r in ranks2:
        r = int(r)
        shifted = np.zeros_like(counts)
        shifted[r:] = counts[:total + 1 - r]
        counts = counts + shifted
    counts /= counts.sum()
    w2 = int(round(w2))
    return float(counts[w2:].sum()), float(counts[:w2 + 1].sum())


def st_wilcoxon_signed(values, exact_max=25):
    """The Wilcoxon signed-rank test that the median of values is 0.

    Wilcoxon (1945). Zeros are dropped, as Wilcoxon did, and tied absolute
    values share their mean rank. W+ is the sum of the ranks of the positive
    values. Two-sided p: exact for up to exact_max non-zero values, from the
    full null distribution of W+; above that, the normal approximation with
    the tie correction of the variance and a continuity correction of one
    half. Five values all of one sign give W+ = 0 or 15 and p = 2/32."""
    v = st_finite(values)
    v = v[v != 0]
    n = int(v.size)
    out = {"n": n, "w_plus": ST_NAN, "w_minus": ST_NAN, "p": ST_NAN, "method": ""}
    if n == 0:
        out["method"] = "no value different from 0"
        return out
    a = np.abs(v)
    order = np.argsort(a, kind="mergesort")
    ranks = np.empty(n, dtype=np.float64)
    sorted_a = a[order]
    i = 0
    ties = []
    while i < n:
        j = i
        while j + 1 < n and sorted_a[j + 1] == sorted_a[i]:
            j += 1
        ranks[order[i:j + 1]] = (i + j) / 2.0 + 1.0
        if j > i:
            ties.append(j - i + 1)
        i = j + 1
    w_plus = float(ranks[v > 0].sum())
    out["w_plus"] = w_plus
    out["w_minus"] = float(ranks[v < 0].sum())
    if n <= exact_max:
        upper, lower = _st_exact_upper(np.round(ranks * 2).astype(int),
                                       w_plus * 2)
        out["p"] = min(1.0, 2.0 * min(upper, lower))
        out["method"] = "exact"
        return out
    mean = n * (n + 1) / 4.0
    var = n * (n + 1) * (2 * n + 1) / 24.0 - sum(t ** 3 - t for t in ties) / 48.0
    if var <= 0:
        out["method"] = "normal approximation: no variance"
        return out
    z = max(0.0, abs(w_plus - mean) - 0.5) / math.sqrt(var)
    out["p"] = min(1.0, math.erfc(z / math.sqrt(2.0)))
    out["method"] = "normal approximation, tie and continuity corrected"
    return out


def st_ratio_se(y, x, N=None):
    """A ratio of totals over clusters, and its standard error.

    The ratio estimator of Cochran (1977, section 6.3), with places (or
    frames) as the clusters: R = sum(y) / sum(x), and

        V(R) = (1 - m/N) * sum((y_i - R x_i)**2) / (m - 1) / (m * xbar**2)

    with m clusters in the sample and xbar = sum(x) / m. The finite
    population correction 1 - m/N is applied only when N, the number of
    clusters there are to draw from, is given; without it the same number is
    a spread between clusters, not a design-based standard error, and the
    caller has to say so. Fewer than two clusters: no standard error."""
    yy = np.asarray([float(v) for v in y], dtype=np.float64)
    xx = np.asarray([float(v) for v in x], dtype=np.float64)
    m = int(yy.size)
    out = {"R": ST_NAN, "se": ST_NAN, "m": m, "fpc": None}
    if m == 0 or xx.sum() <= 0:
        return out
    r = float(yy.sum() / xx.sum())
    out["R"] = r
    if m < 2:
        return out
    xbar = xx.sum() / m
    fpc = 1.0
    if N:
        fpc = max(0.0, 1.0 - m / float(N))
        out["fpc"] = fpc
    var = fpc * float(((yy - r * xx) ** 2).sum()) / (m - 1) / (m * xbar ** 2)
    out["se"] = math.sqrt(var)
    return out


def st_auc_hist(h_pos, h_neg):
    """The area under the ROC curve, from two histograms over the same levels.

    The probability that a level drawn from the positives is higher than one
    drawn from the negatives, ties counted one half: the Mann-Whitney U over
    the product of the two counts (Hanley and McNeil 1982). Here the levels
    are the uncertainty, the positives the pixels a person changed:

        AUC = sum_v Hpos[v] * (Cneg(<v) + Hneg[v] / 2) / (Npos * Nneg)

    NaN when either side is empty."""
    p = np.asarray(h_pos, dtype=np.float64)
    q = np.asarray(h_neg, dtype=np.float64)
    n_pos, n_neg = p.sum(), q.sum()
    if n_pos <= 0 or n_neg <= 0:
        return ST_NAN
    below = np.concatenate([[0.0], np.cumsum(q)[:-1]])
    return float((p * (below + 0.5 * q)).sum() / (n_pos * n_neg))


def st_ece(n, observed, expected):
    """Expected calibration error over bins.

    ECE = sum_b (n_b / N) |observed_b - expected_b| (Naeini, Cooper and
    Hauskrecht 2015; Guo et al. 2017): the gap between the error a model
    stated and the error found, weighted by how much of the map each bin
    holds. Bins with nothing in them are left out."""
    nn = np.asarray(n, dtype=np.float64)
    ob = np.asarray(observed, dtype=np.float64)
    ex = np.asarray(expected, dtype=np.float64)
    keep = (nn > 0) & np.isfinite(ob) & np.isfinite(ex)
    total = nn[keep].sum()
    if total <= 0:
        return ST_NAN
    return float((nn[keep] / total * np.abs(ob[keep] - ex[keep])).sum())


def st_decile_cuts(h_all, parts=10):
    """The levels that cut a histogram into parts of equal count.

    L_k = the lowest level whose cumulative count reaches k N / parts, for k
    = 1 .. parts-1. A level equal to a cut belongs to the lower part. Tied
    levels make cuts coincide, and they are kept once; a cut at the highest
    level present, or above it, separates nothing and is dropped. So three
    levels a third each give the cuts [0, 127], and three parts."""
    h = np.asarray(h_all, dtype=np.float64)
    total = h.sum()
    if total <= 0:
        return []
    cum = np.cumsum(h)
    top = int(np.nonzero(h)[0].max())
    cuts = set()
    for k in range(1, parts):
        target = k * total / parts
        level = int(np.searchsorted(cum, target - 1e-9 * total, side="left"))
        if level < top:
            cuts.add(level)
    return sorted(cuts)


def st_bin_of(levels, cuts):
    """The part each level falls in: how many cuts lie below it."""
    return np.searchsorted(np.asarray(cuts, dtype=np.int64),
                           np.asarray(levels), side="left")


def st_fixed_bin(levels, top=254, parts=10):
    """The fixed bin of a level: tenths of the scale, the last one closed."""
    v = np.asarray(levels, dtype=np.int64)
    return np.minimum(parts - 1, (v * parts) // top)


def st_calibration(h_all, h_chg, binning="decile", top=254, parts=10,
                   cuts=None):
    """The calibration curve as rows, one per bin that holds anything.

    h_all[v] counts the pixels at level v, h_chg[v] those of them a person
    changed. binning "decile" cuts by st_decile_cuts (or by the cuts given,
    so every scope can share the cuts of the whole map); "fixed" by tenths of
    the scale. Each row: bin, u_low and u_high (the lowest and highest level
    present, over top), n, changed, share = changed / n, and mean_u = the
    mean level over top."""
    h = np.asarray(h_all, dtype=np.float64)
    c = np.asarray(h_chg, dtype=np.float64)
    levels = np.arange(h.size)
    if binning == "fixed":
        bins = st_fixed_bin(levels, top, parts)
    else:
        if cuts is None:
            cuts = st_decile_cuts(h, parts)
        bins = st_bin_of(levels, cuts)
    rows = []
    for b in sorted(set(int(x) for x in bins[h > 0])):
        inside = (bins == b) & (h > 0)
        n = float(h[inside].sum())
        changed = float(c[inside].sum())
        present = levels[inside]
        rows.append({"bin": b, "u_low": float(present.min()) / top,
                     "u_high": float(present.max()) / top,
                     "n": int(round(n)), "changed": int(round(changed)),
                     "share": changed / n if n else ST_NAN,
                     "mean_u": float((levels[inside] * h[inside]).sum())
                     / (top * n) if n else ST_NAN})
    return rows


def st_capture(h_all, h_chg, tops=(0.01, 0.02, 0.05, 0.10, 0.20, 0.30,
                                   0.50, 1.00), top=254):
    """How much of the change the most uncertain part of the map holds.

    The levels are taken from the highest down, adding up area and changes.
    For each share t, the first level at which the area reached reaches t of
    the whole gives the threshold, the share of the area actually reached
    (ties at a level come whole), and the share of all the changes inside
    it."""
    h = np.asarray(h_all, dtype=np.float64)
    c = np.asarray(h_chg, dtype=np.float64)
    total, changes = h.sum(), c.sum()
    rows = []
    if total <= 0:
        return rows
    area = np.cumsum(h[::-1])
    caught = np.cumsum(c[::-1])
    for t in tops:
        k = int(np.searchsorted(area, t * total - 1e-9 * total, side="left"))
        k = min(k, area.size - 1)
        level = h.size - 1 - k
        rows.append({"top_share": t, "level": level,
                     "u_threshold": float(level) / top,
                     "share_of_area": float(area[k] / total),
                     "changed_captured": int(round(caught[k])),
                     "share_of_changes_captured":
                         float(caught[k] / changes) if changes > 0 else ST_NAN})
    return rows

# ---------------------------------------------------------------------
# ---- agreement -------------------------------------------------------
# ---------------------------------------------------------------------

CM_NAN = float("nan")

# The values of the disagreement map. The names and colours are in
# constants.DISAGREEMENT_CLASSES, which this module does not import.
CM_OUTSIDE = 0
CM_AGREE = 1
CM_DISAGREE = 2
CM_ONLY_A = 3
CM_ONLY_B = 4
CM_NEITHER = 5

# Past this many cells a bincount would spend more memory than the sort of
# np.unique costs in time.
CM_BINCOUNT_MAX = 1 << 22


def cm_codes(*groups):
    """One sorted list of whole codes out of any number of lists of them."""
    out = set()
    for g in groups:
        for c in g if g is not None else []:
            out.add(int(c))
    return sorted(out)


def _cm_whole(values, what):
    """values as int64, refusing anything that is not a whole number."""
    a = np.asarray(values).ravel()
    if a.dtype.kind == "f":
        if not np.all(np.isfinite(a)) or np.any(a != np.floor(a)):
            raise ValueError("%s holds a value that is not a class code" % what)
    elif a.dtype.kind not in "uib":
        raise ValueError("%s is not a band of class codes" % what)
    return a.astype(np.int64)


def _cm_index(values, codes, what):
    """Where each value sits in codes; ValueError on one that is not there."""
    k = codes.size
    idx = np.searchsorted(codes, values)
    bad = idx >= k
    bad |= codes[np.minimum(idx, k - 1)] != values
    if bad.any():
        raise ValueError("%s holds code %d, which is not in the list of codes"
                         % (what, int(values[bad][0])))
    return idx


def cm_confusion(a, b, codes):
    """The K x K matrix of pixel counts: rows the codes of a, columns of b.

    codes is the full list, sorted, unlabelled included where it counts as a
    row of its own. A code of a or b that is not in it is an error, not a
    pixel quietly dropped."""
    cs = np.asarray(cm_codes(codes), dtype=np.int64)
    if not cs.size:
        raise ValueError("no codes to count by")
    aa = _cm_whole(a, "A")
    bb = _cm_whole(b, "B")
    if aa.size != bb.size:
        raise ValueError("A and B do not have the same number of pixels")
    k = cs.size
    ia = _cm_index(aa, cs, "A")
    ib = _cm_index(bb, cs, "B")
    return np.bincount(ia * k + ib, minlength=k * k).reshape(k, k) \
        .astype(np.int64)


def cm_accumulate(pairs, a, b):
    """Add the (a, b) pairs of these pixels into the dict pairs, and return it.

    For maps whose codes are not known in advance: a thematic map in sixteen
    bits, codes past 255, negative codes. Small ranges are counted with one
    bincount over the offsets; anything wider with np.unique over one int64
    key per pixel, a in the high 32 bits and b in the low ones."""
    if pairs is None:
        pairs = {}
    aa = _cm_whole(a, "A")
    bb = _cm_whole(b, "B")
    if aa.size != bb.size:
        raise ValueError("A and B do not have the same number of pixels")
    if not aa.size:
        return pairs
    a0, a1 = int(aa.min()), int(aa.max())
    b0, b1 = int(bb.min()), int(bb.max())
    span_b = b1 - b0 + 1
    if (a1 - a0 + 1) * span_b <= CM_BINCOUNT_MAX:
        counts = np.bincount((aa - a0) * span_b + (bb - b0))
        for key in np.nonzero(counts)[0]:
            pair = (int(key // span_b) + a0, int(key % span_b) + b0)
            pairs[pair] = pairs.get(pair, 0) + int(counts[key])
        return pairs
    if min(a0, b0) < -(1 << 31) or max(a1, b1) >= (1 << 31):
        raise ValueError("a class code does not fit in 32 bits")
    keys = (aa << 32) | (bb & 0xFFFFFFFF)
    found, counts = np.unique(keys, return_counts=True)
    for key, n in zip(found.tolist(), counts.tolist()):
        low = key & 0xFFFFFFFF
        if low >= (1 << 31):
            low -= 1 << 32
        pair = (key >> 32, low)
        pairs[pair] = pairs.get(pair, 0) + int(n)
    return pairs


def cm_from_pairs(pairs, codes=None):
    """(M, codes) from a dict of pair counts, over the codes given and seen."""
    seen = set()
    for (ca, cb) in pairs:
        seen.add(int(ca))
        seen.add(int(cb))
    cs = cm_codes(codes, seen)
    where = {c: i for i, c in enumerate(cs)}
    m = np.zeros((len(cs), len(cs)), dtype=np.int64)
    for (ca, cb), n in pairs.items():
        m[where[int(ca)], where[int(cb)]] += int(n)
    return m, cs


def _cm_ratio(top, bottom):
    return float(top) / float(bottom) if bottom else CM_NAN


def cm_metrics(M, codes, unlabelled=0, kappa=False, pixel_m2=None):
    """Everything read off one confusion matrix, as plain numbers.

    unlabelled is the code that means "nobody painted it" (0 for two
    readings), or None when every code is a class (a thematic map). When it
    is given, its row and column are counted apart: only A painted, only B
    painted, neither did. Every rate is then taken over the pixels both
    painted, which is what agreement between two readings means. kappa adds
    Cohen's kappa; leave it out for a model. pixel_m2 adds the areas.

    Returned: counts, overall {n, po, pe, kappa?, quantity, allocation,
    exchange, shift, disagreement, mean_iou}, and per_class, one entry per
    class in code order with code, n_A, n_B, n_same, rate_A, rate_B, iou,
    f1, q, a, e, s. Undefined is NaN."""
    m = np.asarray(M, dtype=np.int64)
    cs = [int(c) for c in codes]
    if m.shape != (len(cs), len(cs)):
        raise ValueError("the matrix is %s but there are %d codes"
                         % (m.shape, len(cs)))
    u = cs.index(int(unlabelled)) \
        if unlabelled is not None and int(unlabelled) in cs else None
    keep = [i for i in range(len(cs)) if i != u]
    block = m[np.ix_(keep, keep)] if keep else np.zeros((0, 0), np.int64)
    n = int(block.sum())
    counts = {"total": int(m.sum()), "both": n}
    if u is not None:
        counts["only_A"] = int(m[keep, u].sum()) if keep else 0
        counts["only_B"] = int(m[u, keep].sum()) if keep else 0
        counts["neither"] = int(m[u, u])
    if pixel_m2:
        counts["m2"] = {k: v * float(pixel_m2) for k, v in counts.items()}
    k = len(keep)
    if n > 0:
        p = block / float(n)
        row = p.sum(axis=1)
        col = p.sum(axis=0)
        d = np.diag(p)
        po = float(d.sum())
        pe = float((row * col).sum())
        q = np.abs(row - col)
        a = 2.0 * np.minimum(row - d, col - d)
        pair_min = 2.0 * np.minimum(p, p.T)
        np.fill_diagonal(pair_min, 0.0)
        e = pair_min.sum(axis=1)
        quantity = float(q.sum() / 2.0)
        allocation = float(a.sum() / 2.0)
        exchange = float(e.sum() / 2.0)
        if abs(quantity + allocation - (1.0 - po)) > 1e-9:
            raise ArithmeticError("quantity plus allocation is not the "
                                  "disagreement: %r + %r != 1 - %r"
                                  % (quantity, allocation, po))
        overall = {"n": n, "po": po, "pe": pe, "quantity": quantity,
                   "allocation": allocation, "exchange": exchange,
                   "shift": allocation - exchange, "disagreement": 1.0 - po}
        if kappa:
            overall["kappa"] = (po - pe) / (1.0 - pe) \
                if abs(1.0 - pe) > 1e-12 else CM_NAN
    else:
        q = a = e = np.full(k, CM_NAN)
        overall = {"n": 0, "po": CM_NAN, "pe": CM_NAN, "quantity": CM_NAN,
                   "allocation": CM_NAN, "exchange": CM_NAN,
                   "shift": CM_NAN, "disagreement": CM_NAN}
        if kappa:
            overall["kappa"] = CM_NAN
    per_class = []
    ious = []
    for j, i in enumerate(keep):
        n_a = int(block[j, :].sum())
        n_b = int(block[:, j].sum())
        same = int(block[j, j])
        entry = {"code": cs[i], "n_A": n_a, "n_B": n_b, "n_same": same,
                 "rate_A": _cm_ratio(same, n_a),
                 "rate_B": _cm_ratio(same, n_b),
                 "iou": _cm_ratio(same, n_a + n_b - same),
                 "f1": _cm_ratio(2 * same, n_a + n_b),
                 "q": float(q[j]), "a": float(a[j]), "e": float(e[j]),
                 "s": float(a[j] - e[j])}
        if pixel_m2:
            entry["m2_A"] = n_a * float(pixel_m2)
            entry["m2_B"] = n_b * float(pixel_m2)
            entry["m2_same"] = same * float(pixel_m2)
        if n_a + n_b > 0:
            ious.append(entry["iou"])
        per_class.append(entry)
    # The mean over the classes either side painted: a class absent from
    # both says nothing about how well they agree on it.
    overall["mean_iou"] = float(sum(ious) / len(ious)) if ious else CM_NAN
    return {"codes": cs, "unlabelled": unlabelled, "counts": counts,
            "overall": overall, "per_class": per_class}


def cm_pair_dtype(K):
    """The narrowest unsigned type that holds every pair value of K codes.

    The values run 1 .. K*K, with 0 left for "outside", so a Byte holds
    them while K*K <= 255, that is up to 15 codes."""
    if K * K <= 255:
        return "uint8"
    if K * K <= 65535:
        return "uint16"
    return "uint32"


def cm_pair_values(a, b, codes, inside=None):
    """The pair map: 1 + i*K + j where A has codes[i] and B codes[j].

    0 outside the comparison. One encoding for every report: it holds any
    code of any width, and a value can be read back with cm_pair_of."""
    cs = np.asarray(cm_codes(codes), dtype=np.int64)
    k = cs.size
    aa = np.asarray(a)
    shape = aa.shape
    flat_a = aa.ravel()
    flat_b = np.asarray(b).ravel()
    mask = np.ones(flat_a.size, dtype=bool) if inside is None \
        else np.asarray(inside, dtype=bool).ravel()
    out = np.zeros(flat_a.size, dtype=cm_pair_dtype(k))
    if mask.any():
        ia = _cm_index(_cm_whole(flat_a[mask], "A"), cs, "A")
        ib = _cm_index(_cm_whole(flat_b[mask], "B"), cs, "B")
        out[mask] = 1 + ia * k + ib
    return out.reshape(shape)


def cm_pair_of(value, codes):
    """(code of A, code of B) for one value of the pair map, None for 0."""
    cs = cm_codes(codes)
    v = int(value)
    if v <= 0:
        return None
    i, j = divmod(v - 1, len(cs))
    if i >= len(cs):
        raise ValueError("%d is not a pair of %d codes" % (v, len(cs)))
    return (cs[i], cs[j])


def cm_disagreement_values(a, b, inside=None, unlabelled=0):
    """The disagreement map, one byte a pixel.

    0 outside, 1 both painted the same class, 2 both painted and differ,
    3 only A painted, 4 only B painted, 5 neither painted."""
    aa = np.asarray(a)
    bb = np.asarray(b)
    in_a = aa != unlabelled
    in_b = bb != unlabelled
    out = np.full(aa.shape, CM_NEITHER, dtype=np.uint8)
    out[in_a & in_b & (aa == bb)] = CM_AGREE
    out[in_a & in_b & (aa != bb)] = CM_DISAGREE
    out[in_a & ~in_b] = CM_ONLY_A
    out[~in_a & in_b] = CM_ONLY_B
    if inside is not None:
        out[~np.asarray(inside, dtype=bool)] = CM_OUTSIDE
    return out


def cm_coverage(values, inside=None, unlabelled=0):
    """The share of the pixels inside that carry a class."""
    v = np.asarray(values)
    mask = np.ones(v.shape, dtype=bool) if inside is None \
        else np.asarray(inside, dtype=bool)
    total = int(mask.sum())
    return _cm_ratio(int(((v != unlabelled) & mask).sum()), total)


def cm_stat_values(metrics):
    """The numbers of one cm_metrics result that get a spread and an interval.

    Flat, by name: the overall ones, and iou:<code> and f1:<code> per class.
    The same names are used for a frame, for the pooled matrix and for every
    bootstrap replicate, so they line up."""
    o = metrics["overall"]
    out = {}
    for key in ("po", "kappa", "quantity", "allocation", "exchange", "shift",
                "mean_iou"):
        if key in o:
            out[key] = o[key]
    for c in metrics["per_class"]:
        out["iou:%d" % c["code"]] = c["iou"]
        out["f1:%d" % c["code"]] = c["f1"]
    return out


def cm_bootstrap(Ms, stats, n_boot, seed, min_frames=5, level=0.95,
                 chunk=250):
    """Frame-level bootstrap intervals for the statistics of a pooled matrix.

    Ms is the stack of per-frame matrices, F x K x K. stats takes one pooled
    matrix and returns {name: value}. Each replicate draws F frames with
    replacement, which is a multinomial weight per frame (Efron 1979); the
    replicate's matrix is the weighted sum, computed with einsum a chunk of
    replicates at a time so memory stays bounded. The interval is the
    percentile one. Below min_frames frames there is no interval, and the
    reason says so."""
    stack = np.asarray(Ms, dtype=np.float64)
    f = int(stack.shape[0]) if stack.ndim == 3 else 0
    out = {"resamples": int(n_boot or 0), "seed": seed, "level": level,
           "method": "percentile; frames resampled with replacement",
           "min_frames": int(min_frames), "frames": f, "ci": None,
           "n_valid": {}, "reason": ""}
    if not n_boot or n_boot <= 0:
        out["reason"] = "no resampling asked for"
        return out
    if f < max(1, int(min_frames)):
        out["reason"] = "fewer than %d frames: no interval" % int(min_frames)
        return out
    rng = np.random.default_rng(seed)
    weights = rng.multinomial(f, [1.0 / f] * f, size=int(n_boot))
    reps = {}
    for start in range(0, int(n_boot), max(1, int(chunk))):
        pooled = np.einsum("bf,fij->bij", weights[start:start + chunk], stack)
        for one in pooled:
            for name, value in stats(np.rint(one).astype(np.int64)).items():
                reps.setdefault(name, []).append(value)
    out["ci"] = {name: list(st_percentile_ci(v, level))
                 for name, v in sorted(reps.items())}
    out["n_valid"] = {name: int(np.isfinite(np.asarray(v, dtype=np.float64))
                                .sum()) for name, v in sorted(reps.items())}
    return out


def cm_summarize(Ms, ids, codes, n_boot=2000, seed=1, unlabelled=0,
                 kappa=False, min_frames=5, pixel_m2=None, level=0.95):
    """Pooled values, the spread over frames and the bootstrap, in one go.

    Pooled: cm_metrics of the summed matrix, so pixels weigh equally. The
    spread: median and quartiles of each value frame by frame, so frames
    weigh equally; a frame where a value is undefined is left out of that
    value's n. The bootstrap: frame-level, as cm_bootstrap. With unlabelled
    given, a second, labelled block "with_unlabelled" has Po and kappa with
    unlabelled taken as a class of its own."""
    stack = np.asarray(Ms, dtype=np.int64)
    if stack.ndim != 3:
        stack = stack.reshape((0, len(codes), len(codes)))
    total = stack.sum(axis=0) if stack.shape[0] else \
        np.zeros((len(codes), len(codes)), dtype=np.int64)
    pooled = cm_metrics(total, codes, unlabelled, kappa, pixel_m2)
    frames = []
    values = {}
    for fid, one in zip(ids, stack):
        metrics = cm_metrics(one, codes, unlabelled, kappa, pixel_m2)
        frames.append({"id": fid, "metrics": metrics})
        for name, v in cm_stat_values(metrics).items():
            values.setdefault(name, []).append(v)
    out = {"pooled": pooled, "frames": frames,
           "spread": {name: st_spread(v) for name, v in sorted(values.items())},
           "bootstrap": cm_bootstrap(
               stack, lambda m: cm_stat_values(
                   cm_metrics(m, codes, unlabelled, kappa)),
               n_boot, seed, min_frames, level)}
    if unlabelled is not None:
        whole = cm_metrics(total, codes, None, True)["overall"]
        out["with_unlabelled"] = {"po": whole["po"], "kappa": whole["kappa"],
                                  "note": "unlabelled counted as a class"}
    return out


def cm_name(code, names, unlabelled=0):
    """The word for a code: its class, "unlabelled", or "code N (not in the
    legend)" for a code the classes do not hold."""
    if code in names:
        return names[code]
    if unlabelled is not None and code == unlabelled:
        return "unlabelled"
    return "code %d (not in the legend)" % code


def cm_wide_rows(M, codes, names, unlabelled=0, corner="A \\ B"):
    """The matrix as rows of a table: a header, then one row per code of A."""
    cs = [int(c) for c in codes]
    head = [corner] + ["%d %s" % (c, cm_name(c, names, unlabelled))
                       for c in cs]
    rows = [head]
    m = np.asarray(M)
    for i, c in enumerate(cs):
        rows.append(["%d %s" % (c, cm_name(c, names, unlabelled))]
                    + [int(v) for v in m[i]])
    return rows


def cm_long_rows(M, codes, names, tile_id="ALL", unlabelled=0,
                 pixel_m2=None):
    """The non-empty cells as long rows: tile_id, code_A, name_A, code_B,
    name_B, pixels, area_m2 (empty when the pixel area is not known)."""
    cs = [int(c) for c in codes]
    m = np.asarray(M)
    rows = []
    for i, ca in enumerate(cs):
        for j, cb in enumerate(cs):
            n = int(m[i, j])
            if not n:
                continue
            rows.append([tile_id, ca, cm_name(ca, names, unlabelled), cb,
                         cm_name(cb, names, unlabelled), n,
                         n * float(pixel_m2) if pixel_m2 else None])
    return rows


def cm_jsonable(obj):
    """obj with NaN turned into None and numpy numbers into Python ones, so
    json.dumps writes null where a value is undefined."""
    if isinstance(obj, dict):
        return {str(k): cm_jsonable(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [cm_jsonable(v) for v in obj]
    if isinstance(obj, np.ndarray):
        return cm_jsonable(obj.tolist())
    if isinstance(obj, np.integer):
        return int(obj)
    if isinstance(obj, (float, np.floating)):
        f = float(obj)
        return f if math.isfinite(f) else None
    return obj


def cm_dumps(obj):
    """obj as JSON text, NaN written as null, keys sorted."""
    return json.dumps(cm_jsonable(obj), sort_keys=True, indent=1,
                      ensure_ascii=False, allow_nan=False)

# ---------------------------------------------------------------------
# ---- reports ---------------------------------------------------------
# ---------------------------------------------------------------------

def report_utc(when=None):
    """A moment as UTC ISO text to the second, with a Z: 2026-10-08T17:30:00Z."""
    when = when or datetime.now(timezone.utc)
    if when.tzinfo is None:
        when = when.astimezone(timezone.utc)
    return when.astimezone(timezone.utc).replace(microsecond=0) \
        .isoformat().replace("+00:00", "Z")


def report_stamp(when=None):
    """The stamp in a report's folder name, local time: 20261008-1930 to the
    second, 20261008-193005, so two runs a minute apart do not collide."""
    return (when or datetime.now()).strftime("%Y%m%d-%H%M%S")


def report_stem(label=None, when=None):
    """<label>_<stamp>, or the stamp alone: the name a report folder starts
    from, before a -2 is added to it."""
    stem = report_stamp(when)
    if label:
        stem = "%s_%s" % (tidy(str(label), "report"), stem)
    return stem


def report_folder(owner_folder, kind, label=None, when=None):
    """(tmp, final) for a new report of this kind, with tmp made and empty.

    final does not exist and nothing ending in .tmp under that name does
    either: the first free one of <label>_<stamp>, <label>_<stamp>-2, and so
    on. The caller writes into tmp, then calls report_finish(tmp, final), or
    report_abandon(tmp) when the run fails or is cancelled."""
    if kind not in REPORT_SHORT:
        raise ValueError("%r is not a kind of report" % (kind,))
    base = os.path.join(owner_folder, REPORTS_FOLDER, kind)
    stem = report_stem(label, when)
    for n in range(1, 1000):
        name = stem if n == 1 else "%s-%d" % (stem, n)
        final = os.path.join(base, name)
        tmp = final + REPORT_TMP
        if os.path.exists(long_path(final)) or os.path.exists(long_path(tmp)):
            continue
        try:
            os.makedirs(long_path(tmp))
        except FileExistsError:
            continue
        return tmp, final
    raise OSError("no free name for a report in %s" % base)


# QGIS opens a GeoPackage through SQLite, and SQLite on Windows cannot open a
# path of 260 characters or more, the long form with the \\?\ prefix that
# GDAL writes it through included: probed on QGIS 3.36, 3.44 and 4.2, the file was written and the
# layer then said it was not valid ("sqlite3_open ... unable to open
# database file"). A GeoTIFF, a GeoJSON and a .qml are opened through GDAL
# and Qt, which reach past 260 characters, and give no trouble. The 8.3 name
# of a folder would get round it, but only on a volume that keeps them, and
# a report that loads on one machine and not on another is worse than one
# that says at once where it cannot go.
SQLITE_FILES = (".gpkg", ".sqlite", ".sqlite3", ".db")
WINDOWS_PATH_MAX = 259
# SQLite keeps a side file beside the one it opens: -wal and -shm, or, when
# QGIS edits a GeoPackage through a rollback journal as 3.36 does,
# -journal, eight characters more. Start editing and Save edits on a path
# that left no room for it failed with "unable to open database file", the
# layer having loaded and read well. A report that finds its name taken is
# finished as <name>-2... -99: three more in the folder's name, which the
# name of the file is under.
SQLITE_SIDE_FILES = len("-journal")
REPORT_RENUMBER = len("-99")


def report_folder_guess(owner_folder, kind, label=None, target=None,
                        when=None):
    """Where a report is going to end up, as far as it can be known before
    anything is made: the folder the person named, or the one report_folder
    would make. A name taken in the meantime adds -2, which report_open_
    problem leaves room for."""
    if target:
        return str(target)
    return os.path.join(owner_folder, REPORTS_FOLDER, kind,
                        report_stem(label, when))


def report_open_problem(folder, names, windows=None):
    """"" if QGIS will be able to open every one of the files named in this
    folder, or, in plain words, why it will not and what to do.

    names are the files the report is to write and QGIS is to load. Only a
    SQLite file (a GeoPackage) is held to a length, and only on Windows;
    windows=True asks the question as Windows answers it, which is how the
    suites ask it on a machine that is not one."""
    if windows is None:
        windows = os.name == "nt"
    if not windows:
        return ""
    room = WINDOWS_PATH_MAX - SQLITE_SIDE_FILES - REPORT_RENUMBER
    worst = None
    for name in names or []:
        if os.path.splitext(str(name))[1].lower() not in SQLITE_FILES:
            continue
        n = len(os.path.join(os.path.abspath(str(folder)), str(name)))
        if n > room and (worst is None or n > worst[0]):
            worst = (n, str(name))
    if worst is None:
        return ""
    return ("The GeoPackage of this report, %s, would be at %d characters of "
            "path, and QGIS cannot open and edit one of more than %d on "
            "Windows: the layers would not load, or could not be edited. "
            "Choose a shorter folder for the report, "
            "or move the campaign closer to the root of the drive, %d "
            "characters shorter at least."
            % (worst[1], worst[0], room, worst[0] - room))


def report_finish(tmp, final):
    """Put a complete report in place, and return where it went.

    A folder that took the name in the meantime (another QGIS on the same
    campaign) is left alone, and the report takes the next free name."""
    target = final
    n = 1
    while os.path.exists(long_path(target)):
        n += 1
        target = "%s-%d" % (final, n)
    os.rename(long_path(tmp), long_path(target))
    return target


def report_abandon(tmp):
    """Remove a report that was not finished. Only a folder whose name ends
    in .tmp is ever removed here: a finished report is never touched."""
    if not tmp or not str(tmp).endswith(REPORT_TMP):
        return False
    if os.path.isdir(long_path(tmp)):
        shutil.rmtree(long_path(tmp), ignore_errors=True)
    return not os.path.exists(long_path(tmp))


def _report_piece(text):
    """One piece of the name of a map of a report, made safe for a path
    and never cut: [^A-Za-z0-9_-] runs become one _, as tidy() does."""
    return re.sub(r"[^A-Za-z0-9_\-]+", "_", str(text or "")).strip("_")


# The longest name a map of a report is given, its extension included: a
# file name may not pass 255 characters on Windows, macOS or Linux, and a
# little room is left for the .aux.xml GDAL writes beside a raster.
REPORT_NAME_ROOM = 240


def report_artifact_name(owner_stem, kind, label, part, ext):
    """The name of a raster or a vector of a report.

    <owner stem>_<kind short>_<label>_<part><ext>: the tables inside a
    report folder have short fixed names, but a map is copied out, into a
    paper's figure folder or a colleague's QGIS, and there it has to say
    what it is on its own.

    It is never cut at a fixed length. Sending the whole through tidy(),
    which stops at 48 letters, would give two long readings one name for their
    disagreement map and their map of pairs, cut before _disagreement and
    _pairs. The owner's stem is the stem of a file already on disk, and is
    kept as it is; the label and the part are made safe for a path. Only a
    name that would not fit in REPORT_NAME_ROOM loses the end of its label,
    which is then followed by eight letters of its SHA-1, so two labels
    never meet in one name, and the part and the extension are always
    whole."""
    stem = str(owner_stem or "") or kind
    head = [stem, REPORT_SHORT.get(kind, kind)]
    label = _report_piece(label)
    tail = [_report_piece(part)] if _report_piece(part) else []
    name = "_".join(head + ([label] if label else []) + tail) + ext
    if len(name) <= REPORT_NAME_ROOM or not label:
        return name
    # a mark in a file name, no security (see tidy_tag)
    mark = hashlib.sha1(label.encode("utf-8"),
                        usedforsecurity=False).hexdigest()[:8]
    room = REPORT_NAME_ROOM - (len(name) - len(label)) - len(mark) - 1
    short = label[:max(room, 1)].rstrip("_-") or label[:1]
    return "_".join(head + ["%s_%s" % (short, mark)] + tail) + ext


def report_header(kind, owner):
    """The block every summary.json starts with.

    owner is {kind: campaign|correction, id, name, folder}. The build is the
    fingerprint of the bytes that wrote the report, which is what a reader
    needs to find the exact code again."""
    return {"rasterlabel:report": kind, "report_format": REPORT_FORMAT,
            "program": NAME, "version": VERSION, "build": BUILD,
            "created_utc": report_utc(),
            "owner": {"kind": owner.get("kind", ""),
                      "id": owner.get("id", ""),
                      "name": owner.get("name", ""),
                      "folder": owner.get("folder", "")}}


def report_sha256(path, chunk=1 << 20):
    """The SHA-256 of a file, read a MiB at a time, or None if it cannot be
    read."""
    digest = hashlib.sha256()
    try:
        with open(long_path(path), "rb") as fh:
            while True:
                block = fh.read(chunk)
                if not block:
                    break
                digest.update(block)
    except OSError:
        return None
    return digest.hexdigest()


def report_inputs(paths, folder=None):
    """What a report was made from: path, sha256, bytes and mtime of each.

    A file that is not there is listed with null in place of the numbers, so
    the summary says it was looked for.

    With folder, the one the report is written for, a file inside it is named
    by its way from there: a summary that is zipped and sent does not carry
    the name of whoever made it in every line. Without it the whole path,
    which is what the files as they are now are compared with."""
    out = []
    for p in paths:
        shown = inside_folder(p, folder) if folder else p
        try:
            st = os.stat(long_path(p))
            out.append({"path": shown, "sha256": report_sha256(p),
                        "bytes": int(st.st_size),
                        "mtime_utc": report_utc(datetime.fromtimestamp(
                            st.st_mtime, timezone.utc))})
        except OSError:
            out.append({"path": shown, "sha256": None, "bytes": None,
                        "mtime_utc": None})
    return out


def report_clean(obj):
    """obj made fit for JSON: NaN and infinity as None, tuples as lists,
    sets sorted, numpy numbers as Python ones (through their .item())."""
    if isinstance(obj, dict):
        return {str(k): report_clean(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [report_clean(v) for v in obj]
    if isinstance(obj, (set, frozenset)):
        return [report_clean(v) for v in sorted(obj, key=str)]
    if hasattr(obj, "tolist") and not isinstance(obj, (str, bytes)):
        return report_clean(obj.tolist())
    if hasattr(obj, "item") and not isinstance(obj, (str, bytes)):
        obj = obj.item()
    if isinstance(obj, bool) or obj is None:
        return obj
    if isinstance(obj, float):
        return obj if math.isfinite(obj) else None
    return obj


def report_cell(value):
    """One CSV cell: empty for None and NaN, floats as %.12g, the rest as
    text. Booleans are written 1 and 0, which every reader takes."""
    if value is None:
        return ""
    if hasattr(value, "item") and not isinstance(value, (str, bytes)):
        value = value.item()
    if isinstance(value, bool):
        return "1" if value else "0"
    if isinstance(value, float):
        return "%.12g" % value if math.isfinite(value) else ""
    return csv_text(str(value))


def _report_replace(path, write):
    """Write through a .partial beside path, then move it into place."""
    partial = path + ".partial"
    try:
        write(partial)
        os.replace(long_path(partial), long_path(path))
    except BaseException:
        try:
            os.remove(long_path(partial))
        except OSError:
            pass
        raise
    return path


def report_csv(path, header, rows):
    """A table as CSV, atomically, in the conventions above."""
    def write(target):
        with io.open(long_path(target), "w", encoding="utf-8",
                     newline="") as fh:
            out = csv.writer(fh, lineterminator="\n")
            if header:
                out.writerow([csv_text(str(h)) for h in header])
            for row in rows:
                out.writerow([report_cell(v) for v in row])
    return _report_replace(path, write)


def report_homeless(obj):
    """obj with the home folder of whoever is running written ~ in every
    text: a report is zipped and sent, and the folders it names (the owner's,
    a source map's) are under it."""
    if isinstance(obj, dict):
        return {k: report_homeless(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [report_homeless(v) for v in obj]
    if isinstance(obj, str):
        return without_home(obj)
    return obj


def report_json(path, obj):
    """obj as JSON, atomically: NaN as null, keys sorted, one space indent."""
    text = json.dumps(report_homeless(report_clean(obj)), sort_keys=True,
                      indent=1,
                      ensure_ascii=False, allow_nan=False) + "\n"
    return report_text(path, text)


def report_text(path, text):
    """Text as a UTF-8 file with "\\n" line ends, atomically."""
    def write(target):
        with io.open(long_path(target), "w", encoding="utf-8",
                     newline="\n") as fh:
            fh.write(text)
    return _report_replace(path, write)


def report_headline(kind, values):
    """The headline of a report, with exactly the keys fixed for its kind.

    A key the writer did not give is there as None; a key it gave that is
    not on the list is left out, so the card can rely on the shape."""
    keys = REPORT_HEADLINES.get(kind, ())
    return {k: values.get(k) for k in keys}


def report_entry(kind, report_id, label, created_utc, folder, headline):
    """One entry of data["reports"]: what the manifest remembers of a report.

    folder is relative to the owner's folder, with forward slashes, so the
    entry still points at the report after the whole campaign is moved."""
    return {"kind": kind, "id": report_id, "label": label or "",
            "created_utc": created_utc,
            "folder": str(folder).replace("\\", "/"),
            "headline": report_clean(headline or {})}


def report_register(data, entry, kept=REPORTS_KEPT):
    """Add entry to data["reports"], keeping the newest kept of its kind.

    The manifest is the campaign's or the correction's, and the caller saves
    it the usual way (Campaign.save, CorrectionCampaign.save). The report
    folders themselves are never removed here: only the list is trimmed."""
    reports = data.setdefault("reports", [])
    reports.append(entry)
    same = [i for i, e in enumerate(reports) if e.get("kind") == entry["kind"]]
    drop = set(same[:max(0, len(same) - kept)])
    data["reports"] = [e for i, e in enumerate(reports) if i not in drop]
    return entry


def report_newest(data, kind):
    """The newest entry of this kind in data["reports"], or None."""
    found = [e for e in data.get("reports") or [] if e.get("kind") == kind]
    return found[-1] if found else None


def report_missing(data, owner_folder):
    """The entries of data["reports"] whose folder is not there any more."""
    out = []
    for e in data.get("reports") or []:
        rel = e.get("folder") or ""
        if not rel or not os.path.isdir(long_path(
                os.path.join(owner_folder, *rel.split("/")))):
            out.append(e)
    return out


def report_read(path):
    """A summary.json read back, or None when it is missing or not JSON."""
    try:
        with io.open(long_path(path), encoding="utf-8") as fh:
            return json.load(fh)
    except (OSError, ValueError):
        return None


def report_find(owner_folder, kind, owner_id, name=REPORT_SUMMARY):
    """The finished reports of this kind made of this owner, newest first.

    Each is (folder, summary). A report counts only when its summary says it
    is of this kind and was made of the owner with this id: a folder copied
    in from another campaign, or a file somebody named summary.json, is not
    mistaken for one. Folders still ending in .tmp are not finished and are
    skipped."""
    base = os.path.join(owner_folder, REPORTS_FOLDER, kind)
    try:
        names = os.listdir(long_path(base))
    except OSError:
        return []
    found = []
    for n in names:
        if n.endswith(REPORT_TMP):
            continue
        folder = os.path.join(base, n)
        summary = report_read(os.path.join(folder, name))
        if not isinstance(summary, dict):
            continue
        if summary.get("rasterlabel:report") != kind:
            continue
        if (summary.get("owner") or {}).get("id") != owner_id:
            continue
        found.append((summary.get("created_utc") or "", n, folder, summary))
    found.sort(key=lambda t: (t[0], t[1]), reverse=True)
    return [(folder, summary) for _, _, folder, summary in found]


def _report_same_path(a, b):
    # ~ is the home folder the report was written with (see report_homeless)
    norm = lambda p: os.path.normcase(os.path.normpath(os.path.abspath(
        os.path.expanduser(p))))
    return norm(a) == norm(b)


def _report_way_ends(current, way):
    """Whether the file current is at the end of way, a path a report wrote
    down relative to the folder it was made for."""
    if not way or os.path.isabs(way) or way.startswith("~"):
        return False
    tail = os.path.normcase(os.path.normpath(way))
    full = os.path.normcase(os.path.normpath(current))
    return full.endswith(os.sep + tail)


def report_stale(summary, current):
    """(stale, reason): whether the files a report was made from have changed.

    current lists the files as they are now, in the shape of report_inputs.
    An input whose sha256 was recorded is stale when the sha differs; one
    recorded without a sha is compared by mtime. A file matched by full path
    first, by name second, so a campaign moved to another disk is still
    recognised. An input that is now missing makes the report stale too."""
    now = list(current or [])
    for old in (summary or {}).get("inputs") or []:
        path = old.get("path") or ""
        match = [c for c in now if _report_same_path(c.get("path", ""), path)
                 or _report_way_ends(c.get("path", ""), path)]
        if not match:
            base = os.path.basename(path)
            match = [c for c in now
                     if os.path.basename(c.get("path", "")) == base]
        if not match:
            continue
        cur = match[0]
        if cur.get("sha256") is None and cur.get("mtime_utc") is None:
            return True, "%s is not there any more" % os.path.basename(path)
        if old.get("sha256") and cur.get("sha256"):
            if old["sha256"] != cur["sha256"]:
                return True, "%s has changed since" % os.path.basename(path)
            continue
        if old.get("mtime_utc") and cur.get("mtime_utc") \
                and cur["mtime_utc"] > old["mtime_utc"]:
            return True, "%s is newer than the report" % os.path.basename(path)
    return False, ""


def report_describe(entry):
    """One quiet line about a report entry, for a tally or a tooltip."""
    when = (entry.get("created_utc") or "").replace("T", " ").rstrip("Z")
    words = entry.get("kind", "report").replace("_", " ")
    if entry.get("label"):
        words += " " + str(entry["label"]).replace("_", " ")
    return "%s, %s UTC" % (words, when[:16]) if when else words

# ---------------------------------------------------------------------
# ---- view ------------------------------------------------------------
# ---------------------------------------------------------------------

#  Navigation
# =====================================================================
def step(dx, dy, percent, long_step=False):
    c = canvas()
    e = c.extent()
    f = percent / 100.0 * (LONG_STEP if long_step else 1)
    p = c.center()
    c.setCenter(QgsPointXY(p.x() + dx * e.width() * f, p.y() + dy * e.height() * f))
    c.refresh()


def zoom(inwards):
    c = canvas()
    factor = 1.0 / ZOOM_FACTOR if inwards else ZOOM_FACTOR
    try:
        c.zoomByFactor(factor)
    except Exception:
        e = c.extent()
        w, h = e.width() * factor / 2.0, e.height() * factor / 2.0
        p = c.center()
        c.setExtent(QgsRectangle(p.x() - w, p.y() - h, p.x() + w, p.y() + h))
    c.refresh()

# ---------------------------------------------------------------------
# ---- layout ----------------------------------------------------------
# ---------------------------------------------------------------------

class FlowLayout(QLayout):
    """Lays its buttons out left to right and wraps when the row is full.

    Qt has no layout of this kind, and the panel needs one. It can be widened,
    narrowed, torn out of the frame and dropped on a second screen, and a
    layout worked out once at build time is a guess that goes wrong the first
    time somebody drags the edge. This one is asked again at every resize.

    Groups are kept apart by a wider gap, and the gap is dropped when the
    group happens to start a row, where the edge already separates it.

    With uniform on it stops being a ragged flow and becomes a grid: every
    button is given the width of the longest word among them, the row holds as
    many as the panel is wide enough for, and what is left over is shared out
    so the columns meet the edge. Two of them at three hundred pixels, three at
    four hundred, four at five: the count follows the drag, the buttons keep
    the same size as each other whatever it turns out to be. A group gap would
    put the columns out of line, so in this mode there is none; what divides
    one kind of command from another is the frame around it.

    counts, in the grid, is the column counts it may use, when only some of
    them make a clean shape: six commands written as two rows of three read
    well in three columns or in six, and in five they leave one alone on a
    row of its own; two modules side by side are halves of the row or one
    over the other. The grid then takes the largest of them that fits, and
    only falls back to whatever fits when none of them does. A short last
    row in such a grid is spread over the whole width, so the shape never
    ends in a hole."""

    def __init__(self, spacing=4, gap=GROUP_GAP, uniform=False, counts=()):
        super().__init__()
        self.items = []
        self.extra = {}
        self.gap = gap
        self.uniform = uniform
        self.counts = tuple(sorted(counts))
        self._spacing = spacing
        self.setContentsMargins(0, 0, 0, 0)

    # ---- the six methods a QLayout has to answer
    def addItem(self, item):
        self.items.append(item)

    def count(self):
        return len(self.items)

    def itemAt(self, i):
        return self.items[i] if 0 <= i < len(self.items) else None

    def takeAt(self, i):
        return self.items.pop(i) if 0 <= i < len(self.items) else None

    def expandingDirections(self):
        return Qt.Orientation(0)        # neither direction

    def sizeHint(self):
        return self.minimumSize()

    def minimumSize(self):
        """The widest single button: below that nothing can be laid out at
        all, and the panel must be allowed to say so."""
        size = QSize(0, 0)
        for item in self.items:
            size = size.expandedTo(item.minimumSize())
        if self.uniform and self.items:
            size = size.expandedTo(QSize(*self.cell()))
        margins = self.contentsMargins()
        return size + QSize(margins.left() + margins.right(),
                            margins.top() + margins.bottom())

    def cell(self):
        """One cell of the grid: as wide as the longest word needs, as tall as
        the tallest button.

        The width is read from each button's own minimum rather than from its
        hint, because a button let out of its fixed size to be stretched still
        remembers, in that minimum, exactly how much room its word asked for.
        Ask the hint instead and Qt answers with the style's idea of a button,
        which is wider, and the grid grows a little every time it is measured."""
        width = height = 0
        for item in self.items:
            hint = item.sizeHint()
            widget = item.widget()
            want = widget.minimumWidth() if widget is not None else 0
            width = max(width, want or hint.width())
            height = max(height, hint.height())
        return width, height

    def hasHeightForWidth(self):
        return True

    def heightForWidth(self, width):
        return self._lay(QRect(0, 0, width, 0), True)

    def setGeometry(self, rect):
        super().setGeometry(rect)
        self._lay(rect, False)

    # ---- adding
    def add(self, widget, new_group=False):
        if new_group and self.items:
            self.extra[len(self.items)] = self.gap
        if self.uniform:
            # dress() nails a button to the width of its word. In the grid the
            # width is decided by the row, so the ceiling has to come off;
            # the floor stays, and is what cell() reads back.
            widget.setMinimumWidth(widget.minimumWidth() or widget.width()
                                   or widget.sizeHint().width())
            widget.setMaximumWidth(FREE_W)
        self.addWidget(widget)

    def _lay(self, rect, measure_only):
        if self.uniform:
            return self._grid(rect, measure_only)
        margins = self.contentsMargins()
        left = rect.x() + margins.left()
        right = rect.right() - margins.right()
        x, y, line = left, rect.y() + margins.top(), 0
        for i, item in enumerate(self.items):
            hint = item.sizeHint()
            before = self.extra.get(i, 0) if x > left else 0
            if line and x + before + hint.width() > right + 1:
                x, y, line, before = left, y + line + self._spacing, 0, 0
            if not measure_only:
                item.setGeometry(QRect(x + before, y, hint.width(), hint.height()))
            x += before + hint.width() + self._spacing
            line = max(line, hint.height())
        return y + line - rect.y() + margins.bottom()

    def columns(self, room):
        """How many buttons fit across, given that much room. Never none, and
        never more than there are buttons to put in them."""
        cell_w = self.cell()[0]
        if not self.items or cell_w <= 0:
            return 1
        fit = int((room + self._spacing) // (cell_w + self._spacing))
        fit = max(1, min(fit, len(self.items)))
        allowed = [n for n in self.counts if n <= fit]
        return allowed[-1] if allowed else fit

    def _grid(self, rect, measure_only):
        """The same buttons, all one size, in as many columns as fit.

        The leftover pixels of a row are shared out one each from the left
        instead of being dropped at the end, so the last column lands exactly
        on the edge and no column is ever more than a pixel wider than its
        neighbour. Stretching has a ceiling: on a wide screen six commands
        should not become six banners, so past WIDE_CELL times their word they
        stop growing and the row simply ends where it ends.

        Except in a grid held to its counts: there the keys are wider than
        their words on purpose, to keep a shape, and every row of the shape
        meets the edge, the way the rows of the panel's blocks do one under
        the other."""
        margins = self.contentsMargins()
        left = rect.x() + margins.left()
        top = rect.y() + margins.top()
        room = rect.width() - margins.left() - margins.right()
        cell_w, cell_h = self.cell()
        if not self.items:
            return margins.top() + margins.bottom()
        cols = self.columns(room)
        rows = (len(self.items) + cols - 1) // cols
        spread = room - self._spacing * (cols - 1)
        wide, rest = divmod(max(spread, cell_w * cols), cols)
        ceiling = int(cell_w * WIDE_CELL)
        if wide > ceiling and not self.counts:
            wide, rest = ceiling, 0
        if not measure_only:
            short = len(self.items) - (rows - 1) * cols
            for i, item in enumerate(self.items):
                r, c = divmod(i, cols)
                width, extra = wide, rest
                if self.counts and r == rows - 1 and short < cols:
                    # The last row of a keypad held to its shape, when it is
                    # short: its keys share the whole row instead of leaving
                    # a hole at the end of it. Five keys are three and two,
                    # the two half a row each, and nothing is ever left alone
                    # on a row of its own with the edge a cell away.
                    width, extra = divmod(
                        max(room - self._spacing * (short - 1),
                            cell_w * short), short)
                x = left + sum(width + (1 if k < extra else 0) + self._spacing
                               for k in range(c))
                item.setGeometry(QRect(x, top + r * (cell_h + self._spacing),
                                       width + (1 if c < extra else 0), cell_h))
        return (rows * cell_h + (rows - 1) * self._spacing
                + margins.top() + margins.bottom())


class KeyRow(QLayout):
    """One row of keys that shares the width it is given, and keeps every
    word whole.

    The keys share the row equally whenever an equal share holds the longest
    word among them, which is the keypad's shape and what every row looks
    like at the widths most panels have. A narrower row, or a font larger
    than the one the keypad was drawn for (DejaVu at twelve points, as a
    Linux desktop gives it, is half as wide again as Segoe UI at nine), and
    the equal shares would cut the longest word: then each key gets what its
    own word needs and the room left over is shared out equally, so the row
    still meets both edges. Only when even that does not fit does the row
    wrap onto a second line.

    With a filler, the first widget added (the list of frames beside Go, Note
    and Delete), the keys keep one width, the one they were dressed to when
    there is room for it, and the filler takes what they leave. Short of
    room the keys come down to the width their words need, and the filler
    to its least.

    need(widget) is the least width that keeps a key's word whole with the
    air the style keeps round it, least(widget) the width under which the
    word would touch the frame: a row short of room for the first comes
    down to the second before it wraps. Both are asked again at every
    pass, so a theme that pads the buttons is measured as it is."""

    def __init__(self, need, spacing=4, filler=False, least=None):
        super().__init__()
        self.items = []
        self.need = need
        self.least = least or need
        self.filler = filler
        self.dressed = {}
        self._spacing = spacing
        self.setContentsMargins(0, 0, 0, 0)

    def addItem(self, item):
        self.items.append(item)

    def count(self):
        return len(self.items)

    def itemAt(self, i):
        return self.items[i] if 0 <= i < len(self.items) else None

    def takeAt(self, i):
        return self.items.pop(i) if 0 <= i < len(self.items) else None

    def expandingDirections(self):
        return Qt.Orientation(0)

    def add(self, widget):
        """A key, or with filler on, the filler first. A key nailed to the
        width of its word by dress() is let out of it: the row decides."""
        if not (self.filler and not self.items):
            self.dressed[id(widget)] = widget.width() or widget.minimumWidth()
            widget.setMinimumWidth(0)
            widget.setMaximumWidth(FREE_W)
        self.addWidget(widget)

    def _parts(self):
        widgets = [item.widget() for item in self.items]
        if self.filler and widgets:
            return widgets[0], widgets[1:]
        return None, widgets

    def _needs(self, keys, least=False):
        fn = self.least if least else self.need
        return [max(1, int(fn(k))) for k in keys]

    def _height(self):
        return max([item.sizeHint().height() for item in self.items] or [0])

    def minimumSize(self):
        filler, keys = self._parts()
        needs = self._needs(keys, least=True)
        if filler is None:
            width = max(needs or [0])
        else:
            width = filler.minimumWidth() + sum(needs) \
                + self._spacing * len(keys)
        return QSize(width, self._height())

    def sizeHint(self):
        filler, keys = self._parts()
        needs = self._needs(keys)
        width = sum(needs) + self._spacing * max(0, len(keys) - 1)
        if filler is not None:
            width += filler.minimumWidth() + self._spacing
        return QSize(width, self._height())

    def hasHeightForWidth(self):
        return True

    def heightForWidth(self, width):
        return self._lay(QRect(0, 0, width, 0), True)

    def setGeometry(self, rect):
        super().setGeometry(rect)
        self._lay(rect, False)

    @staticmethod
    def _shares(room, needs, spacing):
        """The widths of keys sharing a row of that much room: equal when an
        equal share holds every word, each word's need and an equal part of
        what is left otherwise. None when even the needs do not fit."""
        n = len(needs)
        free = room - spacing * (n - 1)
        if n * max(needs) <= free:
            wide, rest = divmod(free, n)
            return [wide + (1 if k < rest else 0) for k in range(n)]
        if sum(needs) <= free:
            more, rest = divmod(free - sum(needs), n)
            return [need + more + (1 if k < rest else 0)
                    for k, need in enumerate(needs)]
        return None

    def _lay(self, rect, measure_only):
        filler, keys = self._parts()
        tall = self._height()
        left, top, room = rect.x(), rect.y(), rect.width()
        if not keys:
            if filler is not None and not measure_only:
                filler.setGeometry(QRect(left, top, room, tall))
            return tall if filler is not None else 0
        needs = self._needs(keys)
        if filler is not None:
            free = room - filler.minimumWidth() - self._spacing * len(keys)
            dressed = max(self.dressed.get(id(k), 0) for k in keys)
            if dressed and len(keys) * dressed <= free:
                widths = [dressed] * len(keys)
            elif len(keys) * max(needs) <= free:
                widths = [max(needs)] * len(keys)
            elif sum(needs) <= free:
                widths = needs
            else:
                widths = self._needs(keys, least=True)
            if not measure_only:
                used = sum(widths) + self._spacing * len(keys)
                filler.setGeometry(QRect(left, top, max(1, room - used), tall))
                x = left + max(1, room - used) + self._spacing
                for k, w in zip(keys, widths):
                    k.setGeometry(QRect(x, top, w, tall))
                    x += w + self._spacing
            return tall
        # one line if the row holds them, with the air the style keeps or
        # with the least, else as many lines as it takes, each one shared
        # out the same way
        if self._shares(room, needs, self._spacing) is None:
            needs = self._needs(keys, least=True)
        lines, line = [], []
        for k, need in zip(keys, needs):
            trial = [n for _, n in line] + [need]
            if line and self._shares(room, trial, self._spacing) is None:
                lines.append(line)
                line = []
            line.append((k, need))
        lines.append(line)
        y = top
        for line in lines:
            widths = self._shares(room, [n for _, n in line], self._spacing) \
                or [n for _, n in line]
            if not measure_only:
                x = left
                for (k, _), w in zip(line, widths):
                    k.setGeometry(QRect(x, y, w, tall))
                    x += w + self._spacing
            y += tall + self._spacing
        return y - self._spacing - top


class SliderRow(QLayout):
    """A word, a slider and the number box that shows its value: on one row
    while the slider keeps room enough to be used, and on two when it would
    not, the word and the box on the first and the slider the whole width of
    the second.

    On one line the row at 260 pixels with a Linux desktop's font (DejaVu is
    half as wide again as Segoe UI) leaves the slider 22 pixels, a stub with
    a handle and no track, and the box a pixel from the edge. least() is
    the narrowest slider worth having, asked at every pass so that it
    follows the font it is drawn in; the row stays one line exactly as
    long as the word, that slider and the box, with the air between them,
    fit the width it is given."""

    def __init__(self, least, spacing=6):
        super().__init__()
        self.items = []
        self.least = least
        self._spacing = spacing
        self.setContentsMargins(0, 0, 0, 0)

    def addItem(self, item):
        self.items.append(item)

    def count(self):
        return len(self.items)

    def itemAt(self, i):
        return self.items[i] if 0 <= i < len(self.items) else None

    def takeAt(self, i):
        return self.items.pop(i) if 0 <= i < len(self.items) else None

    def expandingDirections(self):
        return Qt.Orientation(0)

    def add(self, word, slider, box):
        for widget in (word, slider, box):
            self.addWidget(widget)

    def _sizes(self):
        """(the word, the slider, the box) as sizes, or None before the
        three are in."""
        if len(self.items) != 3:
            return None
        return [item.sizeHint() for item in self.items]

    def _least(self):
        return max(1, int(self.least()))

    def hasHeightForWidth(self):
        return True

    def heightForWidth(self, width):
        return self._lay(QRect(0, 0, width, 0), True)

    def sizeHint(self):
        sizes = self._sizes()
        if sizes is None:
            return QSize(0, 0)
        word, slider, box = sizes
        wide = word.width() + box.width() + 2 * self._spacing \
            + max(self._least(), slider.width())
        return QSize(wide, max(s.height() for s in sizes))

    def minimumSize(self):
        sizes = self._sizes()
        if sizes is None:
            return QSize(0, 0)
        word, slider, box = sizes
        wide = max(word.width() + self._spacing + box.width(), self._least())
        return QSize(wide, max(s.height() for s in sizes))

    def setGeometry(self, rect):
        super().setGeometry(rect)
        self._lay(rect, False)

    @staticmethod
    def _put(item, x, y, w, row_high):
        """The item at x, centred on a row row_high tall that starts at y."""
        high = item.sizeHint().height()
        item.setGeometry(QRect(x, y + max(0, row_high - high) // 2, w, high))

    def _lay(self, rect, measure_only):
        sizes = self._sizes()
        if sizes is None:
            return 0
        word, slider, box = sizes
        gap, room = self._spacing, rect.width()
        left, top = rect.x(), rect.y()
        if word.width() + box.width() + 2 * gap + self._least() <= room:
            high = max(s.height() for s in sizes)
            if not measure_only:
                x = left
                self._put(self.items[0], x, top, word.width(), high)
                x += word.width() + gap
                track = room - word.width() - box.width() - 2 * gap
                self._put(self.items[1], x, top, track, high)
                self._put(self.items[2], left + room - box.width(), top,
                          box.width(), high)
            return high
        above = max(word.height(), box.height())
        if not measure_only:
            self._put(self.items[0], left, top, word.width(), above)
            self._put(self.items[2], left + room - box.width(), top,
                      box.width(), above)
            self.items[1].setGeometry(QRect(left, top + above + gap, room,
                                            slider.height()))
        return above + gap + slider.height()


class Deck(QWidget):
    """The body of a module, dealt into as many columns as the width holds.

    A module docked at the side of the map is a narrow strip and its pieces
    stack, one under the other, the way they were written. The same module
    dragged to the top of the window is wide and low, and then stacking is
    exactly the wrong thing: the eye has to travel down a column while the
    whole right half of the screen sits empty. So the pieces are dealt out
    sideways instead, into two, three or four columns, balanced by how much
    room each of them asks for. The pieces themselves never change: only how
    they are dealt."""

    def __init__(self, minimum=DECK_MIN, most=DECK_MAX, gap=16):
        super().__init__()
        self.pieces = []            # (layout or widget, weight)
        self.minimum = minimum
        self.most = most
        self.after = None           # what to tell once the columns have moved
        self._columns = 0
        self.strip = QHBoxLayout(self)
        self.strip.setContentsMargins(0, 0, 0, 0)
        self.strip.setSpacing(gap)
        self.columns = []
        self.struts = []
        for _ in range(most):
            column = QVBoxLayout()
            column.setContentsMargins(0, 0, 0, 0)
            column.setSpacing(7)
            # A column in use is never narrower than this. Without it a column
            # holding nothing but a few short chips shrinks to the width of the
            # chips and its neighbour swallows the rest of the strip.
            column.addStretch(1)
            strut = QSpacerItem(0, 0, QSizePolicy.Policy.Minimum, QSizePolicy.Policy.Minimum)
            column.addSpacerItem(strut)
            self.strip.addLayout(column, 0)
            self.columns.append(column)
            self.struts.append(strut)
        policy = self.sizePolicy()
        policy.setHeightForWidth(True)
        self.setSizePolicy(policy)

    def hasHeightForWidth(self):
        return self.strip.hasHeightForWidth()

    def heightForWidth(self, width):
        """A module whose buttons wrap is taller when it is narrow, and the box
        above has to be told so before it decides how much room to give it.
        Without this the deck is handed the height it asked for at some other
        width, and its pieces are drawn one on top of another."""
        return self.strip.heightForWidth(width)

    def minimumSizeHint(self):
        return self.strip.minimumSize()

    def sizeHint(self):
        return self.strip.sizeHint()

    def room(self):
        """The width one column has. Taken from the deck and the number of
        columns, never from what is inside them: a piece whose own size decided
        the width it is measured against would chase its own tail, growing and
        shrinking at every pass of the layout."""
        used = max(1, self._columns)
        return max(140, (self.width() - self.strip.spacing() * (used - 1)) // used)

    def add(self, piece, weight=1):
        """A piece is either a widget or a whole layout. Layouts are welcome
        on purpose: the class chips must not be wrapped in a widget of their
        own, because a widget keeps the height it was given when the legend
        changes and the last row is drawn over whatever comes next."""
        self.pieces.append((piece, weight))

    def columns_for(self, width):
        if ONE_COLUMN:
            return 1
        return max(1, min(self.most, len(self.pieces),
                          max(1, int(width)) // self.minimum))

    def split(self, wanted):
        """Cut the pieces into that many columns, in order, keeping the weight
        as even as the order allows. Order is never broken: a panel whose
        pieces change places when it is resized is worse than one that leaves
        a column a little longer than its neighbour."""
        total = float(sum(w for _, w in self.pieces)) or 1.0
        target = total / wanted
        plan, group, used = [], [], 0.0
        for i, (piece, weight) in enumerate(self.pieces):
            left = len(self.pieces) - i          # pieces not yet placed
            room = wanted - len(plan)            # columns not yet closed
            # A column must be closed when every piece still in hand is needed
            # to open one of the columns still to come, and it may be closed
            # whenever what is left can still fill them.
            must = left < room
            can = room > 1 and left >= room - 1
            if group and can and (must or used + weight / 2.0 > target):
                plan.append(group)
                group, used = [], 0.0
            group.append(piece)
            used += weight
        plan.append(group)
        while len(plan) < wanted:
            plan.append([])
        return plan

    def deal(self, force=False):
        wanted = self.columns_for(self.width())
        if wanted == self._columns and not force:
            return
        self._columns = wanted
        tail = 2                                 # the stretch and the strut
        for column in self.columns:
            while column.count() > tail:
                item = column.takeAt(0)
                inner = item.layout() if item is not None else None
                # A layout taken out of another one keeps it as its parent, and
                # Qt then refuses to put it anywhere else. Clearing the parent
                # is what makes a piece movable from one column to another.
                if inner is not None:
                    inner.setParent(None)
        for index, group in enumerate(self.split(wanted)):
            column = self.columns[index]
            for piece in group:
                if isinstance(piece, QLayout):
                    column.insertLayout(column.count() - tail, piece)
                else:
                    column.insertWidget(column.count() - tail, piece)
        for i in range(self.most):
            self.strip.setStretch(i, 1 if i < wanted else 0)
            self.struts[i].changeSize(self.minimum - 24 if i < wanted else 0, 0,
                                      QSizePolicy.Policy.Minimum, QSizePolicy.Policy.Minimum)
            self.columns[i].invalidate()
        self.strip.activate()
        if self.after is not None:
            self.after()

    def resizeEvent(self, ev):
        QWidget.resizeEvent(self, ev)
        self.deal()

# ---------------------------------------------------------------------
# ---- theme -----------------------------------------------------------
# ---------------------------------------------------------------------

# ---------------------------------------------------------------- the look
#  Colours are read from the theme QGIS is running with, never written in.
#  A panel painted for the light theme turns unreadable the moment somebody
#  switches to Night Mapping, and the accent is the one the whole program
#  already uses for selection, so the panel belongs to it rather than shouting
#  over it.
#
#  And as little as possible is painted at all. Buttons, combo boxes, spin
#  boxes, line edits and tick boxes in their ordinary state are drawn by
#  QGIS's own style, so the panel looks like every other dock beside it, in
#  the light theme, in Night Mapping and in Blend of Gray. A stylesheet rule
#  that reaches a spin box takes its arrows away under Fusion; one that paints
#  the normal state of a button turns it into a light slab inside a dark
#  theme. What is painted here is only what carries meaning: the tool or
#  module in hand (the accent), what cannot be pressed (it steps back), and
#  what destroys work (it says so, before the pointer gets there).
def mix(a, b, t):
    a, b = QColor(a), QColor(b)
    return QColor(int(a.red() + (b.red() - a.red()) * t),
                  int(a.green() + (b.green() - a.green()) * t),
                  int(a.blue() + (b.blue() - a.blue()) * t))


def luminance(colour):
    """The relative luminance of the WCAG, from 0 for black to 1 for white."""
    c = QColor(colour)

    def channel(v):
        v = v / 255.0
        return v / 12.92 if v <= 0.03928 else ((v + 0.055) / 1.055) ** 2.4
    return (0.2126 * channel(c.red()) + 0.7152 * channel(c.green())
            + 0.0722 * channel(c.blue()))


def contrast(a, b):
    """How far apart two colours read, from 1 (the same) to 21."""
    la, lb = luminance(a), luminance(b)
    return (max(la, lb) + 0.05) / (min(la, lb) + 0.05)


def ink_on(colour):
    """The ink that reads best on a fill: white or black, whichever is
    further from it. Chosen by contrast and not by brightness, which wrote
    white on a mid grey or a ripe brown where black reads twice as well.
    Black and not a near black: on the fills halfway between the two, a
    brown like crust, near black fell under 4.5 to 1 where black still
    clears it, and that is the colour every fill can be."""
    light, dark = "#ffffff", "#000000"
    return light if contrast(light, colour) >= contrast(dark, colour) \
        else dark


def quieter(text, ground, t, least=4.5):
    """The text colour taken towards the ground by t, but never so far that
    it drops under the contrast small writing needs."""
    while t > 0.02 and contrast(mix(text, ground, t), ground) < least:
        t -= 0.04
    return mix(text, ground, max(t, 0.0))


def _theme_colour(selector, prop):
    """A colour the application stylesheet gives one kind of widget, or None.

    QGIS's dark themes do not paint through the palette: Night Mapping
    reports a Window of #535353 and paints its docks #323232, and it writes
    the labels in a grey of its own. Colours mixed from the palette alone came
    out for a ground the panel never stands on. The theme's own rules are
    read instead, where it has them."""
    try:
        sheet = QApplication.instance().styleSheet() or ""
    except Exception:
        return None
    found = None
    for block in sheet.split("}"):
        if "{" not in block:
            continue
        head, body = block.split("{", 1)
        names = [n.strip() for n in head.split(",")]
        if selector not in names:
            continue
        for part in body.split(";"):
            if ":" not in part:
                continue
            key, value = part.split(":", 1)
            value = value.strip()
            if key.strip() == prop and value.startswith("#"):
                colour = QColor(value.split()[0])
                if colour.isValid():
                    found = colour
    return found


def _button_grounds():
    """Every colour the theme paints the face of a button with.

    Night Mapping paints its buttons with a gradient from #565656 to #464646
    and says #efefef in the palette, which it never shows; Fusion and the
    light theme paint the palette's Button. Words written on a button have to
    read on all of them, so all of them are given."""
    found = []
    try:
        sheet = QApplication.instance().styleSheet() or ""
    except Exception:
        sheet = ""
    for block in sheet.split("}"):
        if "{" not in block:
            continue
        head, body = block.split("{", 1)
        names = [n.strip() for n in head.split(",")]
        if "QPushButton" not in names:
            continue
        for part in body.split(";"):
            if ":" not in part:
                continue
            key, value = part.split(":", 1)
            if key.strip() in ("background", "background-color"):
                found += [QColor(c) for c in
                          re.findall(r"#[0-9a-fA-F]{6}\b", value)]
    if not found:
        found = [QApplication.palette().color(QPalette.ColorRole.Button)]
    return found


def readable_on(colour, grounds, least=4.5):
    """The colour, made lighter on dark grounds or darker on light ones until
    it reads on every one of them."""
    colour = QColor(colour)
    dark = sum(luminance(g) for g in grounds) / len(grounds) < 0.18
    towards = QColor("#ffffff" if dark else "#000000")
    for step in range(0, 101, 4):
        tried = mix(colour, towards, step / 100.0)
        if min(contrast(tried, g) for g in grounds) >= least:
            return tried
    return towards


def palette_colours():
    p = QApplication.palette()
    window = _theme_colour("QDockWidget", "background-color") \
        or p.color(QPalette.ColorRole.Window)
    text = _theme_colour("QLabel", "color") \
        or p.color(QPalette.ColorRole.WindowText)
    accent = p.color(QPalette.ColorRole.Highlight)
    on_accent = p.color(QPalette.ColorRole.HighlightedText)
    if contrast(on_accent, accent) < 3.0:
        on_accent = QColor(ink_on(accent))
    dark = window.lightness() < 128
    # The pressed tool or module in the accent, nudged until its own words
    # read on it: QGIS's blue under white is a shade too light for 9 points.
    checked = QColor(accent)
    for _ in range(8):
        if contrast(on_accent, checked) >= 4.5:
            break
        checked = checked.darker(107) if luminance(on_accent) > 0.4 \
            else checked.lighter(107)
    # The ring round a pressed button that has the keyboard: its own border
    # takes the place of the style's focus frame, so it is drawn here. It
    # stands between the fill and the panel and has to read against both:
    # white on QGIS's blue vanished into the light panel round it, the
    # theme's grey on Night Mapping's orange into the button.
    ring = max((text, on_accent, QColor("#000000"), QColor("#ffffff")),
               key=lambda c: min(contrast(c, checked), contrast(c, window)))
    # A grey button's words: far enough from the ground to be read, which
    # is how a grey button says why it is grey, and never so near the live
    # ones that it passes for one. Three to one where the theme's own words
    # stand far from the ground; in Night Mapping, whose words are grey to
    # begin with, two and a half times fainter than they are.
    off_least = min(3.0, contrast(text, window) / 2.5)
    t = 0.30
    while t < 0.9 and contrast(mix(text, window, t), window) > off_least:
        t += 0.02
    # Red that reads on the buttons it is written on, whatever the theme
    # paints them with: #ef7b70 cleared 4.5 to 1 on the dock and fell to 3
    # on Night Mapping's buttons, the three keys that destroy work being the
    # faintest in their rows.
    danger = readable_on("#ef7b70" if dark else "#b3261e",
                         _button_grounds() + [window])
    return {
        "window": window.name(),
        "text": text.name(),
        "dim": quieter(text, window, 0.42).name(),   # secondary, still legible
        "line": mix(text, window, 0.78).name(),      # hairlines and frames
        # A grey button steps back: no fill, a faint outline, faint words.
        # Fusion draws a disabled button as an enabled one with grey text,
        # and fifteen of them in a row looked like fifteen things to press.
        # No fill means the ground shows through, whatever the theme paints
        # the dock with, so it can never come out lighter than the live ones.
        "off_edge": mix(text, window, 0.82).name(),
        "off_text": mix(text, window, t).name(),
        "accent": accent.name(),
        "checked": checked.name(),
        "accent_edge": checked.darker(125).name(),
        "on_accent": on_accent.name(),
        "ring": ring.name(),
        "danger": danger.name(),
        # the guidance strip: warm, quiet, and readable in both themes. It is
        # not a warning, so it must not borrow the colour of one; it is the
        # line you read without looking for it.
        "step_bg": "#3a3320" if dark else "#fff6d5",
        "step_ink": "#f0dfa8" if dark else "#4a3c00",
        "step_edge": "#6b5c32" if dark else "#e0c96a",
        "dark": dark,
    }


def label_sheet():
    """The rules that are safe anywhere, the dialogs included: they name
    only labels and frames, by the object name the program gave them.

    Set on the panel itself, whose children the dialogs are, so a quiet line
    in a dialog is as quiet as one in the panel."""
    return """
    QLabel#section {
        color: %(text)s;
        font-weight: bold;
    }
    QLabel#subsection {
        color: %(dim)s;
        font-weight: bold;
    }
    QLabel#quiet { color: %(dim)s; }
    QLabel#warn { color: %(danger)s; }
    QLabel#step {
        background: %(step_bg)s;
        color: %(step_ink)s;
        border: 1px solid %(step_edge)s;
        border-radius: 4px;
        padding: 6px 8px;
    }
    QFrame[rule="true"] { color: %(line)s; background: %(line)s; border: none; }
    """ % palette_colours()


def stylesheet():
    """The rules for the controls of the panel, and only of the panel.

    Set on the panel's body and not on the panel: every dialog the panel
    opens is its child, and the keypad's compact buttons would cascade into
    them, leaving OK and Cancel thirty pixels wide. The body holds the
    panel's controls and none of its windows.

    No rule names a combo box, a spin box, a line edit or a tick box, and
    the buttons are named only in a state: tests/test_layout.py holds the
    sheet to both."""
    return """
    QPushButton:checked {
        background: %(checked)s;
        color: %(on_accent)s;
        border: 1px solid %(accent_edge)s;
        border-radius: 3px;
        font-weight: bold;
    }
    /* the border above replaces the style's focus frame, so the keyboard's
       place on a pressed button is drawn here */
    QPushButton:checked:focus { border: 2px solid %(ring)s; }
    QPushButton:disabled {
        background: transparent;
        color: %(off_text)s;
        border: 1px solid %(off_edge)s;
        border-radius: 3px;
    }
    QPushButton[danger="true"]:enabled { color: %(danger)s; }
    /* Measure greyed is drawn by the rule above, which puts the arrow of
       its menu in the bottom corner, over the last letter: it stays where
       the style puts it on the live key, after the word */
    QPushButton#measure::menu-indicator {
        subcontrol-origin: padding;
        subcontrol-position: center right;
        right: 4px;
    }
    QToolButton#fold {
        border: none;
        color: %(text)s;
        font-weight: bold;
        padding: 2px 0px;
    }
    QToolButton#fold:hover { color: %(accent)s; }
    QToolButton#unfold { border: none; padding: 0px; }
    /* with no border of their own they show no focus either: given one */
    QToolButton#fold:focus, QToolButton#unfold:focus {
        border: 1px solid %(accent)s;
        border-radius: 3px;
    }
    /* the open module: one hairline round it, and no room kept at the top
       for a title it does not have (Night Mapping keeps thirty pixels) */
    QGroupBox {
        border: 1px solid %(line)s;
        border-radius: 4px;
        margin-top: 0px;
        padding-top: 0px;
    }
    """ % palette_colours()


# ---------------------------------------------------------------- icons
#  QGIS's own icons, beside the word and never instead of it, and on six
#  buttons only: the four modules, which are what the blocks are for, and
#  Save and Delete, the two presses that decide what is kept. An icon on
#  every key was sixteen colours fighting in a narrow column, and it pushed
#  rows of four keys onto a second line. Every name below is in QGIS 3.36,
#  3.44 and 4.2 alike. A name a QGIS does not carry, or no QGIS at all (the
#  suites), gives no icon, and the button is the word alone.
ICONS = {
    "Annotate": "mActionCapturePolygon.svg",
    "Objects": "mActionRectangleExtent.svg",
    "Correct": "mActionToggleEditing.svg",
    "Cutouts": "algorithms/mAlgorithmClip.svg",
    "Save": "mActionSaveEdits.svg",
    "Delete": "mActionDeleteSelectedFeatures.svg",
}
ICON_PX = 16
_icon_cache = {}


def theme_icon(name):
    """QGIS's icon of that name, or None when there is none to be had."""
    if not name:
        return None
    if name in _icon_cache:
        return _icon_cache[name]
    icon = None
    try:
        from qgis.core import QgsApplication
        found = QgsApplication.getThemeIcon(name)
        if found is not None and not found.isNull() \
                and not found.pixmap(ICON_PX, ICON_PX).isNull():
            icon = found
    except Exception:
        icon = None
    _icon_cache[name] = icon
    return icon


def icon_for(word):
    return theme_icon(ICONS.get(word))


def swatch_style(colour):
    """A colour well: the colour, a hairline that reads on light and dark
    alike, rounded like the chips."""
    return ("QPushButton { background-color: %s; border: 1px solid "
            "rgba(0,0,0,0.35); border-radius: 3px; min-height: 20px; }"
            "QPushButton:hover { border: 1px solid palette(highlight); }"
            # the rule above replaces the style's focus frame
            "QPushButton:focus { border: 2px solid palette(highlight); }"
            % colour)


def intro(title, body):
    """The head of a dialog, the way the Trouble window has it: one bold
    line saying what the window is for, then the detail in quiet words that
    wrap to the width of the window instead of breaking where the source
    code did."""
    holder = QWidget()
    box = QVBoxLayout(holder)
    box.setContentsMargins(0, 0, 0, 4)
    box.setSpacing(4)
    head = QLabel(title)
    f = head.font()
    f.setBold(True)
    f.setPointSizeF(f.pointSizeF() * 1.1)
    head.setFont(f)
    box.addWidget(head)
    words = QLabel(body)
    words.setObjectName("quiet")
    words.setWordWrap(True)
    box.addWidget(words)
    return holder


def titled(what):
    """The title of a window of the program: its name first, so a dialog
    left behind QGIS in the taskbar says whose it is."""
    return "%s: %s" % (NAME, what)


def browse(tip):
    """The button beside a folder or a file, the same in every window: three
    dots, as QGIS's own, never wider than they need. It was 'choose' in one
    window, 'Choose' in another and a bar of dots as wide as the field in a
    third."""
    b = QPushButton("…")
    b.setToolTip(tip)
    b.setFixedWidth(32)
    return b


def short_combo(box, chars=6):
    """A list that keeps to the room its window gives it.

    Sized to its contents a list takes the width of its longest item: a
    layer named at length, a reading with a long operator's name, a sentence
    that explains a choice, and a window made for 300 pixels was held at 460
    in DejaVu, whose letters are wider than the ones it was drawn with. A long
    item is cut at the edge of the box instead, and whole in the list when it
    opens; chars is how many letters the box shows at least."""
    box.setSizeAdjustPolicy(
        QComboBox.SizeAdjustPolicy.AdjustToMinimumContentsLengthWithIcon)
    box.setMinimumContentsLength(chars)
    box.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
    return box


def short_spin(spin, sample="000000"):
    """A number box that asks for the room of a number like sample, not of the
    biggest it could hold: a box that goes up to 2 147 483 647, or to a
    trillion with four decimals, asked for a hundred pixels more than a window
    of 300 has, with the fonts of Linux. A longer number scrolls in the box."""
    metrics = spin.fontMetrics()
    spin.setMinimumWidth(text_width(metrics, sample) + 2 * metrics.height())
    return spin


def rule():
    """A hairline across a window, in the colour of the panel's own."""
    line = QFrame()
    line.setFrameShape(QFrame.Shape.HLine)
    line.setFrameShadow(QFrame.Shadow.Plain)
    line.setProperty("rule", True)
    line.setFixedHeight(1)
    return line


def column_head(word):
    label = QLabel(word)
    label.setObjectName("subsection")
    return label


# ---------------------------------------------------------------- buttons
#  The word on every button, and QGIS's icon beside it where QGIS
#  has one: see ICONS. Every button is exactly as wide as its word and icon.
def text_width(metrics, words):
    try:
        return metrics.horizontalAdvance(words)
    except AttributeError:                  # Qt 5.10 and older
        return metrics.width(words)


def bold_metrics(widget):
    """A pressed button writes its word in bold, and bold is wider. Measuring
    the plain font would cut the label off exactly when it matters most."""
    f = QFont(widget.font())
    f.setBold(True)
    return QFontMetrics(f)


def key_height(widget, least=ICON_H):
    """As tall as a key is, or taller when the font QGIS was given is.

    A fixed height has three pixels to spare at QGIS's 11 point font and cuts
    the words off at 13: the height follows the line the font needs."""
    return max(least, widget.fontMetrics().height() + 10)


def chip_height(widget):
    """A class chip, as tall as CLASS_H or as the font needs: at QGIS's 13
    point font a chip of 24 pixels cut the lower half of every name."""
    return max(CLASS_H, widget.fontMetrics().height() + 8)


def banner_height(widget, lines=1):
    """The class in hand over the chips: one line in its own large font, or
    in Correct two, a small word over the class. Fixed at 36 and 42 pixels,
    a 13 point font would lose half of the name."""
    if lines == 1:
        return max(BANNER_H, widget.fontMetrics().height() + 12)
    small = QFont(widget.font())
    small.setPointSize(max(widget.font().pointSize() - 3, 7))
    return max(BANNER_H + 6, QFontMetrics(small).height()
               + widget.fontMetrics().height() + 12)


def fit_field(box, least=0):
    """A number box as wide as its own style asks to show its largest value
    and its unit, and never narrower than least. A width written in, 66
    pixels, held under Fusion and cut '33 %' to '33' under the windows11
    style QGIS 4 uses on Windows 11, which asks for 106."""
    box.setFixedWidth(max(least, box.sizeHint().width()))
    return box


def button_pad(button):
    """The room the style keeps around the word of a button, measured from
    the style itself. PAD was enough for Fusion; the windows11 style keeps
    more and cut the first letter off Go."""
    pad = 0
    try:
        opt = QStyleOptionButton()
        opt.initFrom(button)
        opt.text = "x"
        # measured on a word wide enough that no style's least width for a
        # button (eighty pixels in Fusion) has a say in it
        pad = button.style().sizeFromContents(
            QStyle.ContentsType.CT_PushButton, opt, QSize(200, 20),
            button).width() - 200
    except Exception:
        pad = 0
    return max(PAD, pad)


# The least air beside the word of a key in a row that has no room left:
# four pixels each side, past which the word would touch the frame.
TIGHT_PAD = 8


def menu_room(button):
    """The room the arrow of a button with a menu takes beside its word, as
    the style draws it: a key that opens a menu (Measure) is that much
    wider than its word, or the arrow is drawn over the last letter."""
    try:
        if button.menu() is None:
            return 0
        return button.style().pixelMetric(
            QStyle.PixelMetric.PM_MenuButtonIndicator, None, button)
    except Exception:
        return 0


def key_need(button, tight=False):
    """The least width a key can be given with its word still whole: the
    word in the font it is written in, the room the style keeps round it,
    the icon, and the arrow of a menu. In bold only for a key that can be
    pressed and stay down, the one kind a stylesheet writes in bold.

    dress() measures every key in bold, which leaves a key a little air on
    a panel with room for it; this is the floor a row comes down to when it
    has none (KeyRow). tight is the floor under that one, for a row that
    still does not fit: the word and its frame, with TIGHT_PAD of air in
    place of the room the style likes to keep, which a theme that pads
    every button (Night Mapping) makes generous."""
    metrics = (bold_metrics(button) if button.isCheckable()
               else button.fontMetrics())
    pad = TIGHT_PAD if tight else button_pad(button)
    need = text_width(metrics, button.text()) + pad
    if not button.icon().isNull():
        need += ICON_PX + 6
    return need + menu_room(button)


def key_least(button):
    return key_need(button, tight=True)


def dress(button, word, pad=None):
    button.setText(word)
    icon = icon_for(word)
    extra = menu_room(button)
    if icon is not None:
        button.setIcon(icon)
        button.setIconSize(QSize(ICON_PX, ICON_PX))
        extra += ICON_PX + 6
    elif word in ICONS:
        button.setIcon(QIcon())
    height = button.height() if button.property("primary") \
        else key_height(button)
    button.setFixedSize(text_width(bold_metrics(button), word)
                        + (button_pad(button) if pad is None else pad) + extra,
                        height)
    return button


def hold_shape(dialog, least):
    """The smallest a window may be made: least wide, and at that width as
    tall as everything in it needs, its wrapped words included.

    Qt does not count words that wrap in the least height of a window: a
    window whose layout holds one lets itself be made as small as nothing,
    and the class list and the buttons under it get drawn over each other.
    A layout told to keep its minimum ignores a minimum width given by hand.
    So both are given by hand, from the height the layout needs at that
    width; called again whenever what the window shows changes."""
    layout = dialog.layout()
    layout.setSizeConstraint(QLayout.SizeConstraint.SetDefaultConstraint)
    layout.activate()
    width = max(least, layout.totalMinimumSize().width())
    tall = layout.totalMinimumSize().height()
    try:
        need = layout.minimumHeightForWidth(width)
    except Exception:
        need = -1
    dialog.setMinimumSize(width, max(tall, need))
    if dialog.width() < width or dialog.height() < max(tall, need):
        dialog.resize(max(dialog.width(), width),
                      max(dialog.height(), tall, need))
    return dialog


class ShapeKeeper(QObject):
    """Holds a window's least height up to date while it is being resized.

    hold_shape measures once, at the width the window has when it is built.
    A tick box that wraps its words (WrapTick) is one line tall then and two
    or three when the window is made narrower, and the least height measured
    before is too small for it: the rows below get drawn over each other.
    After each resize, once the boxes have wrapped, the shape is held again."""

    def __init__(self, dialog, least):
        super().__init__(dialog)
        self.dialog = dialog
        self.least = least
        self.pending = False
        dialog.installEventFilter(self)

    def eventFilter(self, watched, ev):
        if watched is self.dialog and ev.type() == QEvent.Type.Resize \
                and not self.pending:
            self.pending = True
            QTimer.singleShot(0, self.settle)
        return False

    def settle(self):
        self.pending = False
        if self.dialog.layout() is None:
            return
        # twice: the first pass lays the boxes out, and they wrap; the
        # second measures them wrapped
        hold_shape(self.dialog, self.least)
        hold_shape(self.dialog, self.least)


def keep_shape(dialog, least):
    """hold_shape now, and again after every resize: for a window with tick
    boxes that wrap."""
    hold_shape(dialog, least)
    if getattr(dialog, "_shape_keeper", None) is None:
        dialog._shape_keeper = ShapeKeeper(dialog, least)
    return dialog


def primary(button, height=None):
    """A module button, or Save: what a block or a module is for, so it is
    the first thing the eye lands on. Taller than a key and written in bold,
    with QGIS's icon; drawn by QGIS's style like every other button until it
    is pressed, when it takes the accent. It is not tinted: a tint mixed from
    Night Mapping's orange came out a muddy brown, and the accent is kept for
    what is in hand."""
    button.setProperty("primary", True)
    f = QFont(button.font())
    f.setBold(True)
    button.setFont(f)
    button.setFixedHeight(height or key_height(button, PRIMARY_H))
    return button


def bar(groups, room=None, gap=GROUP_GAP, uniform=True, counts=()):
    """The command bar of a module: buttons of one size, in as many columns as
    the panel is wide enough to hold.

    As wide as their own word they would make every row a different
    shape, and the eye would have to find each button again after every
    resize. All one size, the bar reads as a keypad: the hand learns where
    Save is and the place stays put whether the panel shows two columns or
    four."""
    flow = FlowLayout(4, gap, uniform, counts)
    for i, group in enumerate(groups):
        for j, button in enumerate(group):
            flow.add(button, new_group=(i > 0 and j == 0))
    return flow


def keypad(rows, gap=4):
    """The keys of a block of the panel, row by row as they are written.

    Each row shares the whole width of the block. The rows are not one grid:
    a row of three is in thirds and a row of two in halves, so a block whose
    keys do not make whole rows of three ends in two halves instead of a key
    alone or a hole. And a row too narrow for equal keys gives each key the
    width its word needs (KeyRow) instead of falling to fewer columns, which
    would break the rows of New, Open and Close apart on a Linux desktop,
    whose larger font does not hold three keys at two hundred and sixty
    pixels."""
    box = QVBoxLayout()
    box.setContentsMargins(0, 0, 0, 0)
    box.setSpacing(gap)
    for row in rows:
        line = KeyRow(key_need, gap, least=key_least)
        for button in row:
            line.add(button)
        box.addLayout(line)
    return box


def full_width(button):
    """Undo the fixed width dress() gave a button, and let it take the room.

    dress() makes every button exactly as wide as its own word, which is right
    for a keypad of eight. It is wrong for a box of one or two: Save, and the
    pairs Tiles/Move and Frames/Marks, are the buttons the hand goes to without
    looking, and a narrow word floating at the left of a wide bar is harder to
    hit than the same word stretched across it."""
    extra = 0 if button.icon().isNull() else ICON_PX + 6
    button.setMinimumWidth(
        text_width(bold_metrics(button), button.text())
        + button_pad(button) + extra)
    button.setMaximumWidth(16777215)            # QWIDGETSIZE_MAX
    if not button.property("primary"):
        button.setFixedHeight(key_height(button))
    policy = button.sizePolicy()
    policy.setHorizontalPolicy(QSizePolicy.Policy.Expanding)
    button.setSizePolicy(policy)
    return button


def spread(buttons, gap=GROUP_GAP):
    """A row of buttons that share the whole width, equally.

    Not a FlowLayout: these never wrap, because there are at most two of them
    and the point is that each one is half the bar, in the same place, at every
    width the panel can be given."""
    row = QHBoxLayout()
    row.setContentsMargins(0, 0, 0, 0)
    row.setSpacing(gap)
    for button in buttons:
        row.addWidget(full_width(button), 1)
    return row


def heading(word, widget):
    """The small name a module writes over each group of its keys.

    The blocks of the panel have had one since the beginning and the groups
    of a module did not, which left the row of shapes looking like the row of
    commands underneath it. A word costs a few pixels of height and saves the
    question."""
    holder = QWidget()
    box = QVBoxLayout(holder)
    box.setContentsMargins(0, 0, 0, 0)
    box.setSpacing(4)
    label = QLabel(word)
    label.setObjectName("subsection")
    f = label.font()
    f.setPointSize(max(f.pointSize() - 1, 7))
    label.setFont(f)
    box.addWidget(label)
    if isinstance(widget, QWidget):
        box.addWidget(widget)
    else:
        box.addLayout(widget)
    return follows_width(holder)


def plain(layout):
    """A group of keys in a widget of its own, with no frame round it.

    Inside the module the groups are told apart by their small headings and
    a little air. A frame round each of them inside the module's own frame
    was two borders everywhere, forty pixels of lines in the one column where
    every pixel is wanted for the work."""
    holder = QWidget()
    holder.setLayout(layout)
    return follows_width(holder)


def follows_width(widget):
    """Let this widget's height depend on the width it is given.

    Buttons that wrap and chips that reflow make a box taller as it gets
    narrower, and the layout above will not ask unless the size policy says it
    should. Qt does not work this out by itself across a widget: the chain of
    layouts carries it, a widget in the middle of the chain breaks it. Every
    box that has a wrapping thing inside it says so here."""
    policy = widget.sizePolicy()
    policy.setHeightForWidth(True)
    widget.setSizePolicy(policy)
    return widget


def _canvas(size, ratio=1.0):
    """A transparent square to draw an icon on, with as many pixels as a
    screen at that ratio has. The painter keeps working in logical units."""
    pm = QPixmap(int(round(size * ratio)), int(round(size * ratio)))
    pm.setDevicePixelRatio(ratio)
    pm.fill(Qt.GlobalColor.transparent)
    return pm


def _icon(size, paint):
    """An icon drawn by paint(painter), once for every pixel ratio it may be
    shown at: the logical size, the screen's own and twice that.

    One pixmap of the screen's ratio came out crisp on Qt 6, and on Qt 5 at
    150 percent, unless the application asked for high resolution pixmaps,
    it was shrunk to the logical size and blown up again, and the arrows
    came out lopsided. With every size in the icon, Qt picks the one it
    needs and never scales a drawing."""
    ratios = {1.0, 2.0}
    try:
        ratios.add(max(1.0, float(QApplication.instance().devicePixelRatio())))
    except Exception:
        pass
    icon = QIcon()
    for ratio in sorted(ratios):
        pm = _canvas(size, ratio)
        p = QPainter(pm)
        try:
            p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            paint(p)
        finally:
            p.end()
        icon.addPixmap(pm)
    return icon


def arrow_icon(where, size=12):
    """A small solid triangle pointing up, down, left or right, in the ink
    of the panel's words.

    The arrows of a font are hairlines in every UI face QGIS uses, smaller
    than the 'fit' beside them, and these are the keys pressed while the eye
    is on the map. A shape the size of the key's word reads at a glance."""
    ink = QColor(palette_colours()["text"])

    def paint(p):
        p.setPen(QPen(Qt.PenStyle.NoPen))
        p.setBrush(QBrush(ink))
        a, b, c = size * 0.12, size * 0.5, size * 0.88
        lo, hi = size * 0.22, size * 0.78
        shape = {"up": [(a, hi), (b, lo), (c, hi)],
                 "down": [(a, lo), (b, hi), (c, lo)],
                 "left": [(hi, a), (lo, b), (hi, c)],
                 "right": [(lo, a), (hi, b), (lo, c)]}[where]
        p.drawPolygon(QPolygonF([QPointF(x, y) for x, y in shape]))
    return _icon(size, paint)


def person_icon(size=14):
    """A head and a pair of shoulders, drawn instead of shipped.

    The plugin is one file and has to stay one file, so an icon cannot be a
    .png sitting next to it. Drawing it at call time from the palette also
    means it comes out legible whether QGIS is in its light theme or its dark
    one, instead of being a dark glyph on a dark button."""
    ink = QColor(palette_colours()["text"])

    def paint(p):
        p.setPen(QPen(Qt.PenStyle.NoPen))
        p.setBrush(QBrush(ink))
        head = size * 0.34
        p.drawEllipse(QRectF((size - head) / 2.0, size * 0.10, head, head))
        # the shoulders: a disc with its top half clipped away
        body = size * 0.64
        p.setClipRect(QRectF(0, size * 0.54, size, size * 0.46))
        p.drawEllipse(QRectF((size - body) / 2.0, size * 0.52, body, body))
    return _icon(size, paint)


def padlock_icon(closed=True, size=14):
    """A padlock, shut or open, drawn from the palette like the person is.

    Drawn and not written as a character: the lock glyphs a font may or may
    not have come out as an empty box on one machine and as a colour emoji on
    another, and this one is neither."""
    ink = QColor(palette_colours()["text"])

    def paint(p):
        body = QRectF(size * 0.18, size * 0.46, size * 0.64, size * 0.44)
        p.setPen(QPen(Qt.PenStyle.NoPen))
        p.setBrush(QBrush(ink))
        p.drawRoundedRect(body, size * 0.10, size * 0.10)
        pen = QPen(ink)
        pen.setWidthF(max(1.2, size * 0.11))
        pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        p.setPen(pen)
        p.setBrush(QBrush(Qt.BrushStyle.NoBrush))
        # the shackle: a half circle, upright when shut and tipped over to the
        # side when open, which is the difference the eye actually catches
        left = size * (0.30 if closed else 0.42)
        arc = QRectF(left, size * 0.16, size * 0.40, size * 0.42)
        p.drawArc(arc, 0 * 16, 180 * 16)
        if closed:
            p.drawLine(QPointF(arc.left(), arc.center().y()),
                       QPointF(arc.left(), body.top()))
            p.drawLine(QPointF(arc.right(), arc.center().y()),
                       QPointF(arc.right(), body.top()))
        else:
            p.drawLine(QPointF(arc.left(), arc.center().y()),
                       QPointF(arc.left(), body.top()))
    return _icon(size, paint)

