def hidden_readings(panel, readings):
    """The readings, out of these, that the reader in hand is kept from by the
    Annotate filter (the panel's blind gate, one reading at a time)."""
    gate = getattr(panel, "blind_gate", None)
    if not callable(gate):
        return []
    try:
        return [r for r in readings if gate([r])]
    except Exception as err:
        log("cannot ask whether the readings may be shown: %s" % err)
        return []


def ask_hidden(panel, hidden, subject="These files contain"):
    """True when the files may be written although they hold work hidden from
    the reader in hand: asked once, before anything is written, with Cancel as
    the default. Writing the tables with that work in them and refusing only
    the card would not do: the card is the same work in counts."""
    held = panel.reading() if callable(getattr(panel, "reading", None))         else None
    who = (held or {}).get("operator") or "the reader"
    names = ", ".join("%s pass %d" % (operator_word(r[0]), pass_number(r[1]))
                      for r in hidden)
    answer = QMessageBox.question(
        panel, NAME,
        "%s work hidden from %s (%s). Write %s anyway?"
        % (subject, who, names,
           "them" if subject.startswith("These") else "it"),
        QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.Cancel,
        QMessageBox.StandardButton.Cancel)
    if answer != QMessageBox.StandardButton.Yes:
        log("not written: %s hidden from the reader" % names)
        return False
    return True


def write_card_beside(panel, folder, stem, exports=None, describe=None,
                      ignore_index=None, points_in_mask=False, dot_px=1):
    """The dataset card of the open campaign, written beside the files an
    export or the Whole raster has just made: <stem>_card.md and .json,
    with the SHA-256 of each of those files. The package is read only and
    the manifest is not told. Returns (files, the sentence for the
    information box, the card or None). Never raises: the files it
    describes are written, and a card that could not be is said so. A reader
    kept from some reading's work is asked before the files go out
    (ask_hidden), not here."""
    campaign = panel.campaign
    package = campaign.package_path
    QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
    try:
        card = card_gather_campaign(
            campaign.data, campaign.folder, package, progress=card_progress,
            exports=exports, ignore_index=ignore_index,
            points_in_mask=points_in_mask, describe=describe, dot_px=dot_px,
            where=folder)
        # a card written on its own may be the first file of its folder
        os.makedirs(long_path(folder), exist_ok=True)
        files = card_write(card, folder, stem)
    except Exception as err:
        log("the dataset card could not be written: %s" % err, loud=True)
        return [], "The dataset card could not be written: %s" % err, None
    finally:
        QApplication.restoreOverrideCursor()
        card_say("")
    text = "Dataset card: %s and .json. %s" % (card_names(stem)[0],
                                               card_summary(card))
    stale = card_stale_lines(card)
    if stale:
        text += "\n" + "\n".join(stale)
    log("dataset card written: %s" % ", ".join(files))
    return files, text, card


def cut_ignore_rule(own, readings, want):
    """What a layer cut as classes holds where it holds nothing:
    (ignore value or None, whether its 0 means "nobody painted", where the
    value comes from), by the first of these that holds.

    1. The file carries an ignore value of its own (RASTERLABEL_IGNORE_INDEX,
       written by Whole or by an earlier cutout of the folder): that one,
       whatever the dock says. Its 0, if any, is a class ("none of these" in
       a frame).
    2. The dock is off: nothing, which is how RasterLabel 1.0 cut it, bit
       for bit.
    3. A mask of a campaign written by Whole with 0 where nobody painted
       (it says which readings it holds): the dock's value, and its 0 is
       "nobody painted".
    4. Any other map: the dock's value for the padding and the map's own
       nodata only; its 0 may be a class and is kept."""
    if own not in (None, ""):
        try:
            return int(float(own)), False, "file"
        except (TypeError, ValueError):
            pass
    if want is None:
        return None, False, None
    if readings:
        return int(want), True, "campaign mask"
    return int(want), False, "map"


def cut_class_entries(classes, ignore):
    """The classification:classes of a STAC asset (classification extension
    v2.0.0): every class the style names, its name made fit for the
    extension's pattern and its own words kept as the title, and the ignore
    value marked as nodata, which is what the extension says it is."""
    out = []
    for c in classes or []:
        code = int(c["code"])
        if ignore is not None and code == int(ignore):
            continue
        words = c.get("name") or "code %d" % code
        out.append({"value": code, "name": tidy(words, "class_%d" % code),
                    "title": words})
    if ignore is not None:
        out.append({"value": int(ignore), "name": "ignore",
                    "description": "nobody labelled it; leave it out of "
                                   "training", "nodata": True})
    return out


def write_atomic(path, text):
    """text at path whole or not at all: written under a temporary name,
    flushed to the disk, then renamed over the old file. A crash, or a full
    disk, in the middle leaves the old file as it was, not the first half of
    a new one. Raises OSError, with the temporary file taken away."""
    spare = long_path(path + ".tmp")
    try:
        with open(spare, "w", encoding="utf-8") as f:
            f.write(text)
            f.flush()
            try:
                os.fsync(f.fileno())
            except OSError:
                pass            # a file system that cannot is no reason to fail
        os.replace(spare, long_path(path))
    except OSError:
        try:
            os.remove(spare)
        except OSError:
            pass
        raise


# Two small files that describe the cutouts folder itself, beside cutouts.csv:
# the layers the cutouts were cut from, so the next session cuts the same
# ones, and a note that a cutout is being written, so a crash in the middle of
# one can be found and cleaned.
LAYERS_FILE = "layers.json"
PENDING_FILE = "cutting.pending"


def layer_key(source):
    """A layer's file spelled so that two spellings of one file are equal,
    which is what the folder remembers a layer by: the id of a layer is made
    up again every time a project is opened, and its name is whatever it was
    called."""
    source = clean_source(str(source or "").split("|")[0].strip())
    if not source or "://" in source:
        return source
    return os.path.normcase(os.path.normpath(source))


def source_moment(ds):
    """When the image of a raster was taken, as STAC writes it
    (2025-03-14T10:22:31Z), if the file says so; "" when it does not.

    Read from what a GeoTIFF of a camera or a sensor keeps: the TIFF date
    tag, which has no time zone and is taken as UTC, and the acquisition
    time some producers write. A file that says nothing says nothing: the
    moment a cutout was cut is not the moment the ground was seen."""
    try:
        items = ds.GetMetadata() or {}
    except Exception:
        return ""
    for key, shapes in (
            ("TIFFTAG_DATETIME", ("%Y:%m:%d %H:%M:%S", "%Y-%m-%d %H:%M:%S")),
            ("ACQUISITIONDATETIME", ("%Y-%m-%dT%H:%M:%SZ", "%Y-%m-%dT%H:%M:%S",
                                     "%Y:%m:%d %H:%M:%S")),
            ("ACQUISITION_DATE", ("%Y-%m-%dT%H:%M:%SZ", "%Y-%m-%d"))):
        text = str(items.get(key) or "").strip()
        for shape in shapes:
            try:
                return datetime.strptime(text, shape).strftime(
                    "%Y-%m-%dT%H:%M:%SZ")
            except ValueError:
                continue
    return ""


class CutoutsSection(QGroupBox):
    """Cuts windows out of the layers you already have, and writes a dataset.

    This is the other job, not the annotating one. You have a map of ground
    truth and some imagery of the same place, in whatever mixture of bands and
    resolutions; you pick a window, and out comes one file per layer, on one
    common pixel grid so that they stack.

    What is drawn by hand does not come through here. The annotation of a
    campaign is written from Annotate, where it lives and where the operator
    and pass filters apply; burning it here as well would have produced the
    same reading out of two places under two different sets of rules. The
    ground truth of a cutout is a LAYER somebody marked "classes". The one
    exception is the boxes of Objects, which no layer carries: they are
    written from the campaign as detection labels in the pixels of each image
    (boxes_coco.json and labels/), when there are any.

    It needs no campaign and writes none. What it cuts is the raster layers
    of the project, on a window you choose, and what it writes is the folder
    of cutouts and the files that describe them. How it was last set up is
    remembered by QGIS on this machine. An annotation campaign that happens
    to be open is only ever read: for its frames (All tiles), for its drawing
    (Whole), and once for the folder an earlier build kept its cutouts in."""

    def __init__(self, panel):
        super().__init__("")
        self.panel = panel
        self.campaign = panel.campaign          # read, never written
        self.geometry = None
        if self.campaign is not None:
            reference = find_mine(self.campaign.data["id"], "tiles") \
                or find_mine(self.campaign.data["id"], "polygons")
            self.geometry = Geometry(
                self.campaign, reference.crs() if reference is not None else None)
        self.tiled = bool(self.campaign is not None
                          and self.campaign.data.get("with_tiles"))
        self.sources = []
        self.ignored = {}         # layers unticked in the Layers panel
        self.tool = None
        self.written = []
        self.skipped = {}         # tag -> why the last cutout left it out
        self.gone = []            # cutouts listed in the books, not on disk
        self.folder = self.remembered_folder()
        self.settle_interrupted()
        self.count = self.count_existing()
        self.measure = QgsDistanceArea()
        self.aim_measure()
        self.build()
        self.pick_layers(silent=True)
        # Once the panel holds this module, which is just after it is made:
        # the log then goes to the folder of the program if there is a
        # cutouts folder already.
        panel_ = self.panel
        QTimer.singleShot(0, lambda: CutoutsSection.reroute(panel_))

    # ----------------------------------------------------------- the panel
    SETTINGS = SETTINGS_ROOT + "/cutouts/"

    def setting(self, key, default, kind=str):
        return read_setting(self.SETTINGS + key, default, kind)

    def keep_setting(self, key, value):
        write_setting(self.SETTINGS + key, value)

    def default_folder(self):
        """A "cutouts" folder beside the QGIS project, and one in the home
        folder when the project has never been saved. Not beside the campaign
        manifest, which there may not be."""
        try:
            home = QgsProject.instance().homePath()
        except Exception:
            home = ""
        # normpath: QGIS spells its folders with slashes, and joined to a
        # backslash that is a path with both in it on Windows
        if home and os.path.isdir(home):
            return os.path.normpath(os.path.join(home, "cutouts"))
        return os.path.join(os.path.expanduser("~"), NAME, "cutouts")

    def remembered_folder(self):
        """Where the cutouts go: the folder chosen last time, on this machine.

        It is not kept in the campaign manifest, which would tie the module to
        a campaign it has no other use for: QGIS remembers it. The one
        thing still read from a campaign is the folder RasterLabel 1.0 kept
        there, once, when QGIS has nothing yet: so a dataset that was being
        written goes on in the same place. The manifest is never written."""
        want = (self.setting("folder", "") or "").strip()
        if not want and self.campaign is not None:
            want = (self.campaign.data.get("cutouts_folder") or "").strip()
        return want or self.default_folder()

    def remember_folder(self, folder):
        """Keep the choice in QGIS, so it is the same tomorrow.

        Written even when it is the default, because "no answer" and "the
        default, chosen on purpose" are not the same thing."""
        folder = (folder or "").strip() or self.default_folder()
        self.keep_setting("folder", folder)
        return folder

    def folder_changed(self, *args):
        """A new folder means a new set of names already taken.

        free_name() asks the folder, so nothing can be overwritten either way,
        but the count on the panel has to be the one of the new folder.

        It is connected to editingFinished, which Qt sends every time the box
        merely loses focus. Every click from the box to the map would come
        here, forget what this session had cut and leave Undo saying "nothing
        cut in this session" about the cutout still on the screen. Only a
        folder that is really another one starts afresh."""
        folder = self.remember_folder(self.folder_box.text())
        if self.folder_box.text() != folder:
            self.folder_box.setText(folder)
        if self.same_folder(folder, self.folder):
            return
        self.folder = folder
        # undo cannot reach into a folder we have left behind
        self.written = []
        self.settle_interrupted()
        self.count = self.count_existing()
        # A folder that has been cut before says which layers it was cut
        # from and as what: the same ones, the same grid, the same names.
        # Nothing else changes the layers of a session behind its back.
        self.restore_layers()
        self.show_state()
        self.route_log()
        log("cutouts go to %s (%d already there)" % (folder, self.count))

    @staticmethod
    def same_folder(a, b):
        """Two spellings of one folder: a slash at the end, the other slash,
        another case on Windows."""
        if not a or not b:
            return False
        return (os.path.normcase(os.path.abspath(a))
                == os.path.normcase(os.path.abspath(b)))

    def route_log(self):
        """Ask the panel to point the log file at this folder, now that there
        may be one: with no campaign open it is the only folder Cutouts has,
        and the log would go nowhere at all."""
        CutoutsSection.reroute(self.panel)

    @staticmethod
    def reroute(panel):
        try:
            panel.route_log()
        except Exception:
            pass

    def folder_is_usable(self):
        """Can we actually write there? Asked once, before the first file.

        Finding out halfway through a batch means half a dataset and a dialog
        about a GeoTIFF, which is a confusing way to be told that a folder is
        read only or that a drive is not plugged in."""
        folder = self.folder or self.default_folder()
        try:
            os.makedirs(long_path(folder), exist_ok=True)
        except OSError as err:
            QMessageBox.critical(
                self, NAME,
                "The cutouts folder cannot be made:\n\n%s\n\n%s\n\n"
                "Pick another one under Settings." % (folder, err))
            return False
        probe = os.path.join(folder, ".rasterlabel_write_test")
        try:
            with open(long_path(probe), "w") as f:
                f.write("x")
            os.remove(long_path(probe))
        except OSError as err:
            QMessageBox.critical(
                self, NAME,
                "Nothing can be written into the cutouts folder:\n\n%s\n\n%s"
                % (folder, err))
            return False
        # The folder is there now, so the log can go into it.
        self.route_log()
        return True

    def choose_folder(self):
        got = QFileDialog.getExistingDirectory(
            self, "Where the cutouts go", self.folder or self.default_folder())
        if not got:
            return
        self.folder_box.setText(got)
        self.folder_changed()

    def build(self):
        follows_width(self)
        outer = QVBoxLayout(self)
        outer.setContentsMargins(8, 8, 8, 8)
        outer.setSpacing(7)

        self.state = QLabel("")
        self.state.setWordWrap(True)
        self.state.setObjectName("quiet")
        outer.addWidget(self.state)

        groups = [[self._act("Layers", "Choose which layers are cut and as what.",
                             self.pick_layers)],
                  [self._act("Cut", "Click on the map for a square, drag for a\n"
                                    "free rectangle. Right click undoes the last\n"
                                    "one, Esc stops cutting.", self.start_cutting)]]
        # Both read the annotation campaign: its frames, its drawing. Without
        # one there is nothing for them to read, so they are not shown.
        if self.tiled:
            groups.append([self._act(
                "All tiles", "Cut one subset for every tile of the campaign.",
                self.export_all_tiles)])
        if self.campaign is not None:
            groups.append([self._act(
                "Whole",
                "The whole raster, in one piece.\n\n"
                "Write a whole raster out, with the annotation of the campaign on\n"
                "it. The one place in this module that does look at the hand\n"
                "drawing, because a river traced across a scene has no frames to\n"
                "cut and its extent is the picture itself.\n\n"
                "For work with no frames: a river traced across the scene, a\n"
                "coastline, anything whose extent is the picture itself. Comes out\n"
                "as the image with the annotation painted over, a mask of class\n"
                "codes, the plain image, or a picture for a figure, at full size or\n"
                "scaled down.",
                self.export_whole)])
        # Folder before Undo: Undo deletes a file, and goes last.
        groups.append([self._act("Folder", "Open the output folder.",
                                 self.show_folder),
                       self._act("Undo", "Delete the last cutout from disk.",
                                 self.undo, danger=True)])
        self.deck = Deck()
        # Rows of equal keys with nothing left alone: four are two and two
        # or one row of four, five and six are rows of three.
        keys = sum(len(g) for g in groups)
        self.deck.add(bar(groups, counts=(2, 4) if keys == 4 else (3,)), 2)

        self.settings_box = QVBoxLayout()
        self.settings_box.setSpacing(5)
        self.fold = QToolButton()
        self.fold.setText(" Settings")
        self.fold.setCheckable(True)
        self.fold.setArrowType(Qt.ArrowType.RightArrow)
        self.fold.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextBesideIcon)
        self.fold.setAutoRaise(True)
        self.fold.setObjectName("fold")
        self.fold.setFocusPolicy(Qt.FocusPolicy.TabFocus)
        self.fold.toggled.connect(self.show_settings)
        self.settings_box.addWidget(self.fold, 0, Qt.AlignmentFlag.AlignLeft)

        self.settings = follows_width(QWidget())
        inner = QVBoxLayout(self.settings)
        inner.setContentsMargins(8, 0, 0, 2)
        inner.setSpacing(5)

        self.side = QDoubleSpinBox()
        self.side.setRange(0.5, 5000.0)
        self.side.setDecimals(2)
        self.side.setSuffix(" m")
        self.side.setFixedWidth(FIELD_W)
        kept = self.setting("side_m", 0.0, float)
        self.side.setValue(round(kept if kept > 0
                                 else TILE_SIDE_PX * self.cutting_pixel()[0], 2))
        self.side.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.side.valueChanged.connect(self.show_state)
        self.side.valueChanged.connect(
            lambda v: self.keep_setting("side_m", float(v)))
        self.side_px = QLabel("")
        self.side_px.setObjectName("quiet")
        inner.addLayout(self._field("side", self.side, self.side_px))

        self.prefix = QLineEdit(self.setting("prefix", "cut") or "cut")
        self.prefix.setFixedWidth(FIELD_W)
        self.prefix.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.prefix.editingFinished.connect(
            lambda: self.keep_setting("prefix", self.prefix.text().strip()))
        inner.addLayout(self._field("prefix", self.prefix))

        row = QHBoxLayout()
        row.setSpacing(6)
        word = QLabel("folder")
        word.setFixedWidth(max(LABEL_W,
                               text_width(word.fontMetrics(), "folder") + 6))
        row.addWidget(word)
        self.folder_box = QLineEdit(self.folder)
        self.folder_box.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.folder_box.setToolTip(
            "Where the cutouts are written. Remembered by QGIS on this machine,\n"
            "not in any campaign: Cutouts needs none and saves none. Leave it\n"
            "empty to go back to a 'cutouts' folder beside the QGIS project.\n\n"
            "Changing it starts a fresh count from whatever is already in the\n"
            "new folder, and nothing there is ever overwritten: a name that is\n"
            "taken is skipped.")
        self.folder_box.editingFinished.connect(
            shielded(self.folder_changed, "Folder"))
        row.addWidget(self.folder_box, 1)
        pick = QPushButton("...")
        pick.setFixedWidth(30)
        pick.setFocusPolicy(Qt.FocusPolicy.TabFocus)
        pick.setToolTip("Choose the folder.")
        pick.clicked.connect(shielded(self.choose_folder, "Folder"))
        row.addWidget(pick)
        inner.addLayout(row)

        # The second half: not what a cutout contains but how the folder is
        # written. Its own block, so a wide panel sets them side by side.
        self.written_how = follows_width(QWidget())
        inner = QVBoxLayout(self.written_how)
        inner.setContentsMargins(8, 0, 0, 2)
        inner.setSpacing(5)

        self.png = WrapTick("also write PNG copies")
        self.png.setChecked(self.setting("png", True, bool))
        self.png.toggled.connect(
            lambda on, k="png": self.keep_setting(k, bool(on)))
        self.png.setFocusPolicy(Qt.FocusPolicy.TabFocus)
        self.png.setToolTip(
            "Pictures for looking at: no coordinates, transparent outside the\n"
            "cutout and where the image has no data. An image comes out as it\n"
            "is shown in QGIS, with the bands and the stretch of its style;\n"
            "classes are painted with the colours of their style. A classes\n"
            "layer written as PNG keeps its codes in the main PNG and gets the\n"
            "coloured picture beside it, as _classes_colour.png.")
        inner.addWidget(self.png)

        self.common = WrapTick("one common pixel grid")
        self.common.setChecked(self.setting("common", True, bool))
        self.common.toggled.connect(
            lambda on, k="common": self.keep_setting(k, bool(on)))
        self.common.setFocusPolicy(Qt.FocusPolicy.TabFocus)
        self.common.setToolTip(
            "On, every layer is read onto the grid of the layer chosen in\n"
            "Layers to set it, and all the files of a cutout have the same\n"
            "size. A layer that sits elsewhere is resampled: classes by the\n"
            "class most of a larger pixel holds, or the one under the centre\n"
            "of a smaller one, so no code is ever invented; an image averaged\n"
            "onto a larger pixel and interpolated onto a smaller one. Off,\n"
            "each layer keeps its own grid and the sizes can differ by a pixel.\n"
            "A layer in another coordinate system is always reprojected onto\n"
            "the common grid.")
        inner.addWidget(self.common)

        self.same_size = WrapTick("same size for all")
        self.same_size.setChecked(self.setting("same_size", True, bool))
        self.same_size.toggled.connect(
            lambda on, k="same_size": self.keep_setting(k, bool(on)))
        self.same_size.setFocusPolicy(Qt.FocusPolicy.TabFocus)
        self.same_size.setToolTip(
            "The first cutout of a given side fixes how many pixels that side\n"
            "is, and every later one of the same side comes out exactly that\n"
            "size, padded with nodata where it runs past the edge of the\n"
            "raster. Without this two frames of the same metres can differ by\n"
            "one pixel depending on where they fall, and a loader that stacks\n"
            "the pieces into a batch refuses them. Freehand rectangles are not\n"
            "touched: they were asked for free.")
        inner.addWidget(self.same_size)

        # Where a layer cut as classes holds nothing: off, as RasterLabel 1.0
        # cut it, the padding past the edge is 0 and so is
        # the map's own nodata. On, they are the ignore value, declared as
        # the nodata of the cutout, so a loss told ignore_index leaves them
        # out. A 0 of a map made elsewhere is left alone: it may be a class.
        row_ignore = QWidget()
        self.ignore_on = WrapTick(
            "unlabelled as ignore",
            room=lambda: row_ignore.width() - self.ignore_value.width() - 6)
        self.ignore_on.watch_row(row_ignore)
        self.ignore_on.setChecked(self.setting("ignore_on", False, bool))
        self.ignore_on.setFocusPolicy(Qt.FocusPolicy.TabFocus)
        self.ignore_value = QSpinBox()
        self.ignore_value.setRange(-32768, 65535)
        self.ignore_value.setFixedWidth(FIELD_W)
        self.ignore_value.setValue(self.setting("ignore_value", IGNORE_CODE,
                                                int))
        self.ignore_value.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        tip = ("Layers cut as classes: the edge padding, the layer's own\n"
               "nodata, and the 0 of a mask written by Whole become this\n"
               "value, declared as nodata. A 0 in any other map is left alone:\n"
               "it may be a class. A mask that already carries an ignore\n"
               "value keeps its own. It is not a foreground: samgeo and\n"
               "Deepness write 255 for that.")
        self.ignore_on.setToolTip(tip)
        self.ignore_value.setToolTip(tip)
        self.ignore_on.toggled.connect(
            lambda on: (self.keep_setting("ignore_on", bool(on)),
                        self.ignore_value.setEnabled(bool(on))))
        self.ignore_value.valueChanged.connect(
            lambda v: self.keep_setting("ignore_value", int(v)))
        self.ignore_value.setEnabled(self.ignore_on.isChecked())
        ignore_line = QHBoxLayout(row_ignore)
        ignore_line.setContentsMargins(0, 0, 0, 0)
        ignore_line.setSpacing(6)
        ignore_line.addWidget(self.ignore_on)
        ignore_line.addWidget(self.ignore_value)
        ignore_line.addStretch(1)
        self.row_ignore = row_ignore
        inner.addWidget(row_ignore)

        self.stac = WrapTick("STAC catalogue")
        self.stac.setChecked(self.setting("stac", True, bool))
        self.stac.toggled.connect(
            lambda on, k="stac": self.keep_setting(k, bool(on)))
        self.stac.setFocusPolicy(Qt.FocusPolicy.TabFocus)
        self.stac.setToolTip(
            "Writes a stac folder beside the cutouts: one item per cutout,\n"
            "listing the files really written, the roles they were cut as,\n"
            "the projection and the exact transform. It is what makes the\n"
            "folder readable by something that was not told how we name our\n"
            "files. An item whose files are no longer on disk is left out of\n"
            "catalog.json, and kept in the stac folder.")
        inner.addWidget(self.stac)

        # Boxes for detection training: the one thing drawn by hand that has
        # no layer to come through, so it is written from the campaign here,
        # in the pixels of each cutout. Only with a campaign that has boxes.
        self.boxes = WrapTick("boxes for detection")
        self.boxes.setChecked(self.setting("boxes", True, bool))
        self.boxes.toggled.connect(
            lambda on, k="boxes": self.keep_setting(k, bool(on)))
        self.boxes.setFocusPolicy(Qt.FocusPolicy.TabFocus)
        self.boxes.setToolTip(
            "The boxes of the campaign (Objects), cut to each cutout and\n"
            "written in its pixels: boxes_coco.json for the whole folder\n"
            "(COCO, category_id the class code) and, in labels/, one text\n"
            "file per image in the YOLO form, with classes.txt naming the\n"
            "indices. A cutout keeps the boxes the campaign held when it was\n"
            "cut. Written only when the campaign has boxes, and for images:\n"
            "a layer cut as classes has none.\n"
            "Every image over ground that was read gets its file, empty when\n"
            "no box falls in it, and an empty file reads as a picture with\n"
            "nothing in it. In a campaign with frames, ground outside them\n"
            "was not read: an image the frames do not cover gets no file and\n"
            "is listed under unlabelled_images in the book, to be left out of\n"
            "training.")
        inner.addWidget(self.boxes)
        self.boxes_reading = None
        self.boxes_choices = []
        if self.campaign_package():
            # one reading, or all of them together: two people who read the
            # same ground would otherwise put every object in twice
            self.boxes_reading, self.boxes_choices = \
                self.reading_box_of_boxes()
            inner.addWidget(self.boxes_reading)

        self.settings.setVisible(False)
        self.written_how.setVisible(False)
        self.more_settings = [self.written_how]
        self.settings_box.addWidget(self.settings)
        self.deck.add(self.settings_box, 3)
        self.deck.add(self.written_how, 3)

        self.deck.deal(force=True)
        outer.addWidget(self.deck)

        self.show_state()

    _act = AnnotationSection.__dict__["_act"]
    _field = AnnotationSection.__dict__["_field"]
    show_settings = AnnotationSection.__dict__["show_settings"]

    def campaign_package(self):
        """The GeoPackage of the campaign, or None with no campaign."""
        return getattr(self.campaign, "package_path", None)

    def reading_box_of_boxes(self):
        """The readings the boxes can be taken from: all of them together, or
        one. The consensus the pixel windows offer has no meaning for a box."""
        choices = [c for c in reading_choices(
            readings_in(self.campaign_package()))
            if c["mode"] in ("all", "one")]
        box = QComboBox()
        for c in choices:
            box.addItem("boxes of " + c["label"])
        short_combo(box, 14)    # a reading with a long name is cut, not wide
        box.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        box.setToolTip(
            "Whose boxes go to the detection files. All readings together\n"
            "puts an object in once for every reading that boxed it: for a\n"
            "campaign read by several people, choose one.")
        return box, choices

    def cutting_pixel(self):
        """The pixel the cutouts are actually taken on, and whose it is.

        The first chosen layer, because that is the grid every other one is
        read onto. Until a layer has been chosen the raster selected in the
        panel stands in for it, then the grid of a campaign if one is open,
        then a pixel of one unit: the two are not always the same size, so the
        count is shown with a star until it is the real one."""
        if self.sources:
            # On the ground, like the side it divides. rasterUnitsPerPixelX()
            # is in the units of the layer, and on a layer in degrees a side
            # of ten metres came out as tens of millions of pixels.
            try:
                px = float(pixel_on_the_ground(self.sources[0]["layer"])[0])
                if px > 0:
                    return px, "layer"
            except (TypeError, ValueError, AttributeError):
                pass
        try:
            raster = self.panel.active_raster()
        except Exception:
            raster = None
        if raster is not None:
            try:
                px = float(pixel_on_the_ground(raster)[0])
                if px > 0:
                    return px, "panel"
            except (TypeError, ValueError, AttributeError):
                pass
        if self.geometry is not None:
            return self.geometry.pixel_m[0], "campaign"
        return 1.0, None

    def resizeEvent(self, ev):
        """The folder line is cut to the width, so a new width is a new cut."""
        QGroupBox.resizeEvent(self, ev)
        if getattr(self, "side_px", None) is not None:
            self.show_state()

    def show_state(self, *args):
        px, whose = self.cutting_pixel()
        self.side_px.setText("%d px%s" % (int(round(self.side.value() / px))
                                          if px else 0,
                                          "" if whose == "layer" else " *"))
        if whose == "layer":
            self.side_px.setToolTip(
                "On the grid of %s, the layer that sets the grid: that is the "
                "grid every other layer is read onto." % self.sources[0]["tag"])
        elif whose == "panel":
            self.side_px.setToolTip(
                "On the grid of %s, the raster selected in the panel, marked "
                "with a star because no layer has been chosen yet. The layer "
                "that is cut first may have a pixel of a different size, and "
                "then this count changes." % self.panel.active_raster().name())
        else:
            self.side_px.setToolTip(
                "On the grid of the %s, marked with a star because no layer "
                "has been chosen yet. The layer that is cut first may have a "
                "pixel of a different size, and then this count changes."
                % ("campaign" if whose == "campaign" else "unit pixel"))
        # What is cut, and what the last cutout really wrote. A line made
        # from what was asked for alone would read "aragona as image" through
        # a whole session in which every cutout had left the image out; the
        # reason would be in a warning that the next message covers.
        warn = palette_colours()["danger"]
        roles = ", ".join(
            "%s as %s" % (s["tag"], s["role"])
            + ("" if s["tag"] not in self.skipped else
               " <span style='color:%s'>(left out of the last cutout: %s)"
               "</span>" % (warn, self.skipped[s["tag"]]))
            for s in self.sources)
        gone = ""
        if self.gone:
            gone = ("<br><span style='color:%s'>%d listed in cutouts.csv but "
                    "no longer on disk: %s%s (the log has the rest)</span>"
                    % (warn, len(self.gone), ", ".join(self.gone[:3]),
                       ", ..." if len(self.gone) > 3 else ""))
        # Where they land, always in sight. A dataset written into the wrong
        # folder is not lost, but it is not found either, and the moment to
        # notice is before the first cut and not after the hundredth.
        where = self.folder or self.default_folder()
        # Cut in the middle to the width the line has, so both ends of the
        # path stay in sight: cut at forty-six letters it broke after the
        # drive and ran off the edge of a narrow panel.
        room = self.state.contentsRect().width()
        if room < 60:
            room = 200
        metrics = self.state.fontMetrics()
        short = metrics.elidedText(where, Qt.TextElideMode.ElideMiddle,
                                   max(room - text_width(metrics, "into "), 40))
        self.state.setText(
            "<b>%d</b> cutout%s written<br>%s<br>"
            "<span style='color:%s'>into %s</span>%s%s"
            % (self.count, "" if self.count == 1 else "s",
               roles or "no layer chosen yet: press <b>Layers</b>",
               palette_colours()["dim"], escape(short), gone,
               "" if self.campaign is not None else
               "<br><span style='color:%s'>no campaign needed, none written"
               "</span>" % palette_colours()["dim"]))
        self.state.setToolTip(where)
        if self.campaign is None:
            # Why All tiles and Whole are missing, where it is asked: the
            # status was six lines of grey prose above the buttons.
            self.state.setToolTip("%s\n\nAll tiles and Whole need an "
                                  "annotation campaign." % where)

    # ----------------------------------------------------------- the layers
    def export_whole(self):
        """The whole raster, with everything drawn on it.

        Saved first, always. An export that quietly misses the last ten minutes
        of drawing is worse than no export, because nothing about it looks
        wrong."""
        panel = self.panel
        if panel.section is not None and panel.section.unsaved():
            try:
                panel.section.save()
            except Exception as err:
                log("could not save before exporting the whole raster: %s" % err)
        if panel.annotation is not None and panel.annotation.unsaved():
            try:
                panel.annotation.save()
            except Exception as err:
                log("could not save the annotation: %s" % err, loud=True)
        # Whole is reached from Cutouts, where neither of those two modules is
        # open, so what is still in a table's buffer is asked of the tables
        # themselves, as every other export does (panel.pending_layers). A
        # package that failed to save when Annotate was closed, a rename
        # that could not be written, a recovery put back that did not commit:
        # all of it is missing from the file the mask is burned from, and
        # what is missing is labelled as background.
        left = []
        try:
            if panel.pending_layers():
                left = panel.flush_layers()
        except Exception as err:
            log("could not write the layers before exporting the whole "
                "raster: %s" % err)
        # If anything is still unsaved after that, the export would be made
        # from the package on disk and would quietly miss the last stretch of
        # work. Better to stop and ask than to hand over a dataset that is
        # wrong in a way nothing about it shows.
        still = [m for m in (panel.section, panel.annotation)
                 if m is not None and m.unsaved()]
        try:
            waiting = panel.pending_layers()
        except Exception:
            waiting = []
        if still or left or waiting:
            q = QMessageBox.warning(
                self, NAME,
                "Not everything could be saved, so the raster will be made "
                "from the package as it stands on disk, without it:\n\n%s\n\n"
                "Where nothing is drawn in the file the mask is background. "
                "Export anyway?"
                % ("\n".join(left) if left else
                   "some work is still waiting to be written."),
                QMessageBox.StandardButton.Yes
                | QMessageBox.StandardButton.Cancel,
                QMessageBox.StandardButton.Cancel)
            if q != QMessageBox.StandardButton.Yes:
                return

        if self.campaign is None:
            return
        dialog = WholeRaster(self, self.campaign,
                             os.path.join(self.campaign.folder, "whole"))
        if run_dialog(dialog) != QDialog.DialogCode.Accepted:
            return
        r = dialog.result()
        if r["layer"] is None:
            QMessageBox.warning(self, NAME, "No raster is loaded.")
            return
        # The card is not a raster: it is written after them, beside them.
        want_card = "card" in r["kinds"]
        r["kinds"] = [k for k in r["kinds"] if k != "card"]
        if not r["kinds"] and not want_card:
            QMessageBox.information(self, NAME, "Nothing was chosen.")
            return
        if not r["folder"]:
            QMessageBox.warning(self, NAME, "Say where to write it.")
            return

        layer = r["layer"]
        ds = open_raster(source_of(layer))
        if ds is None:
            QMessageBox.critical(
                self, NAME, "That raster cannot be read." if
                CutoutsSection.is_file_layer(layer) else
                "That raster cannot be read: it is not a file but a web or "
                "database layer.")
            return
        os.makedirs(r["folder"], exist_ok=True)

        bands = renderer_bands(layer)
        limits = display_limits(layer, bands)
        if limits is None:
            limits = self.guess_limits(ds, bands, r["scale"])
        colours = {c["code"]: (QColor(c["colour"]).red(),
                               QColor(c["colour"]).green(),
                               QColor(c["colour"]).blue())
                   for c in self.campaign.active_classes()}

        # The same stem the layers are named with, so a table on disk and
        # the layer it came from answer to the same word.
        stem = self.campaign.stem
        stem = "%s_%s" % (stem, tidy_tag(layer.name(), "raster"))
        choice = r.get("reading") or {"mode": "all"}
        # one reading, or a consensus, is said in the name as well as inside
        # the file: the mask of every reading together keeps the name it
        # always had
        if choice.get("tag"):
            stem += "_" + choice["tag"]
        # and the value where nobody painted, when it is not 0: two masks of
        # the same reading, one with 0 and one with 255, are two files
        unlabelled = r.get("unlabelled") or "zero"
        ignore = r.get("ignore") if unlabelled != "zero" else None
        if ignore is None:
            unlabelled = "zero"
        tag = unlabelled_tag(unlabelled, ignore)
        if tag:
            stem += "_" + tag
        if r["scale"] > 1:
            stem += "_1of%d" % r["scale"]
        ext = r["extension"]
        # a mask never goes out as JPEG, whatever was picked: the codes are
        # meaning, not brightness, and a lossy codec would shuffle them; nor
        # as a PNG with a negative ignore value, which needs 16 signed bits
        # and a PNG has none
        mask_driver, mask_ext = (
            ("GTiff", ".tif") if not r["exact"]
            or (ignore is not None and ignore < 0 and r["driver"] == "PNG")
            else (r["driver"], ext))
        plan = {"painted": (stem + "_annotated" + ext, r["driver"]),
                "mask": (stem + "_mask" + mask_ext, mask_driver),
                "plain": (stem + "_image" + ext, r["driver"]),
                "figure": (stem + "_figure.png", "PNG"),
                "votes": (stem + "_votes.tif", "GTiff")}
        kinds = list(r["kinds"])
        # A consensus mask says which class won; the votes beside it say by
        # how much, and where the readings painted and did not agree.
        if choice.get("mode") == "consensus" and "mask" in kinds:
            kinds.append("votes")
        outputs = [(k, os.path.join(r["folder"], plan[k][0]), plan[k][1])
                   for k in kinds]
        card_stem = stem
        card_files = [os.path.join(r["folder"], n)
                      for n in card_names(card_stem)] if want_card else []
        # A card holds every reading's counts: a reader kept from some of
        # them is asked once, before anything is written.
        if want_card:
            hidden = hidden_readings(self.panel, sorted(
                readings_in(self.campaign.package_path),
                key=lambda x: (x[1], x[0])))
            if hidden and not ask_hidden(self.panel, hidden,
                                         "The dataset card holds"):
                return
        clashing = [p for _, p, _ in outputs if os.path.exists(p)] + [
            p for p in card_files if os.path.exists(p)]
        # the legend written beside a mask is a file of its own, and one
        # that is there already is followed and rewritten
        clashing += [style_of(p) for k, p, _ in outputs
                     if k == "mask" and os.path.exists(style_of(p))]
        if clashing:
            q = QMessageBox.question(
                self, "Whole raster",
                "These are already there and would be replaced:\n\n%s\n\nGo on?"
                % "\n".join(os.path.basename(c) for c in clashing))
            if q != QMessageBox.StandardButton.Yes:
                return

        recipe = dict(r["extras"])
        # the layer too, so the pictures are drawn with its style, as the
        # screen has them; the bands and the limits are for when they cannot be
        recipe.update({"ds": ds, "layer": layer,
                       "scale": r["scale"], "rgb": bands,
                       "limits": limits, "alpha": r["alpha"],
                       "colours": colours, "outputs": outputs,
                       # the legend of the mask: code, name and colour of
                       # every class, written into it and beside it
                       "classes": [dict(c) for c in
                                   self.campaign.active_classes()],
                       "package": self.campaign.package_path,
                       "reading": choice,
                       "unlabelled": unlabelled, "ignore": ignore,
                       # the build, the campaign and the pixel rule inside
                       # every GeoTIFF, and the card's name when one goes
                       # beside it; and the counts as written, for the card
                       "provenance": card_provenance_metadata(
                           self.campaign.data,
                           card_files[1] if card_files else None),
                       "tally": {}})

        written, size = [], None
        if outputs:
            bar = iface.messageBar().createMessage(NAME,
                                                   "writing the whole raster")
            # The level is the enum, never the 0 it is worth: PyQt6 refuses
            # an int here, and on QGIS 4 Whole stopped on a TypeError before
            # writing anything, whatever the raster.
            iface.messageBar().pushWidget(bar, LEVEL_INFO)
            QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
            try:
                written, size = paint_whole(recipe, progress=self.tick_whole)
            except Exception as err:
                QApplication.restoreOverrideCursor()
                iface.messageBar().popWidget(bar)
                QMessageBox.critical(self, NAME,
                                     "Nothing was written:\n\n%s" % err)
                log("whole raster export failed: %s" % err)
                return
            finally:
                ds = None
            QApplication.restoreOverrideCursor()
            iface.messageBar().popWidget(bar)
        ds = None
        message = ""
        if written:
            message = ("%d file%s of %d x %d pixels written in\n%s\n\n"
                       "Readings: %s."
                       % (len(written), "" if len(written) == 1 else "s",
                          size[0], size[1], r["folder"],
                          reading_rule(choice,
                                       recipe.get("consensus_partial"))))
            if "mask" in kinds:
                message += "\nUnlabelled: %s." % unlabelled_rule(
                    unlabelled, ignore, choice.get("mode") == "consensus")
                legend = [os.path.basename(p)
                          for p in recipe.get("sidecars") or []]
                if legend:
                    inside = any(d == "GTiff" for k, _, d in outputs
                                 if k == "mask")
                    message += (
                        "\nLegend of the classes: %s beside the mask%s."
                        % (", ".join(legend),
                           ", and inside it" if inside else ""))
        if want_card:
            message += "\n\n" if message else ""
            message += self.whole_card(recipe, outputs, written, choice,
                                       card_stem, r)
        QMessageBox.information(self, NAME, message)
        log("whole raster (%s): %s"
            % (choice.get("label", "all readings together"),
               ", ".join(os.path.basename(f) for f in written)
               or "the card only"))
        try:
            QDesktopServices.openUrl(QUrl.fromLocalFile(r["folder"]))
        except Exception:
            pass

    def whole_card(self, recipe, outputs, written, choice, stem, r):
        """The dataset card beside what Whole wrote, with the counts of the
        mask as they were written, and the STAC item of a GeoTIFF mask that
        has a coordinate system. Returns what the information box says."""
        on_disk = set(written)
        tally = recipe.get("tally") or {}
        exports, mask = [], None
        for what, path, driver in outputs:
            if path not in on_disk or what not in ("mask", "votes"):
                continue
            entry = {"path": path, "role": what, "reading": choice,
                     "scale": r["scale"]}
            if what in tally:
                entry["counts"] = tally[what]
            exports.append(entry)
            if what == "mask":
                mask = (path, driver)
        files, said, card = write_card_beside(
            self.panel, r["folder"], stem, exports=exports, describe=choice,
            ignore_index=recipe.get("ignore"),
            points_in_mask=bool(recipe.get("points_in_mask")
                                and recipe.get("want_points")),
            dot_px=recipe.get("dot_px", 1))
        if card is not None and mask is not None and mask[1] == "GTiff":
            try:
                ds = gdal.Open(long_path(mask[0]))
                gt, w, h = pixel_grid(ds), ds.RasterXSize, ds.RasterYSize
                wkt = ds.GetProjection()
                ds = None
                votes = [p for k, p, _ in outputs
                         if k == "votes" and p in on_disk]
                item = card_write_mask_item(card, mask[0], gt, w, h, wkt,
                                            votes[0] if votes else None,
                                            files[1] if files else None)
                if item:
                    said += "\nSTAC item: %s." % os.path.basename(item)
            except Exception as err:
                log("the STAC item of the mask could not be written: %s"
                    % err, loud=True)
        return said

    def tick_whole(self, done, total):
        """Keep QGIS answering while a big raster goes out, and say how far
        along it is. Without this the window greys over and looks crashed."""
        iface.mainWindow().statusBar().showMessage(
            "%s: whole raster, %d%%" % (NAME, int(100.0 * done / max(total, 1))))
        QApplication.processEvents()

    def guess_limits(self, ds, bands, scale):
        """A stretch decided once, from a cheap look at the whole raster.

        Taken before the strips start, and on a heavily decimated read, because
        a stretch worked out strip by strip would put a visible seam across the
        picture wherever the brightness of the ground changed."""
        step = max(1, ds.RasterXSize // 1200, ds.RasterYSize // 1200)
        out = []
        for b in bands:
            try:
                band = ds.GetRasterBand(min(b, ds.RasterCount))
                small = band.ReadAsArray(
                    0, 0, ds.RasterXSize, ds.RasterYSize,
                    buf_xsize=max(1, ds.RasterXSize // step),
                    buf_ysize=max(1, ds.RasterYSize // step)).astype(np.float32)
                nd = band.GetNoDataValue()
                good = np.isfinite(small)
                if nd is not None:
                    good &= small != nd
                v = small[good]
                out.append((float(np.percentile(v, 2)),
                            float(np.percentile(v, 98))) if v.size else (0.0, 255.0))
            except Exception:
                out.append((0.0, 255.0))
        return out

    def pick_layers(self, silent=False):
        # Cutouts writes a picture rather than a GeoTIFF when there is no
        # coordinate system, which the Whole dialog has said in so many words
        # for a long time; the layer picker was the one place still refusing to
        # list those layers at all.
        #
        # In the order of the Layers panel, top first. They came sorted by
        # name, and the first one sets the grid and the system of every
        # cutout: whatever was on top, a layer whose name sorts first won.
        rasters = in_tree_order(project_rasters(need_crs=False))
        if not rasters:
            if not silent:
                QMessageBox.warning(self, NAME, "No raster is loaded.")
            return
        remembered = dict(self.ignored)
        remembered.update({s["id"]: s for s in self.sources})
        if silent and not self.sources:
            self.sources = self.guess(rasters)
            self.show_state()
            return
        dialog = CutoutSetup(self, rasters, remembered,
                             grid_id=self.sources[0]["id"] if self.sources
                             else None)
        if not run_dialog(dialog):
            return
        self.sources = dialog.result()
        self.skipped = {}
        if self.sources:
            log("cutouts: %s; the grid is %s's"
                % (", ".join("%s as %s" % (s["tag"], s["role"])
                             for s in self.sources), self.sources[0]["tag"]))
        self.show_state()

    def guess(self, rasters):
        """What a first glance says, so the module is usable before anyone
        opens the dialog: every raster that is on the map, in the order of
        the Layers panel, so the one on top sets the grid. A layer unticked
        in the Layers panel starts as "ignore", because what is cut is what
        is shown, and it is one click to put it back in Layers. So does a
        map of a report (the disagreement of two readings, a map of pairs):
        Compare loads it on, on top, and it would otherwise be cut beside the
        image as a layer of classes of the dataset. With a campaign open its
        reference raster goes first.

        A folder that was cut before has the last word over all of that
        (layers.json, see remember_layers): the layers it was cut from keep
        their roles, their bands, their names and their order, the first of
        them the grid, whatever is ticked on the map today."""
        reference = ""
        if self.campaign is not None:
            reference = from_folder(
                (self.campaign.data.get("grid") or {}).get(
                    "reference_raster", ""), self.campaign.folder)
        kept, order = {}, {}
        memory = self.read_layers() or {}
        for i, entry in enumerate(memory.get("layers") or []):
            key = layer_key(entry.get("source"))
            if key and key not in kept:
                kept[key], order[key] = entry, i
        # A record that names no layer of this project says nothing about
        # it: another project, or files that have moved.
        here = {layer_key(source_of(l)) for l in rasters}
        if not set(kept) & here:
            kept, order = {}, {}
        self.ignored = {}
        choices, new, claimed = [], [], set()
        for layer in rasters:
            key = layer_key(source_of(layer))
            entry = kept.get(key)
            # two layers of one file: the first is the folder's
            if key in claimed:
                entry = None
            claimed.add(key)
            # With a record the folder is the whole list: a layer it does
            # not know is not part of this dataset, and is one click away in
            # Layers. A layer more is how the same folder came to hold
            # pieces that did not stack. A map of a report is never offered
            # unless the folder was cut with it.
            if entry is None and (kept or not self.on_the_map(layer)
                                  or is_report_layer(layer)):
                self.ignored[layer.id()] = {"id": layer.id(), "role": "ignore"}
                if kept:
                    new.append(layer.name())
                continue
            choices.append((layer, key, entry))
        if new:
            log("%s: %s %s not among the layers this folder was cut from, "
                "and %s left out. Layers puts %s in."
                % (self.folder, ", ".join(new[:4]) + (", ..." if len(new) > 4
                                                       else ""),
                   "is" if len(new) == 1 else "are",
                   "is" if len(new) == 1 else "are",
                   "it" if len(new) == 1 else "them"))
        # the names the folder gave are kept as they were, whatever order the
        # layers are in today: the ones it does not know come after
        out, taken = [], set()
        for layer, key, entry in choices:
            if entry is not None and entry.get("tag"):
                # as the folder kept it, never cut again: a tag made by
                # RasterLabel 1.0 is at most 48 letters and comes back as it
                # was, and one made since may be a little longer (a "_2")
                tag = tidy_tag(str(entry["tag"]), room=255)
                if tag.lower() not in taken:
                    taken.add(tag.lower())
                    entry["_tag"] = tag
        for layer, key, entry in choices:
            tag = (entry or {}).get("_tag")
            if not tag:
                # a long name loses its middle, never its ending
                tag = tidy_tag(layer.name())
                while tag.lower() in taken:
                    tag += "_2"
                taken.add(tag.lower())
            source = {"id": layer.id(), "layer": layer,
                      "role": guess_role(layer),
                      "band": class_band_of(layer),
                      "rgb": renderer_bands(layer), "tag": tag}
            if entry is not None:
                self.take_remembered(source, entry, layer)
            out.append(source)
        out.sort(key=lambda s: 0 if source_of(s["layer"]) == reference else 1)
        if order:
            out.sort(key=lambda s: order.get(layer_key(source_of(s["layer"])),
                                             len(order)))
        return out

    @staticmethod
    def take_remembered(source, entry, layer):
        """What a folder remembers of a layer, as far as it still fits the
        layer: a role that exists, bands the layer has, a format we write."""
        bands = layer.dataProvider().bandCount()
        if entry.get("role") in ("image", "classes"):
            source["role"] = entry["role"]
        band = entry.get("band")
        if isinstance(band, int) and 1 <= band <= bands:
            source["band"] = band
        rgb = entry.get("rgb")
        if isinstance(rgb, list) and len(rgb) == 3 and all(
                isinstance(b, int) and 1 <= b <= bands for b in rgb):
            source["rgb"] = list(rgb)
        if entry.get("driver") in [row[1] for row in WHOLE_FORMATS]:
            source["driver"] = entry["driver"]

    # ---------------------------------------------- the layers of a folder
    # Which layers were cut, as what and on whose grid is a property of the
    # dataset, not of a session: a folder that gets its cutouts from a
    # different set of layers every other day holds pieces that do not stack.
    # So it is written into the folder, layers.json beside cutouts.csv, and
    # not into the QGIS settings of this machine. It goes with the folder when
    # it is copied or zipped, and it cannot disagree with the folder it
    # describes the way a setting keyed by the path of a folder that has been
    # moved or deleted would. Layers are told apart by the path of the file
    # they come from, so it serves where those files are at the same paths: on
    # another machine, another drive or after the files moved, no layer of the
    # record is found and it is left aside (guess), the layers chosen from the
    # map as for a new folder.
    @property
    def layers_path(self):
        return os.path.join(self.folder, LAYERS_FILE)

    def read_layers(self, as_written=False):
        """layers.json of the folder, or None when there is none or it cannot
        be read as one. The paths in it are made whole from the folder, as the
        manifests are (from_folder): it keeps them from the folder or from ~,
        and a file written before, with whole paths, reads the same. With
        as_written the paths are left as the file has them."""
        path = long_path(self.layers_path)
        if not self.folder or not os.path.exists(path):
            return None
        try:
            with open(path, encoding="utf-8") as f:
                book = json.load(f)
        except (OSError, ValueError) as err:
            log("%s could not be read, the layers are chosen afresh: %s"
                % (LAYERS_FILE, err), loud=True)
            return None
        if not isinstance(book, dict) or not isinstance(
                book.get("layers"), list):
            return None
        book["layers"] = [e for e in book["layers"] if isinstance(e, dict)]
        if not as_written:
            held = [(e, "source") for e in book["layers"]] + [(book, "grid")]
            for entry, key in held:
                if isinstance(entry.get(key), str):
                    entry[key] = from_folder(entry[key], self.folder)
        return book

    def layers_record(self):
        """What this session cuts, as layers.json says it: the layers in
        order, the first the grid, and the ones left out on purpose."""
        layers = []
        for s in self.sources:
            entry = {"source": source_of(s["layer"]),
                     "name": s["layer"].name(), "role": s["role"],
                     "tag": s["tag"]}
            if s["role"] == "classes":
                entry["band"] = s["band"]
            else:
                entry["rgb"] = list(s["rgb"])
            if s.get("driver"):
                entry["driver"] = s["driver"]
            layers.append(entry)
        return {"written_by": "%s %s" % (NAME, VERSION),
                "note": "The layers this folder is cut from, the first one "
                        "setting the pixel grid. Cutouts reads it when the "
                        "folder is chosen, so the next session cuts the same "
                        "layers in the same way, when their files are where "
                        "the paths written here lead: from this folder, or "
                        "from the home folder (~). A layer not listed here "
                        "is not part of this dataset.",
                "grid": layers[0]["source"] if layers else "",
                "layers": layers}

    @staticmethod
    def layers_words(book):
        """The layers of a record in a sentence."""
        layers = (book or {}).get("layers") or []
        if not layers:
            return "no layer"
        return "%s (the grid is %s's)" % (
            ", ".join("%s as %s" % (e.get("tag"), e.get("role"))
                      for e in layers), layers[0].get("tag"))

    @staticmethod
    def layers_match(a, b):
        """True when two records cut the same layers, as the same, on the
        same grid. The order after the first does not matter."""
        def shape(book):
            rows = [(layer_key(e.get("source")), e.get("role"), e.get("tag"),
                     e.get("band") if e.get("role") == "classes"
                     else tuple(e.get("rgb") or ()), e.get("driver") or "")
                    for e in (book or {}).get("layers") or []]
            return rows[:1], sorted(rows[1:], key=str)
        return shape(a) == shape(b)

    def layers_to_write(self, record):
        """The record as the file keeps it: the paths of the layers from the
        folder, or from ~ when they are far from it (beside_folder), and the
        passwords of a layer that is a service taken out. The folder is
        zipped and published, and whole paths carry the name of whoever cut
        it."""
        out = dict(record)
        out["layers"] = [dict(e, source=beside_folder(e.get("source"),
                                                      self.folder))
                         for e in record["layers"]]
        if out.get("grid"):
            out["grid"] = beside_folder(out["grid"], self.folder)
        return out

    def remember_layers(self, record=None):
        """Write layers.json, if it says anything new. Never raises: the
        dataset is whole without it."""
        record = record or self.layers_record()
        if not record["layers"]:
            return
        text = self.layers_to_write(record)
        before = self.read_layers()
        if before is not None and self.layers_match(before, record):
            # a file written with whole paths is written again, once, in the
            # form that does not carry the home folder
            kept = self.read_layers(as_written=True)
            same_paths = (
                sorted(str(e.get("source")) for e in kept["layers"])
                == sorted(str(e["source"]) for e in text["layers"]))
            if same_paths and kept.get("grid") == text["grid"]:
                return
        try:
            os.makedirs(long_path(self.folder), exist_ok=True)
            write_atomic(self.layers_path, json.dumps(text, indent=2))
        except OSError as err:
            log("cannot write %s: %s" % (LAYERS_FILE, err), loud=True)

    def restore_layers(self):
        """The layers a folder says it was cut from, in place of the ones
        chosen so far, when it says: True when it did."""
        if self.read_layers() is None:
            return False
        rasters = in_tree_order(project_rasters(need_crs=False))
        if not rasters:
            return False
        self.sources = self.guess(rasters)
        self.skipped = {}
        log("cutouts: the layers of %s, as it was cut before: %s"
            % (self.folder, self.layers_words(self.layers_record())))
        return True

    def check_layers(self):
        """Before a cut: the layers of the folder, and the layers about to be
        cut. They differ when somebody chose other roles, another grid or
        other layers since the last cutout, and the pieces of one folder
        then no longer line up. It is said, once, on the message bar and in
        the log, and the new choice is kept from now on."""
        record = self.layers_record()
        before = self.read_layers()
        if before is not None and self.count > 0 \
                and not self.layers_match(before, record):
            told = self.__dict__.setdefault("_layers_told", set())
            sentence = (self.layers_words(before), self.layers_words(record))
            if sentence not in told:
                told.add(sentence)
                log("the layers differ from the ones this folder was cut "
                    "from. Before: %s. Now: %s." % sentence, loud=True)
                iface.messageBar().pushMessage(
                    NAME, "this folder was cut from other layers or roles "
                    "(before: %s). The new choice is kept; cutouts of the two "
                    "may not stack." % sentence[0], level=LEVEL_WARNING,
                    duration=10)
        self.remember_layers(record)

    # ------------------------------------------- a cutout in the making
    @property
    def pending_path(self):
        return os.path.join(self.folder, PENDING_FILE)

    def note_pending(self, name):
        """Say, in the folder, that this cutout is being written. If the
        process dies before cutouts.csv has its rows, nothing else would ever
        say that the files with this name belong to nothing."""
        try:
            write_atomic(self.pending_path,
                         json.dumps({"cutout": name, "when": now()}))
        except OSError as err:
            log("cannot note that %s is being written: %s" % (name, err))

    def clear_pending(self):
        try:
            os.remove(long_path(self.pending_path))
        except OSError:
            pass

    def settle_interrupted(self):
        """A cutout that was being written when the process died: its files
        are in the folder and cutouts.csv does not list it. They are taken
        away, so that the name is free again and the folder holds whole
        cutouts only. A cutout the manifest does list is a whole one, whose
        note was left behind, and the note is all that goes. A manifest that
        cannot be read says nothing either way, and then nothing of the
        cutout is removed."""
        path = long_path(self.pending_path)
        if not self.folder or not os.path.exists(path):
            return
        try:
            with open(path, encoding="utf-8") as f:
                name = str(json.load(f).get("cutout") or "")
        except (OSError, ValueError, AttributeError):
            name = ""
        rows = self.read_manifest()
        if name and rows is None:
            log("%s was being written when the last session ended, but "
                "cutouts.csv cannot be read to say whether it lists it: "
                "its files are left where they are" % name, loud=True)
        elif name and name not in [r.get("cutout") or "" for r in rows]:
            removed = []
            for folder in (self.folder, self.stac_folder()):
                try:
                    entries = os.listdir(long_path(folder))
                except OSError:
                    continue
                for entry in entries:
                    if entry == name or entry.startswith(name + "_") \
                            or entry.startswith(name + "."):
                        try:
                            os.remove(long_path(os.path.join(folder, entry)))
                            removed.append(entry)
                        except OSError as err:
                            log("cannot remove %s: %s" % (entry, err))
            log("%s was being written when the last session ended, and "
                "cutouts.csv does not list it: its %d file%s taken away%s"
                % (name, len(removed),
                   " was" if len(removed) == 1 else "s were",
                   (": " + ", ".join(removed[:4])
                    + (", ..." if len(removed) > 4 else "")) if removed
                   else ""), loud=True)
        self.clear_pending()

    def on_the_map(self, layer):
        """True when the layer is ticked in the Layers panel. A project with
        no tree to ask, or a layer the tree does not hold, counts as shown."""
        try:
            node = QgsProject.instance().layerTreeRoot().findLayer(layer.id())
        except Exception:
            return True
        if node is None:
            return True
        try:
            return bool(node.isVisible())
        except Exception:
            return True

    @staticmethod
    def is_file_layer(layer):
        """False for a raster that comes from a service or a database, whose
        source is no path."""
        try:
            return layer.dataProvider().name() == "gdal"
        except Exception:
            return True

    def open_sources(self):
        """The layers to cut, opened, with the ones that cannot be put on the
        grid of the first left out and the reason kept in self.skipped."""
        self.skipped = {}
        alive = []
        for s in self.sources:
            layer = QgsProject.instance().mapLayer(s["id"])
            if layer is None:
                log("%s is no longer in the project, skipped" % s["tag"])
                self.skipped[s["tag"]] = "no longer in the project"
                continue
            s["layer"] = layer
            s["ds"] = open_raster(source_of(layer))
            if s["ds"] is None:
                # A web basemap or a database table is a valid layer and no
                # file GDAL opens: said as what it is, not as a broken file.
                log("cannot read %s, skipped" % s["tag"])
                self.skipped[s["tag"]] = "its file cannot be read" \
                    if self.is_file_layer(layer) else \
                    "it is not a raster file (a web or database layer)"
                continue
            s["limits"] = display_limits(layer, s["rgb"]) \
                if s["role"] == "image" else None
            s["moment"] = source_moment(s["ds"])
            s["readings"] = self.readings_of(s["ds"]) \
                if s["role"] == "classes" else None
            s["ignore"] = self.ignore_for(s) if s["role"] == "classes" \
                else (None, False, None)
            s["reproject"] = False
            s["src_wkt"] = None
            if s["role"] == "classes":
                self.warn_if_lossy(s)
            alive.append(s)
        if not alive:
            return []
        # Compared on the ground, not by definition. The orthomosaic that
        # taught this declares WGS 84 with a TOWGS84 of seven zeros, which GDAL
        # reads as a BOUNDCRS; the map of classes beside it is plain EPSG:4326.
        # The two definitions differ and the two systems are one, and a test
        # of the definitions with == left the image out of every cutout, in
        # whichever order the layers came, with a warning that said "is in
        # EPSG:4326 and the first layer is in EPSG:4326" and that the next
        # message covered.
        #
        # A layer whose system really is another is reprojected onto the grid,
        # or a map of classes and an image in two systems, which is a common
        # pair, could not be cut together at all. Only a layer with no system,
        # beside one that has one, is left out: there is nothing to say where
        # it is on the ground.
        first = alive[0]
        out = [first]
        told = self.__dict__.setdefault("_reprojected_told", set())
        for s in alive[1:]:
            if self.same_system(s["layer"], first["layer"]):
                out.append(s)
                continue
            mine = self.system_name(s["layer"].crs())
            theirs = self.system_name(first["layer"].crs())
            if s["layer"].crs().isValid() and first["layer"].crs().isValid():
                s["reproject"] = True
                # the systems as QGIS has them when a file does not say its
                # own, as when it was set in QGIS
                s["src_wkt"] = (None if s["ds"].GetProjection()
                                else s["layer"].crs().toWkt())
                s["dst_wkt"] = (first["ds"].GetProjection()
                                or first["layer"].crs().toWkt())
                out.append(s)
                if s["tag"] not in told:
                    told.add(s["tag"])
                    log("%s is in %s and %s, which sets the grid, is in %s: "
                        "it is reprojected onto that grid" % (
                            s["tag"], mine, first["tag"], theirs), loud=True)
                continue
            self.skipped[s["tag"]] = "it is in %s, the grid in %s" % (mine,
                                                                      theirs)
            log("%s is in %s and %s, which sets the grid, is in %s: with no "
                "system on one side there is no saying where its cutout "
                "would land, so it is left out"
                % (s["tag"], mine, first["tag"], theirs), loud=True)
        return out

    def ignore_wanted(self):
        """The ignore value of the dock, or None while it is off."""
        on = getattr(self, "ignore_on", None)
        if on is None or not on.isChecked():
            return None
        return int(self.ignore_value.value())

    def ignore_refused(self, quiet=False):
        """True, having said why, when the ignore value of the settings is
        one no cutout may hold: 0, a class code a campaign hands out, or
        past what a mask holds. Nothing is cut with it."""
        want = self.ignore_wanted()
        why = ignore_refusal(want) if want is not None else None
        if not why:
            return False
        log("cutouts refused: the ignore value %d: %s" % (want, why))
        if not quiet:
            QMessageBox.warning(
                self, NAME, "The ignore value under Settings cannot be used: "
                "%s.\n\nChange it, or untick 'unlabelled as ignore'." % why)
        return True

    def ignore_for(self, s):
        """(value, zero is unlabelled, why) for one layer cut as classes
        (cut_ignore_rule), said in the log once a session when the file's
        own value overrules the one in the dock."""
        try:
            own = s["ds"].GetMetadataItem("RASTERLABEL_IGNORE_INDEX")
        except Exception:
            own = None
        want = self.ignore_wanted()
        got = cut_ignore_rule(own, s.get("readings"), want)
        told = self.__dict__.setdefault("_ignore_told", set())
        if got[2] == "file" and want is not None and want != got[0] \
                and s["tag"] not in told:
            told.add(s["tag"])
            log("%s carries its own ignore value, %d, and keeps it: the %d "
                "of the settings is not used for it" % (s["tag"], got[0],
                                                        want), loud=True)
        return got

    def warn_if_lossy(self, s):
        """Say it, once a session for each map, when a map of classes is
        stored with a lossy codec. The codec moves the values along every edge
        between two classes, so the map holds codes that are no class, and
        the cutouts copied them as data without a word."""
        told = self.__dict__.setdefault("_lossy_told", set())
        key = os.path.normcase(source_of(s["layer"]) or s["tag"])
        if key in told:
            return
        told.add(key)
        codec = lossy_codec(source_of(s["layer"]) or "")
        if codec:
            log("%s is stored as %s, which is lossy: its class codes carry "
                "compression noise along the edges, values that are no "
                "class, and the cutouts copy them as they are"
                % (s["tag"], codec), loud=True)

    @staticmethod
    def centre_of(layer):
        try:
            c = layer.extent().center()
            return (c.x(), c.y())
        except Exception:
            return None

    def same_system(self, layer, grid_layer):
        """True when two layers are in one coordinate system on the ground:
        the same definition, the same registered name once named_crs has
        looked through a binding that does nothing, or a point that stays
        where it was when it is moved from one to the other."""
        a, b = layer.crs(), grid_layer.crs()
        if a == b:
            return True
        if not a.isValid() or not b.isValid():
            return not a.isValid() and not b.isValid()
        here, there = self.centre_of(layer), self.centre_of(grid_layer)
        try:
            na, nb = named_crs(a, here), named_crs(b, there)
            if na.authid() and na.authid() == nb.authid():
                return True
        except Exception:
            pass
        try:
            return bool(same_ground(a, b, here))
        except Exception:
            return False

    @staticmethod
    def system_name(crs):
        """The system as the log says it, with the description beside the
        code when the code came from named_crs: two layers called EPSG:4326
        in one sentence must not look the same when they are not."""
        label = crs_label(crs)
        try:
            if crs.isValid() and not crs.authid() and crs.description():
                return "%s (%s)" % (label, crs.description())
        except Exception:
            pass
        return label

    def output_wkt(self, source):
        """The system the files of a cutout are written in.

        The grid layer's own, except when it has no code and a registered
        system is the same on the ground: then that one, by its code. Written
        as it came, a BOUNDCRS spread from the orthomosaic into every file of
        the dataset, into the footprints and into the catalogue, all of them
        in a system with no name that the next program has to work out
        again."""
        own = source["ds"].GetProjection() or ""
        crs = source["layer"].crs()
        try:
            if not crs.isValid() or crs.authid():
                return own
            named = named_crs(crs, self.centre_of(source["layer"]))
            code = named.authid()
            if not code:
                return own
            srs = osr.SpatialReference()
            if srs.SetFromUserInput(code) == 0:
                return srs.ExportToWkt() or own
            return named.toWkt() or own
        except Exception:
            return own

    # ----------------------------------------------------------- cutting
    def aim_measure(self):
        """The ruler of square_at, in the system the canvas is in now.

        On the project's ellipsoid only when that system is a real one. Given
        an ellipsoid and no valid system, QGIS takes the coordinates for
        degrees: on a picture with no georeference one unit came out as about
        a hundred kilometres, and past 90 as NaN, which reached the window of
        a click and stopped it with "cannot convert float NaN to integer"."""
        crs = canvas().mapSettings().destinationCrs()
        try:
            self.measure.setSourceCrs(crs,
                                      QgsProject.instance().transformContext())
            self.measure.setEllipsoid(project_ellipsoid() if crs.isValid()
                                      else "NONE")
        except Exception:
            pass

    def first_layer(self):
        """The layer that sets the grid, as the project holds it now."""
        if not self.sources:
            return None
        try:
            return QgsProject.instance().mapLayer(self.sources[0]["id"])
        except Exception:
            return None

    def square_at(self, point):
        """A square of the chosen side in true metres, around a point of the
        canvas, whatever the canvas system is.

        When the layer that sets the grid has no coordinate system, its units
        are pixels or whatever its world file counts in, and the side is in
        those units: one to a metre, which is what the side box counts its
        pixels with. Measured in the system of the canvas it would take the
        units of a picture for degrees."""
        first = self.first_layer()
        wide = tall = 1.0
        try:
            known = first is None or first.crs().isValid()
        except Exception:
            known = True
        if known:
            self.aim_measure()
            try:
                wide = self.measure.measureLine(
                    QgsPointXY(point.x(), point.y()),
                    QgsPointXY(point.x() + 1.0, point.y()))
                tall = self.measure.measureLine(
                    QgsPointXY(point.x(), point.y()),
                    QgsPointXY(point.x(), point.y() + 1.0))
            except Exception:
                wide = tall = 1.0
        # NaN is not caught by "or 1.0", nor is an infinity or a negative
        # length: anything but a finite length above zero is one unit
        if not (isinstance(wide, (int, float)) and math.isfinite(wide)
                and wide > 0):
            wide = 1.0
        if not (isinstance(tall, (int, float)) and math.isfinite(tall)
                and tall > 0):
            tall = 1.0
        hx = self.side.value() / 2.0 / wide
        hy = self.side.value() / 2.0 / tall
        return QgsRectangle(point.x() - hx, point.y() - hy,
                            point.x() + hx, point.y() + hy)

    def save_first(self):
        """Write the campaign down before reading anything off the disk.

        The layers being cut are read with gdal, from the file, not through
        QGIS. Anything still sitting in an open edit session is invisible to
        them. This matters less here than in Annotate, since the ground truth
        of a cutout is usually a layer somebody else made, but a campaign whose
        own package is half committed is a campaign whose next rollback throws
        away what a cutout already copied."""
        panel = self.panel
        for module in (panel.section, panel.annotation):
            if module is None or module is self or not module.unsaved():
                continue
            try:
                module.save()
            except Exception as err:
                log("could not save before cutting: %s" % err, loud=True)

    def start_cutting(self):
        if not self.sources:
            QMessageBox.warning(self, NAME, "Choose the layers first.")
            return
        if self.tool is None:
            self.tool = CutoutTool(canvas(), self)
        canvas().setMapTool(self.tool)
        log("cutting: click for a square of %.2f m, drag for a free rectangle, "
            "right click to undo the last one, Esc to stop." % self.side.value())

    def stop_cutting(self):
        if self.tool is not None and canvas().mapTool() is self.tool:
            canvas().unsetMapTool(self.tool)
        log("stopped cutting, %d cutouts in %s" % (self.count, self.folder))

    def release_tools(self):
        self.stop_cutting()
        # Called while the module is being closed; once it is gone the panel
        # lets the log go from Cutouts.
        panel_ = self.panel
        QTimer.singleShot(0, lambda: CutoutsSection.reroute(panel_))

    def export_all_tiles(self):
        if self.campaign is None:
            return
        tiles = find_mine(self.campaign.data["id"], "tiles")
        if tiles is None:
            return
        features = [f for f in tiles.getFeatures() if f.hasGeometry()]
        if not features:
            QMessageBox.information(self, NAME, "This campaign has no tile yet.")
            return
        q = QMessageBox.question(
            self, "All tiles",
            "Cut one subset for each of the %d tiles?" % len(features))
        if q != QMessageBox.StandardButton.Yes:
            return
        if self.ignore_refused():
            return
        self.save_first()
        if not self.folder_is_usable():
            return
        done, refused, broken = 0, 0, []
        for f in features:
            try:
                side = float(f["side_m"] or 0) or None
            except (TypeError, ValueError):
                side = None
            try:
                if self.export(f.geometry().boundingBox(), quiet=True,
                               tile_id=str(f["tile_id"]), nominal=side):
                    done += 1
                else:
                    refused += 1
            except Exception as err:
                # One frame that cannot be written is one frame, not the whole
                # batch: an exception walking out of the loop would leave the
                # remaining frames untried, with no dialog to say so.
                broken.append(str(f["tile_id"]))
                log("tile %s could not be cut: %s" % (f["tile_id"], err))
            QApplication.processEvents()
        self.show_state()
        message = "%d cutout%s written in\n%s" % (
            done, "" if done == 1 else "s", self.folder)
        if refused:
            message += "\n\n%d frames were refused: too small, outside the " \
                       "first layer, or too large." % refused
        if broken:
            message += "\n\n%d could not be written at all: %s.\nThe log says " \
                       "why for each." % (len(broken), ", ".join(broken[:12]))
        QMessageBox.information(self, NAME, message)

    # ----------------------------------------------------------- the export
    def export(self, rect, quiet=False, tile_id=None, nominal=None):
        """Write one cutout. `nominal` is the side in metres that was asked
        for, when one was: a click of the fixed side or a frame. It is None for
        a rectangle dragged by hand, which is meant to be its own size and is
        left alone by the rule that keeps every piece of a given side the same
        number of pixels."""
        if self.ignore_refused(quiet):
            return False
        if not quiet:
            self.save_first()
            if not self.folder_is_usable():
                return False
        sources = self.open_sources()
        if not sources:
            if not quiet:
                QMessageBox.warning(self, NAME, "No layer can be read.")
            return False
        view = canvas().mapSettings().destinationCrs()
        target = sources[0]["layer"].crs()
        if tile_id is None and view != target:
            rect = QgsCoordinateTransform(
                view, target, QgsProject.instance()).transformBoundingBox(rect)
        elif tile_id is not None and self.geometry is not None \
                and self.geometry.crs != target:
            rect = QgsCoordinateTransform(
                self.geometry.crs, target,
                QgsProject.instance()).transformBoundingBox(rect)

        reference = sources[0]["ds"]
        size = (reference.RasterXSize, reference.RasterYSize)
        # A raster stored bottom row first is cut on the same grid counted
        # from the top, and its cutouts come out north up like every other.
        gt0 = north_up_of(reference)
        if is_rotated(gt0):
            # A window of whole pixels cannot be laid on a rotated grid:
            # snapped as if the grid were north up, the cutout would hold
            # other pixels than the ones under the rectangle, and some clicks
            # would be refused as outside a layer they were on.
            if not quiet:
                QMessageBox.warning(
                    self, NAME, "'%s', which sets the grid of the cutouts, "
                    "has a rotated pixel grid: its rows are not parallel to "
                    "the x axis, and no cutout of whole pixels can be laid on "
                    "it.\n\n%s, and cut that one, or let another layer set "
                    "the grid in Layers." % (sources[0]["layer"].name(),
                                              ROTATED_ADVICE))
            log("cutout refused: %s, which sets the grid, is rotated"
                % sources[0]["tag"])
            return False
        col, row, w, h = snap(gt0, size, rect)
        if w < 2 or h < 2:
            if not quiet:
                iface.messageBar().pushMessage(
                    NAME, "the rectangle falls outside the first layer",
                    level=LEVEL_WARNING, duration=3)
            return False
        if nominal is not None and tile_id is None:
            # A click: the square the side box announces, so many pixels on
            # each side, centred on the click. Not the square measured on the
            # ground and then snapped outwards to whole pixels, which almost
            # never falls on pixel edges and so comes out one pixel larger
            # than the box says, 201 for 200 and 4 for 3, forty metres for
            # thirty; and shapes.json would then hold that size for every
            # later cutout of the side.
            col, row, w, h = self.clicked_window(sources[0]["layer"], gt0,
                                                 rect, nominal)
            if not self.same_size.isChecked():
                c1, r1 = min(col + w, size[0]), min(row + h, size[1])
                col, row = max(col, 0), max(row, 0)
                w, h = c1 - col, r1 - row
                if w < 2 or h < 2:
                    if not quiet:
                        iface.messageBar().pushMessage(
                            NAME, "the rectangle falls outside the first "
                            "layer", level=LEVEL_WARNING, duration=3)
                    return False
        if nominal is not None and self.same_size.isChecked():
            if tile_id is not None:
                col, row, w, h = snap(gt0, size, rect, clip=False)
            w, h = self.hold_shape(nominal, w, h, gt0[1])
        if w * h > MAX_WINDOW_PX:
            if not quiet:
                iface.messageBar().pushMessage(
                    NAME, "that cutout would be %d by %d pixels" % (w, h),
                    level=LEVEL_WARNING, duration=4)
            return False
        gt = window_transform(gt0, col, row)
        wkt = self.output_wkt(sources[0])
        extent = QgsRectangle(gt[0], gt[3] + h * gt[5],
                              gt[0] + w * gt[1], gt[3])

        # The ground truth of a cutout is a LAYER marked "classes", never the
        # annotation of the campaign. This module exists for the other job: you
        # already have a map and some imagery and you want a dataset out of
        # them. What is drawn by hand is written from Annotate, where it lives,
        # and burning it here as well would have made the same reading come out
        # of two places with two different sets of rules.
        os.makedirs(long_path(self.folder), exist_ok=True)
        self.settle_interrupted()
        self.check_layers()
        name = self.free_name()
        files, rows = [], []
        assets = {}
        sizes = set()

        # before the first file: if this process is killed from here to the
        # rows in cutouts.csv, the next session finds the note and the files
        self.note_pending(name)
        try:
            self.cut_layers(sources, name, gt, w, h, wkt, extent, tile_id,
                            files, rows, assets, sizes)
        except Exception as err:
            # Everything this cutout managed to write is taken away again. Half
            # a cutout on disk is worse than none: it is not in cutouts.csv, so
            # undo cannot reach it, and a year later it looks like a piece of
            # the dataset that simply has fewer files than the others.
            # Every path is in the list before its writer is called, so a
            # writer that made its file and then raised is cleaned up too.
            for path in files:
                for gone in (path, path + ".aux.xml"):
                    try:
                        os.remove(long_path(gone))
                    except OSError:
                        pass
            self.clear_pending()
            log("%s was abandoned: %s" % (name, err))
            if not quiet:
                QMessageBox.critical(
                    self, NAME,
                    "%s could not be written, and the pieces of it that had "
                    "already landed have been removed.\n\n%s" % (name, err))
            return False

        if len(sizes) > 1 and not quiet:
            iface.messageBar().pushMessage(
                NAME,
                "%s: the layers came out in %d different sizes (%s). They will "
                "not stack. Turn 'one common pixel grid' on."
                % (name, len(sizes),
                   ", ".join("%dx%d" % t for t in sorted(sizes))),
                level=LEVEL_WARNING, duration=8)
            log("%s: sizes %s" % (name, sorted(sizes)))
        return self.finish_cutout(name, files, rows, assets, extent, gt, w, h,
                                  wkt, tile_id, quiet)

    @staticmethod
    def clicked_window(layer, gt0, rect, nominal):
        """The window of a click: as many pixels a side as the side box says,
        round(side / pixel), centred on the middle of the square clicked.

        The pixel is measured on the ground, by the same pixel_on_the_ground
        the box uses, so a side of 10 m on 5 cm pixels is 200 by 200, and on
        pixels of 5 by 7 cm it is 200 by 143: square in pixels on square
        pixels, the same ground both ways otherwise."""
        try:
            px, py = pixel_on_the_ground(layer)
            px, py = float(px), float(py)
        except (TypeError, ValueError, AttributeError):
            px, py = abs(gt0[1]), abs(gt0[5])
        if not (math.isfinite(px) and px > 0):
            px = abs(gt0[1])
        if not (math.isfinite(py) and py > 0):
            py = abs(gt0[5])
        w = max(2, int(round(nominal / px)))
        h = max(2, int(round(nominal / py)))
        centre = rect.center()
        col = int(np.floor((centre.x() - gt0[0]) / gt0[1] - w / 2.0 + 0.5))
        row = int(np.floor((centre.y() - gt0[3]) / gt0[5] - h / 2.0 + 0.5))
        return col, row, w, h

    def side_of(self, ruler, extent, crs):
        """The side written in cutouts.csv: on the ground in metres, or in the
        units of the layer when it has no system, never NaN. An ellipsoid on a
        layer with no system measured its pixels as degrees and wrote nan."""
        a = QgsPointXY(extent.xMinimum(), extent.yMinimum())
        b = QgsPointXY(extent.xMaximum(), extent.yMinimum())
        side = float("nan")
        try:
            if crs is not None and crs.isValid():
                side = float(ruler.measureLine(a, b))
        except Exception:
            pass
        if not (math.isfinite(side) and side > 0):
            side = abs(extent.xMaximum() - extent.xMinimum())
        return side

    def cut_layers(self, sources, name, gt, w, h, wkt, extent, tile_id,
                   files, rows, assets, sizes):
        """One file per layer, on the grid the first layer set.

        Raises as soon as anything refuses to be written. The caller takes away
        what had already landed, so a cutout is all there or not there at
        all. Every path goes into files BEFORE its writer is called: a writer
        that made its file and then raised would otherwise leave it behind,
        out of every book."""
        # The side is measured in the system of the first layer, whatever
        # the canvas is in: there may be no campaign to lend its ruler.
        system = sources[0]["layer"].crs()
        ruler = ground_measure(system)
        for s in sources:
            # A layer reprojected from another system has no grid of its own
            # in the system of the cutout: it goes on the common one even
            # when each layer keeps its own grid.
            if self.common.isChecked() or s.get("reproject"):
                grid, ww, hh = gt, w, h
            else:
                own = north_up_of(s["ds"])
                v = snap(own, (s["ds"].RasterXSize, s["ds"].RasterYSize), extent)
                if v[2] < 2 or v[3] < 2:
                    log("%s: the cutout falls outside it, skipped" % s["tag"])
                    self.skipped[s["tag"]] = "the cutout falls outside it"
                    continue
                grid, ww, hh = window_transform(own, v[0], v[1]), v[2], v[3]
            stem = os.path.join(self.folder, "%s_%s" % (name, s["tag"]))
            sizes.add((ww, hh))
            driver, extension, kind = shape_of(s.get("driver"), s["role"])
            if (s["role"] == "classes" and driver == "PNG"
                    and self.class_type(s) not in (gdal.GDT_Byte,
                                                   gdal.GDT_UInt16)):
                # A PNG holds bytes and unsigned 16 bit values, nothing else,
                # and GDAL writes anything else into one as bytes, clamped,
                # with a warning on the console only: a map with a nodata of
                # -9999 had its class 300 come out as 255. Such a map goes out
                # as a GeoTIFF, the way a map of classes asked for as JPEG
                # does.
                driver, extension, kind = shape_of("GTiff", s["role"])
                if s["tag"] not in self.__dict__.setdefault("_png_refused",
                                                            set()):
                    self._png_refused.add(s["tag"])
                    log("%s holds values a PNG cannot (negative, or past 16 "
                        "bits): its classes are cut as GeoTIFF" % s["tag"],
                        loud=True)
            before = set(assets)
            if s["role"] == "classes":
                bands, resampled, stretch = self.cut_classes(
                    s, stem, grid, ww, hh, wkt, driver, extension, kind,
                    files, assets)
            else:
                bands, resampled, stretch = self.cut_image(
                    s, stem, grid, ww, hh, wkt, driver, extension, kind,
                    files, assets)
            if (tuple(grid), ww, hh) != (tuple(gt), w, h):
                # A layer on a grid of its own: the item says the grid of
                # the first layer, and this file has another size, another
                # transform, another box. Said on the asset, where the
                # projection extension allows it, instead of being left to
                # read as the item's.
                box = (grid[0], grid[3] + hh * grid[5],
                       grid[0] + ww * grid[1], grid[3])
                own = {k: v for k, v in projection_of(
                    grid, ww, hh, wkt, box).items()
                    if k in ("proj:shape", "proj:transform", "proj:bbox")}
                for key in set(assets) - before:
                    entry = assets[key]
                    if "data" in entry[2]:
                        more = dict(entry[4]) if len(entry) > 4 and entry[4] \
                            else {}
                        more.update(own)
                        assets[key] = tuple(entry[:4]) + (more,)

            ign = (s.get("ignore") or (None,))[0] \
                if s["role"] == "classes" else None
            rows.append({"cutout": name, "tag": s["tag"], "role": s["role"],
                         "layer": s["layer"].name(),
                         "bands": " ".join(str(b) for b in bands),
                         "resampled": int(bool(resampled)),
                         "stretch": stretch,
                         "tile_id": tile_id or "",
                         "xmin": "%.9f" % extent.xMinimum(),
                         "ymin": "%.9f" % extent.yMinimum(),
                         "xmax": "%.9f" % extent.xMaximum(),
                         "ymax": "%.9f" % extent.yMaximum(),
                         # the edges of THIS file: a layer on a grid of its
                         # own can be clipped by its own edge and then is
                         # smaller than the extent above. Not a column of
                         # cutouts.csv; the detection labels read it.
                         "grid_box": (grid[0], grid[3] + hh * grid[5],
                                      grid[0] + ww * grid[1], grid[3]),
                         "width_px": ww, "height_px": hh,
                         "format": driver,
                         # the side this cutout really has, measured on its own
                         # window. The spin box would be a lie for every hand
                         # dragged rectangle and for every frame whose side is
                         # not the current one
                         "side_m": "%.3f" % self.side_of(ruler, extent,
                                                         system),
                         "when": now(),
                         "ignore_index": "" if ign is None else str(ign)})
            if resampled:
                log("%s: %s %s onto the grid by %s" % (
                    name, s["tag"], "reprojected and resampled"
                    if s.get("reproject") else "resampled", resampled))

    @staticmethod
    def read_layer(s, bands, grid, ww, hh, wkt, pad_nan=False):
        """read_on_grid for one layer: by its role, and reprojected into the
        system of the grid when it is in another."""
        target = (s.get("dst_wkt") or wkt) if s.get("reproject") else None
        if pad_nan:
            return read_on_grid(s["ds"], bands, grid, ww, hh, role=s["role"],
                                wkt=target, src_wkt=s.get("src_wkt"),
                                pad_nan=True)
        return read_on_grid(s["ds"], bands, grid, ww, hh, role=s["role"],
                            wkt=target, src_wkt=s.get("src_wkt"))

    def cut_classes(self, s, stem, grid, ww, hh, wkt, driver, extension, kind,
                    files, assets):
        """The class codes as they are, and their coloured picture.

        A layer of classes written as PNG would be one grey PNG of codes one
        to four, nearly black to the eye, if the coloured copy were skipped
        because the main file is a PNG already, whatever "also write PNG
        copies" says. The codes stay in the main file, which is what a loader
        reads, and the picture goes beside it under its own name."""
        bands = [s["band"]]
        ign, zero_unlabelled, whence = s.get("ignore") or (None, False, None)
        array, nodata, resampled = self.read_layer(
            s, bands, grid, ww, hh, wkt, pad_nan=ign is not None)
        # A byte, unless the map holds a value that does not fit in one:
        # decided once per map, so every cutout of it has the same type.
        held = self.class_type(s)
        path = stem + "_classes" + extension
        # The map's own nodata, when it has one a cutout can declare. It is
        # declared as the nodata of the cutout and is no class: no colour,
        # nothing in the picture.
        declared = class_nodata(s["ds"], s["band"], held) \
            if ign is None else None
        if ign is None:
            v = array[0]
            if declared is not None and nodata[0] is not None \
                    and not is_class_code(nodata[0]):
                # a nodata no integer holds: written as the code declared
                # for it, or as 0 where a PNG cannot declare one, and never
                # cast, which gave the smallest 32 bit number
                v = np.where(np.isfinite(v) & (v != nodata[0]), v,
                             declared if driver == "GTiff" else 0)
            codes = np.nan_to_num(v, nan=0.0).astype(class_array(held))
        else:
            # Where the layer holds nothing: past its edge, its own nodata,
            # and the 0 of a campaign mask that means "nobody painted".
            # Any other 0 is left as it is: in a map made elsewhere it may
            # be a class, and in a mask with an ignore value of its own it
            # is "none of these", inside a frame.
            v = array[0]
            unlabelled = ~np.isfinite(v)
            if nodata[0] is not None:
                unlabelled |= v == nodata[0]
            if zero_unlabelled:
                unlabelled |= v == 0
            if np.any(v[~unlabelled] == ign):
                raise ValueError(
                    "%s holds %d inside this cutout, the value chosen for "
                    "ignore: choose another value." % (s["layer"].name(), ign))
            codes = np.where(unlabelled, ign, np.nan_to_num(v, nan=0.0)) \
                .astype(class_array(held))
        # No nodata is declared on a class raster for its 0. Zero here means
        # "no class", which is a value with a meaning, not an absence: a
        # reader honouring a nodata of zero would throw those pixels away
        # and could no longer tell them from outside the image. The ignore
        # value is declared, because it is the absence.
        files.append(path)
        if ign is not None:
            put_raster(driver, path, codes[None], grid, wkt, dtype=held,
                       nodata=ign if driver == "GTiff" else None)
        else:
            put_raster(driver, path, codes[None], grid, wkt, dtype=held,
                       nodata=declared if driver == "GTiff" else None)
        carried = dict(s.get("readings") or {})
        if ign is not None and whence != "file":
            # what this cutout holds where nobody labelled, said inside it,
            # so a cutout of it keeps the value and a reader is told
            consensus = carried.get("RASTERLABEL_READING_MODE") == "consensus"
            carried.update({
                "RASTERLABEL_UNLABELLED": "ignore" if zero_unlabelled
                else "map",
                "RASTERLABEL_UNLABELLED_RULE":
                    unlabelled_rule("ignore", ign, consensus)
                    if zero_unlabelled else
                    "%d past the edge and where the map has no data; its "
                    "own values, 0 included, as they are" % ign,
                "RASTERLABEL_IGNORE_INDEX": str(int(ign))})
        if carried and driver == "GTiff":
            # the mask of a campaign, written by Whole: which readings it
            # holds goes on into every cutout of it
            self.carry_readings(path, carried)
        named = (style_classes(s["layer"], s["band"]) if driver == "GTiff"
                 else None)
        if named:
            # The classes of the layer's style, as the colour table and
            # category names of the GeoTIFF: it opens in QGIS, and in
            # whatever reads GDAL, in the colours of the PNG beside it,
            # instead of grey. The codes are not touched.
            said = dress_class_band(
                path, 1, self.class_colours(s["layer"], s["band"], codes,
                                            ign if declared is None
                                            else declared))
            if said.startswith("no "):
                log(said)
        bands_entry = {"data_type": self.stac_type(held)}
        extra = {"raster:bands": [bands_entry]}
        if ign is not None:
            bands_entry["nodata"] = int(ign)
        elif declared is not None:
            bands_entry["nodata"] = declared
        # The classes of the layer's style, with or without an ignore value:
        # whoever is handed the item cannot tell what a 3 is from the codes.
        listed = style_classes(s["layer"], s["band"]) or []
        if ign is not None or listed:
            extra["classification:classes"] = cut_class_entries(listed, ign)
        assets["%s_classes" % s["tag"]] = (
            path, kind, ["data", "labels"],
            "%s, the class codes as they arrived, in %s"
            % (s["tag"], gdal.GetDataTypeName(held)), extra)
        if self.png.isChecked():
            picture = stem + ("_classes_colour.png" if driver == "PNG"
                              else "_classes.png")
            files.append(picture)
            hole = ign if declared is None else declared
            seen = codes > 0 if ign is None else (codes != 0) & (codes != ign)
            if declared is not None:
                seen &= codes != declared
            write_png(picture, colour_table(
                codes, self.class_colours(s["layer"], s["band"], codes, hole)),
                np.where(seen, 255, 0).astype(np.uint8))
            assets["%s_classes_png" % s["tag"]] = (
                picture, "image/png", ["overview"],
                "%s, coloured for looking at" % s["tag"])
        return bands, resampled, ""

    def cut_image(self, s, stem, grid, ww, hh, wkt, driver, extension, kind,
                  files, assets):
        """An image, by its own rules, and a picture of it as QGIS shows it.

        As a GeoTIFF it is the source itself over the window: every band, in
        its own data type, with its own nodata and its own band names, the
        first three called red, green and blue. Three bands stretched to
        bytes whatever the source is would turn a survey of seven bands of
        sixteen bits into a picture of three, and lose the four bands nobody
        looks at, which are the reason for a survey of seven.

        The picture is made from the style of the layer: its bands and its
        stretch, the way the image is on the screen. It is for looking at,
        not for reading numbers off, and it is transparent where the image
        has no data. A PNG or a JPEG asked for as the main file is that
        picture: neither can hold the image as it is."""
        ds = s["ds"]
        rgb = list(s["rgb"])
        if driver == "GTiff":
            bands = list(range(1, ds.RasterCount + 1))
        else:
            bands = rgb
        array, nodata, resampled = self.read_layer(s, bands, grid, ww, hh, wkt)
        at = {b: i for i, b in enumerate(bands)}
        valid = np.ones((hh, ww), bool)
        for b in rgb:
            i = at.get(b)
            if i is None:
                continue
            if nodata[i] is not None:
                valid &= array[i] != nodata[i]
            valid &= np.isfinite(array[i])

        if driver == "GTiff":
            path = stem + "_image" + extension
            files.append(path)
            self.write_native(ds, path, array, nodata, grid, wkt)
            assets["%s_image" % s["tag"]] = (
                path, kind, ["data"],
                "%s, every band as in the source: %d of %s"
                % (s["tag"], len(bands), gdal.GetDataTypeName(
                    self.native_type(ds))),
                {"raster:bands": [
                    dict({"data_type": self.stac_type(self.native_type(ds))},
                         **({} if nd is None else {"nodata": nd}))
                    for nd in nodata]})
        picture, alpha, stretch = None, None, ""
        if driver != "GTiff" or self.png.isChecked():
            picture, alpha, stretch = self.preview(
                s, grid, ww, hh, [array[at[b]] for b in rgb], valid)
        if driver != "GTiff":
            path = stem + "_image" + extension
            files.append(path)
            if driver == "PNG":
                write_png(path, picture, alpha)
            else:
                put_raster(driver, path, picture, grid, wkt)
            assets["%s_image" % s["tag"]] = (
                path, kind, ["data"],
                "%s, a picture of bands %s as QGIS shows them"
                % (s["tag"], " ".join(str(b) for b in rgb)))
        elif self.png.isChecked():
            q = stem + "_image.png"
            files.append(q)
            write_png(q, picture, alpha)
            assets["%s_image_png" % s["tag"]] = (
                q, "image/png", ["overview"],
                "%s, bands %s as QGIS shows them, without coordinates"
                % (s["tag"], " ".join(str(b) for b in rgb)))
        return bands, resampled, stretch

    def class_type(self, s):
        """class_band_type, kept for the session: it reads the whole band
        once, and a map cut a hundred times is read once. With the ignore
        value it is cut with, which the type has to hold as well."""
        known = self.__dict__.setdefault("_class_types", {})
        ign = (s.get("ignore") or (None,))[0]
        key = (s["ds"].GetDescription(), s["band"], ign)
        if key not in known:
            known[key] = class_band_type(s["ds"], s["band"]) if ign is None \
                else class_band_type(s["ds"], s["band"], ign)
        return known[key]

    @staticmethod
    def readings_of(ds):
        """The RASTERLABEL_ items of a mask written by Whole, or None."""
        try:
            items = ds.GetMetadata() or {}
        except Exception:
            return None
        found = {k: v for k, v in items.items()
                 if k.startswith("RASTERLABEL_")}
        return found if "RASTERLABEL_READING_MODE" in found else None

    @staticmethod
    def carry_readings(path, readings):
        try:
            out = gdal.Open(long_path(path), gdal.GA_Update)
            if out is not None:
                for k, v in readings.items():
                    out.SetMetadataItem(k, v)
                out.FlushCache()
            out = None
        except Exception as err:
            log("cannot write which readings %s holds: %s"
                % (os.path.basename(path), err))

    @staticmethod
    def native_type(ds):
        """One data type that holds every band of the source."""
        kind = ds.GetRasterBand(1).DataType
        for b in range(2, ds.RasterCount + 1):
            other = ds.GetRasterBand(b).DataType
            if other != kind:
                kind = gdal.DataTypeUnion(kind, other)
        return kind

    def write_native(self, ds, path, array, nodata, grid, wkt):
        """The bands as they are, in the data type of the source.

        read_on_grid hands them back as floats, with the nodata of the band
        where the window runs past the edge and NaN where the band has none;
        those pixels become zero, which is what GDAL fills a new band with.
        Filled in place: seven bands of a large rectangle are a lot of
        memory once, and there is no need to hold them twice.

        Zero in an image with no nodata is black, and black is ground too: the
        padding past the edge of the raster could not be told from a black
        roof in the GeoTIFF, only in its PNG. So where a band has no nodata
        and the window was padded, the file gets a mask of its own (a GDAL
        internal mask, which QGIS and rasterio read as transparency): 0 over
        the padding, 255 over the image. The values are not touched.

        A resampled band comes back with fractions, and an integer band is
        given the nearest whole number rather than whatever the cast makes
        of them."""
        mask = None
        if any(nd is None for nd in nodata):
            pad = ~np.isfinite(array).all(axis=0)
            if pad.any():
                mask = np.where(pad, 0, 255).astype(np.uint8)
        kind = self.native_type(ds)
        whole = not gdal.GetDataTypeName(kind).startswith(("Float", "CFloat"))
        for i in range(array.shape[0]):
            bad = ~np.isfinite(array[i])
            if bad.any():
                array[i][bad] = nodata[i] if nodata[i] is not None else 0.0
            if whole:
                np.rint(array[i], out=array[i])
        n = ds.RasterCount
        colours = None
        if n >= 3:
            colours = [gdal.GCI_RedBand, gdal.GCI_GreenBand, gdal.GCI_BlueBand]
            for b in range(4, n + 1):
                own = ds.GetRasterBand(b).GetColorInterpretation()
                colours.append(own if own == gdal.GCI_AlphaBand
                               else gdal.GCI_Undefined)
        names = [ds.GetRasterBand(b).GetDescription() for b in range(1, n + 1)]
        write_tif(path, array, grid, wkt, nodata=list(nodata),
                  dtype=kind, colours=colours, names=names, mask=mask)

    def preview(self, s, grid, ww, hh, rgb, valid):
        """The picture of an image: the style of the layer when QGIS can draw
        it, and when it cannot, the three bands of the style stretched by the
        limits of that style, or by the cutout itself. Gives the bands, the
        alpha and the words the manifest keeps for how it was made."""
        # The renderer draws a layer in its own system: one reprojected onto
        # the grid of another is stretched from its bands instead.
        drawn = (None if s.get("reproject")
                 else self.styled_preview(s["layer"], grid, ww, hh))
        if drawn is not None:
            picture, alpha = drawn
            alpha = np.where(valid, alpha, 0).astype(np.uint8)
            return picture, alpha, "as styled in QGIS"
        limits = s.get("limits")
        stretch = "layer limits"
        if limits is None or len(limits) < len(rgb):
            limits, stretch = [], "per cutout"
            for band in rgb:
                v = band[valid]
                limits.append((float(np.percentile(v, 2)),
                               float(np.percentile(v, 98)))
                              if v.size else (0.0, 1.0))
        picture = np.zeros((3, hh, ww), np.uint8)
        for i, (low, high) in enumerate(limits[:3]):
            scaled = (rgb[i] - low) / max(high - low, 1e-6)
            # a band that is all one value, or all NaN, would put NaN into
            # the cast and a warning into the log for every cutout
            scaled = np.nan_to_num(scaled, nan=0.0, posinf=1.0, neginf=0.0)
            picture[i] = (255 * np.clip(scaled, 0, 1)).astype(np.uint8)
        picture[:, ~valid] = 0
        return picture, np.where(valid, 255, 0).astype(np.uint8), stretch

    def styled_preview(self, layer, grid, ww, hh):
        """The window drawn by the layer's own renderer, as the screen has it:
        the bands it shows, its stretch, its palette. Returns the three
        bands and the alpha, or None when it cannot be drawn here, which is
        never a reason to lose the cutout."""
        if abs(grid[2]) + abs(grid[4]) > 0 or grid[5] >= 0:
            return None
        try:
            renderer = layer.renderer()
            extent = QgsRectangle(grid[0], grid[3] + hh * grid[5],
                                  grid[0] + ww * grid[1], grid[3])
            block = renderer.block(1, extent, ww, hh)
            if block is None or not block.isValid():
                return None
            image = block.image()
            if image is None or image.isNull() \
                    or (image.width(), image.height()) != (ww, hh):
                return None
            image = image.convertToFormat(QImage.Format.Format_RGBA8888)
            line = image.bytesPerLine()
            bits = image.constBits()
            bits.setsize(line * hh)
            data = np.frombuffer(bits, np.uint8).reshape(hh, line)
            data = data[:, :ww * 4].reshape(hh, ww, 4)
            picture = np.ascontiguousarray(data[:, :, :3].transpose(2, 0, 1))
            alpha = np.ascontiguousarray(data[:, :, 3])
            return picture, alpha
        except Exception as err:
            log("%s could not be drawn with its style, the picture is "
                "stretched from its bands instead: %s" % (layer.name(), err))
            return None

    def finish_cutout(self, name, files, rows, assets, extent, gt, w, h, wkt,
                      tile_id, quiet):
        """The books, once every file of the cutout is safely on disk."""
        if not files:
            self.clear_pending()
            return False
        self.append_csv(rows)
        # Listed now, so whole: the note that it was in the making goes. Had
        # the row not been written (it says so, loudly), the files stay, as
        # they always did, and are not taken away by the next session.
        self.clear_pending()
        self.write_footprint(name, extent, w, h, wkt, tile_id)
        self.write_sampler()
        self.write_detection(name, rows, assets, files, wkt)
        if self.stac.isChecked():
            # the roles of what was written, not of what was asked for: an
            # item would say "classes, image" while it held the classes only
            files += self.write_stac(name, extent, gt, w, h, wkt, tile_id,
                                     assets,
                                     roles=sorted({r["role"] for r in rows}))
        # cutouts.csv, the footprints and the catalogue are the books of the
        # folder. Nothing goes into a campaign: there may be none, and the
        # folder is what describes itself.
        self.written.append((name, files))
        self.count += 1
        cut = ", ".join("%s as %s" % (r["tag"], r["role"]) for r in rows)
        left = "; ".join("%s left out: %s" % (t, why)
                         for t, why in sorted(self.skipped.items()))
        log("%s written, %d by %d pixels: %s%s. Files: %s"
            % (name, w, h, cut, ("; " + left) if left else "",
               ", ".join(os.path.basename(f) for f in files)))
        if not quiet:
            self.show_state()
            iface.messageBar().pushMessage(
                NAME, "%s written, %d by %d pixels: %s%s"
                % (name, w, h, cut, ("; " + left) if left else ""),
                level=LEVEL_WARNING if left else LEVEL_INFO,
                duration=8 if left else 3)
        return True

    def write_footprint(self, name, extent, w, h, wkt, tile_id):
        """Where each cutout was taken from, as a polygon.

        The ones cut from a frame are already traced by the frame itself, but
        the ones cut freehand would exist only as four numbers in a text file,
        and a dataset whose pieces cannot be put back on the map is hard to
        check a year later."""
        path = os.path.join(self.folder, "cutouts.gpkg")
        try:
            driver = ogr.GetDriverByName("GPKG")
            ds = driver.Open(path, 1) if os.path.exists(long_path(path)) \
                else driver.CreateDataSource(path)
            if ds is None:
                return
            layer = ds.GetLayerByName("cutouts")
            if layer is None:
                srs = None
                if wkt:
                    srs = osr.SpatialReference()
                    try:
                        srs.ImportFromWkt(wkt)
                    except Exception:
                        srs = None
                layer = ds.CreateLayer("cutouts", srs, ogr.wkbPolygon,
                                       ["GEOMETRY_NAME=geom"])
                for field, kind in (("cutout", ogr.OFTString),
                                    ("tile_id", ogr.OFTString),
                                    ("width_px", ogr.OFTInteger),
                                    ("height_px", ogr.OFTInteger),
                                    ("created", ogr.OFTString)):
                    d = ogr.FieldDefn(field, kind)
                    if kind == ogr.OFTString:
                        d.SetWidth(80)
                    layer.CreateField(d)
            feature = ogr.Feature(layer.GetLayerDefn())
            ring = ogr.Geometry(ogr.wkbLinearRing)
            for x, y in ((extent.xMinimum(), extent.yMinimum()),
                         (extent.xMinimum(), extent.yMaximum()),
                         (extent.xMaximum(), extent.yMaximum()),
                         (extent.xMaximum(), extent.yMinimum()),
                         (extent.xMinimum(), extent.yMinimum())):
                ring.AddPoint_2D(x, y)
            polygon = ogr.Geometry(ogr.wkbPolygon)
            polygon.AddGeometry(ring)
            feature.SetGeometry(polygon)
            feature.SetField("cutout", name)
            feature.SetField("tile_id", tile_id or "")
            feature.SetField("width_px", int(w))
            feature.SetField("height_px", int(h))
            feature.SetField("created", now())
            layer.CreateFeature(feature)
            feature = None
            layer = None
            ds = None
        except Exception as err:
            log("cannot write the footprint: %s" % err, loud=True)

    # ------------------------------------------------- one size for them all
    def hold_shape(self, nominal, w, h, res=None):
        """How many pixels a side of so many metres is, decided once.

        Two frames of the same side can come out one pixel apart depending on
        where they fall between two pixel edges, and a loader that piles the
        pieces into a batch wants them identical. The first cutout of a given
        side writes the answer into the manifest and every later one of that
        side is made to match, padded with nodata if it now reaches past the
        edge of the raster.

        The answer is remembered against the pixel it was measured on, not
        against the side alone. Ten metres is two hundred pixels at five
        centimetres and fifty at twenty, and a campaign that cuts from two
        rasters of different resolution would otherwise take the count from one
        and impose it on the other, quietly cutting four times the ground.

        The answers live in shapes.json in the cutouts folder, because they
        describe that folder. Manifests written by RasterLabel 1.0 kept them
        instead; the first time a folder with no shapes.json is cut into
        while a campaign that kept them is open, they are taken from there,
        once."""
        key = "%.3f" % float(nominal)
        if res:
            # Six decimals are plenty for a pixel in metres and nothing for one
            # in degrees: 5.64e-07 was written "0.000001", and every pixel
            # between half a millionth and one and a half millionths of a
            # degree shared one answer. Below a thousandth, six significant
            # figures; above it the key is the one older folders have.
            res = abs(float(res))
            key += "@" + ("%.6f" % res if res >= 1e-3 else "%.6g" % res)
        book = self.read_shapes()
        kept = book.get(key)
        if kept and len(kept) == 2:
            fixed = (max(2, int(kept[0])), max(2, int(kept[1])))
            if fixed != (w, h):
                log("side %s m: %d by %d to match the first cutout of that side"
                    % (key, fixed[0], fixed[1]))
            return fixed
        book[key] = [int(w), int(h)]
        self.write_shapes(book)
        return int(w), int(h)

    @property
    def shapes_path(self):
        return os.path.join(self.folder, "shapes.json")

    def read_shapes(self):
        try:
            with open(long_path(self.shapes_path), encoding="utf-8") as f:
                book = json.load(f)
            return book if isinstance(book, dict) else {}
        except FileNotFoundError:
            pass
        except Exception as err:
            log("shapes.json could not be read, the sizes start afresh: %s"
                % err, loud=True)
            return {}
        if self.campaign is not None:
            kept = self.campaign.data.get("cutout_shape")
            if isinstance(kept, dict) and kept:
                # Written into the folder at once, so it holds them from now
                # on whether or not that campaign is ever open again.
                book = dict(kept)
                self.write_shapes(book)
                log("the sizes of the cutouts kept by the campaign were "
                    "written into %s" % self.shapes_path)
                return book
        return {}

    def write_shapes(self, book):
        """Through a temporary file, as every book here is written."""
        try:
            os.makedirs(long_path(self.folder), exist_ok=True)
            write_atomic(self.shapes_path, json.dumps(book, indent=2))
        except OSError as err:
            log("cannot write shapes.json: %s" % err, loud=True)

    def write_sampler(self):
        """A small note saying what one piece of this dataset is.

        Written for whoever has to sample the survey again later with the same
        geometry. TorchGeo asks for a size and a stride and wants to be told
        whether the numbers are pixels or ground units, and getting that pair
        wrong is the usual way a second pass stops lining up with the first.

        It describes the DATASET, read back from the manifest, not the cutout
        that happened to be written last. Rewriting the file each time with
        that one cutout's height and width would make the GridGeoSampler line
        it offers, on a folder of mixed sizes or of freehand rectangles, true
        of one piece and wrong about all the others."""
        shapes = self.shapes_on_disk()
        if not shapes:
            return
        (h, w), same = shapes[0][0], len(shapes) == 1
        res = shapes[0][1]
        crs = QgsCoordinateReferenceSystem()
        wkt = self.reference_wkt()
        if wkt:
            crs.createFromWkt(wkt)
        classes = self.class_order()
        note = {
            "written_by": "%s %s" % (NAME, VERSION),
            "crs": crs_to_text(named_crs(crs)),
            "res": list(res),
            "size_pixels": [int(h), int(w)],
            "size_crs": [round(h * res[1], 6), round(w * res[0], 6)],
            "stride_pixels": [int(h), int(w)],
            "units": "pixels",
            "every_piece_the_same": bool(same),
            "shapes_found": [{"height": int(a), "width": int(b), "n": int(n)}
                             for (a, b), _, n in shapes],
            "all_the_same_size": bool(self.same_size.isChecked()),
            "classes": [{"index": i, "code": int(c["code"]), "name": c["name"]}
                        for i, c in enumerate(classes)],
            "order": ("rows then columns, as the arrays are written: the first "
                      "number of every pair is the height"),
            "torchgeo": ("GridGeoSampler(dataset, size=(%d, %d), "
                         "stride=(%d, %d), units=Units.PIXELS)"
                         % (h, w, h, w)),
            "note": ("size and stride are given in pixels because the pieces "
                     "were cut on the pixel grid of the first layer, not on "
                     "round numbers of metres. The same numbers in ground "
                     "units are size_crs, valid only at this resolution. The "
                     "stride here is the size, which tiles the ground without "
                     "overlap; lower it for overlapping patches."
                     + ("" if same else
                        " WARNING: this folder holds pieces of more than one "
                        "shape, listed under shapes_found. The size above is "
                        "the commonest one and a single sampler will not fit "
                        "them all.")),
        }
        labels = self.labels_note(classes)
        if labels is not None:
            note["labels"] = labels
            if labels.get("warning"):
                note["note"] += " WARNING: " + labels["warning"]
        if self.campaign is not None:
            note["campaign"] = self.campaign.data.get("name", "")
        if not classes:
            note["classes_note"] = (
                "no layer cut as classes has a style that names its classes, "
                "so none are listed: the codes in the files are the values of "
                "that layer as they are.")
        try:
            os.makedirs(long_path(self.folder), exist_ok=True)
            write_atomic(os.path.join(self.folder, "sampler.json"),
                         json.dumps(note, indent=2))
        except OSError as err:
            log("cannot write sampler.json: %s" % err, loud=True)

    def detection_boxes(self, wkt=None):
        """The boxes to write, from the reading chosen, or None when there is
        nothing to write them from: no campaign, the option off, no box. They
        come in the system `wkt` of the cutout, when that differs from the
        campaign's; when they cannot be put there nothing is written, and it
        is said."""
        if not self.campaign_package() or not self.boxes.isChecked():
            return None
        choice = None
        if self.boxes_reading is not None and self.boxes_choices:
            choice = self.boxes_choices[
                max(0, self.boxes_reading.currentIndex())]
        readings = None if choice is None or choice["mode"] == "all" \
            else set(map(tuple, choice["readings"]))
        try:
            boxes = det_boxes(self.campaign_package(), readings, wkt)
        except Exception as err:
            log("the boxes could not be read for the detection files, and "
                "none is written for this cutout: %s" % err, loud=True)
            return None
        return boxes or None

    def detection_book(self):
        """boxes_coco.json as it is, or None."""
        try:
            with open(long_path(os.path.join(self.folder, DET_COCO_NAME)),
                      encoding="utf-8") as f:
                book = json.load(f)
            return book if isinstance(book, dict) else None
        except (OSError, ValueError):
            return None

    def write_detection(self, name, rows, assets, files, wkt=None):
        """The boxes of the campaign in the pixels of the images of a cutout:
        its images are added to boxes_coco.json, and each gets its YOLO file
        in labels/ (put in `files`, so that undo takes it away with the
        rest). In a campaign with frames an image the frames do not cover is
        over ground nobody read: it gets no file, an empty one would say
        there is nothing there, and it is listed in the book as unlabelled.
        A failure is said and does not undo the cutout."""
        boxes = self.detection_boxes(wkt)
        if boxes is None:
            return
        frames = None
        if self.tiled:
            try:
                frames = det_frames(self.campaign_package(), wkt)
            except Exception as err:
                log("the frames could not be read for the detection files, "
                    "and none is written for this cutout: %s" % err,
                    loud=True)
                return
        images = []
        for r in rows:
            if r.get("role") != "image":
                continue
            # the image itself: the asset the cut put down as "_image"
            main = assets.get("%s_image" % r["tag"])
            if not main or not landed(main[0]):
                continue
            images.append({
                "file": os.path.basename(main[0]), "cutout": name,
                "tag": r["tag"],
                "width": int(r["width_px"]), "height": int(r["height_px"]),
                "extent": tuple(float(v) for v in r.get("grid_box") or (
                    r[k] for k in ("xmin", "ymin", "xmax", "ymax")))})
        if not images:
            return
        plan = det_plan(images, boxes, self.campaign.data.get("classes"),
                        frames)
        try:
            book = det_merge(self.detection_book(), plan, name)
            folder = os.path.join(self.folder, DET_LABELS_FOLDER)
            if plan["yolo"]:
                os.makedirs(long_path(folder), exist_ok=True)
            for stem, text in plan["yolo"].items():
                path = os.path.join(folder, stem + ".txt")
                files.append(path)
                write_atomic(path, text)
            if plan["yolo"]:
                write_atomic(os.path.join(folder, DET_CLASSES_NAME),
                             plan["classes_txt"])
            write_atomic(os.path.join(self.folder, DET_COCO_NAME),
                         det_coco_text({"coco": book}))
        except OSError as err:
            log("cannot write the detection files of %s: %s" % (name, err),
                loud=True)
            return
        if plan["unlabelled"]:
            log("%d image%s of %s left without a label file: the ground is "
                "outside the frames of the campaign, nobody read it, and an "
                "empty file would say there is nothing there. Listed under "
                "unlabelled_images in %s; leave them out of training."
                % (len(plan["unlabelled"]),
                   "" if len(plan["unlabelled"]) == 1 else "s", name,
                   DET_COCO_NAME), loud=True)

    def forget_detection(self, name):
        """Take a cutout out of boxes_coco.json (its YOLO files go with the
        rest of its files). Never raises."""
        book = self.detection_book()
        if book is None:
            return
        try:
            write_atomic(os.path.join(self.folder, DET_COCO_NAME),
                         det_coco_text({"coco": det_remove(book, name)}))
        except OSError as err:
            log("boxes_coco.json could not be brought up to date: %s" % err,
                loud=True)

    def labels_note(self, classes):
        """The "labels" block of sampler.json: which value the layers cut as
        classes hold where nobody labelled, and how to tell a loss so.

        Read back from cutouts.csv, like the shapes, so it describes the
        folder and not the last cutout: one value when every piece of
        classes agrees, None and a warning when they do not. What the 0 of
        the files means is said from the layer being cut now. None when no
        layer has been cut as classes into this folder."""
        found, by_layer, pieces = set(), {}, 0
        try:
            with open(long_path(self.csv_path), newline="", encoding="utf-8",
                      errors="replace") as f:
                for row in csv.DictReader(f):
                    if (row.get("role") or "") != "classes":
                        continue
                    pieces += 1
                    held = (row.get("ignore_index") or "").strip()
                    try:
                        value = int(held) if held else None
                    except ValueError:
                        value = None
                    found.add(value)
                    if value is not None:
                        by_layer[csv_untext(row.get("tag") or "")] = value
        except (OSError, csv.Error) as err:
            log("cannot read the manifest for the sampler: %s" % err)
            return None
        if not pieces:
            return None
        value = next(iter(found)) if len(found) == 1 else None
        source = next((s for s in self.sources
                       if s.get("role") == "classes"), None)
        whence = ((source or {}).get("ignore") or (None, False, None))[2]
        own =((source or {}).get("readings") or {}).get(
            "RASTERLABEL_UNLABELLED", "")
        if whence == "file":
            mode = own if own in ("ignore", "frames") else "ignore"
            zero_is = "a class" if mode == "frames" else "not present"
        elif whence == "campaign mask":
            mode, zero_is = "ignore", "not present"
        elif whence == "map":
            mode, zero_is = "map", "a class"
        elif source is not None and source.get("readings"):
            mode, zero_is = "zero", "unlabelled"
        else:
            mode, zero_is = "map", "a class"
        named = [int(c["code"]) for c in classes or []]
        k = (max(named) + 1) if named else None
        out = {"ignore_index": value, "ignore_index_by_layer": by_layer,
               "unlabelled": mode, "zero_is": zero_is}
        if value is not None:
            v = value
            out.update({
                "meaning": ("%d marks pixels nobody labelled; leave them out "
                            "of the loss. It is not a class and not a "
                            "foreground: samgeo and Deepness write 255 for "
                            "the foreground of a binary mask." % v),
                "pytorch": "torch.nn.CrossEntropyLoss(ignore_index=%d)" % v,
                "torchgeo": ("SemanticSegmentationTask(..., num_classes=%s, "
                             "ignore_index=%d)" % (k if k else "K", v)),
                "mmsegmentation": ("decode_head=dict(..., ignore_index=%d), "
                                   "reduce_zero_label=False" % v),
                "targets": ("read the masks as integers and hand them to "
                            "the loss as torch.long; a mask of 16 signed "
                            "bits must be cast first" if v < 0 or v > 255
                            else "read the masks as integers and hand them "
                                 "to the loss as torch.long")})
            if k:
                out["num_classes"] = k
        elif len(found) > 1:
            out["warning"] = (
                "the pieces of classes in this folder do not hold one "
                "ignore value (%s): a single loss cannot leave them all out; "
                "cut them again with one value, or into separate folders"
                % ", ".join("none" if f is None else str(f)
                            for f in sorted(found, key=lambda f: (
                                f is not None, f or 0))))
            out["meaning"] = "the ignore value is not the same in every piece"
        else:
            out["meaning"] = (
                "no ignore value: the files hold 0 where nobody labelled"
                if zero_is == "unlabelled" else
                "no ignore value: the files hold the values of their map, "
                "0 included, and the padding past its edge is 0")
        return out

    def shapes_on_disk(self):
        """The shapes the cutouts in this folder really have, commonest first,
        read back from the manifest rather than remembered. Cutouts are
        counted, not files: a cutout of three layers has three rows in the
        manifest and is one piece."""
        counts, res = {}, {}
        try:
            with open(long_path(self.csv_path), newline="",
                      encoding="utf-8") as f:
                for at, row in enumerate(csv.DictReader(f)):
                    try:
                        key = (int(row["height_px"]), int(row["width_px"]))
                        span = (float(row["xmax"]) - float(row["xmin"]),
                                float(row["ymax"]) - float(row["ymin"]))
                    except (KeyError, TypeError, ValueError):
                        continue
                    # a row with no cutout name is a cutout of its own
                    counts.setdefault(key, set()).add(
                        row.get("cutout") or "row %d" % at)
                    if key not in res and key[0] and key[1]:
                        res[key] = (abs(span[0] / key[1]),
                                    abs(span[1] / key[0]))
        except (OSError, csv.Error) as err:
            log("cannot read the manifest for the sampler: %s" % err)
            return []
        return [(k, res.get(k, (0.0, 0.0)), len(n))
                for k, n in sorted(counts.items(),
                                   key=lambda kv: -len(kv[1]))]

    def reference_wkt(self):
        sources = [s for s in self.sources
                   if QgsProject.instance().mapLayer(s["id"]) is not None]
        if not sources:
            return ""
        layer = QgsProject.instance().mapLayer(sources[0]["id"])
        try:
            return layer.crs().toWkt() if layer.crs().isValid() else ""
        except Exception:
            return ""

    # ------------------------------------------------------- the catalogue
    def lonlat_footprint(self, extent, wkt):
        """The cutout outline in longitude and latitude, which is the only
        geometry a STAC item is allowed to carry, whatever the data is in
        (project.lonlat_footprint)."""
        try:
            return lonlat_footprint((extent.xMinimum(), extent.yMinimum(),
                                     extent.xMaximum(), extent.yMaximum()),
                                    wkt)
        except Exception as err:
            log("cannot put the cutout in degrees: %s" % err)
            return None, None

    def projection_of(self, gt, w, h, wkt, extent):
        return projection_of(gt, w, h, wkt,
                             (extent.xMinimum(), extent.yMinimum(),
                              extent.xMaximum(), extent.yMaximum()))

    def stac_folder(self):
        return os.path.join(self.folder, "stac")

    # The raster extension of STAC (constants.RASTER_EXT), for the data type
    # of every band: a map of classes is cut in bytes or in a wider type
    # depending on the map, and a reader of the catalogue should not have to
    # open the file to know. The classification extension
    # (CLASSIFICATION_EXT) only on an item whose classes carry an ignore
    # value, marked as nodata.

    @staticmethod
    def stac_type(kind):
        """The data_type of the raster extension for a GDAL type."""
        name = gdal.GetDataTypeName(kind) or ""
        return "uint8" if name == "Byte" else (name.lower() or "other")

    def stac_assets(self, book):
        """Asset paths are written relative to the item, so the folder can be
        moved or zipped whole and still be readable. An entry may carry a
        fifth element, fields of its own such as raster:bands."""
        out = {}
        for key, entry in sorted(book.items()):
            path, media, roles, title = entry[:4]
            out[key] = {"href": "../" + os.path.basename(path),
                        "type": media, "roles": list(roles), "title": title}
            if len(entry) > 4 and entry[4]:
                out[key].update(entry[4])
        return out

    def write_stac(self, name, extent, gt, w, h, wkt, tile_id, assets,
                   roles=None):
        """One document per cutout: what was cut, and out of which layers.

        There is no second one, a label item, describing the annotation burned
        onto the cutout. There is no such burn: the ground truth of a cutout
        is a layer somebody marked "classes", not the hand drawing of this
        campaign, and a label item is a claim about hand drawing. Such an item
        would also claim more than it holds. It would list every class of the
        campaign whether or not the tile contained one, invent a count of one
        for each kind of label, and announce an object detection task even
        when the box file it pointed at was empty. A catalogue that overstates
        is worse than none: somebody downstream believes it."""
        folder = self.stac_folder()
        # utcnow() is deprecated from Python 3.12, and says so on every
        # cutout catalogued: the same moment, asked of an aware clock
        stamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        shape, bbox = self.lonlat_footprint(extent, wkt)
        if shape is None:
            log("no usable projection: the cutout is not catalogued")
            return []
        projection = self.projection_of(gt, w, h, wkt, extent)
        try:
            os.makedirs(long_path(folder), exist_ok=True)
        except OSError as err:
            log("cannot make the stac folder: %s" % err)
            return []

        # The roles of the files really written, handed in by the caller. The
        # roles asked for would make every item of a session that had left the
        # image out say "classes, image" over assets of classes only.
        if roles is None:
            roles = sorted({s.get("role") for s in self.sources
                            if s.get("role") in ("image", "classes")})
        # The date of an item is the date of what it shows, when a layer says
        # when it was taken. The moment of the cutting is the date of the
        # cutout, and is "created". With no date in any layer the item has
        # none: datetime is null, which STAC allows when the item has a
        # start and an end, and these are the moment of the cutting, said
        # to be so, because that is all there is.
        moments = sorted({src.get("moment") for src in self.sources
                          if src.get("moment")})
        if len(moments) == 1:
            when = {"datetime": moments[0]}
        elif moments:
            when = {"datetime": None, "start_datetime": moments[0],
                    "end_datetime": moments[-1]}
        else:
            when = {"datetime": None, "start_datetime": stamp,
                    "end_datetime": stamp,
                    "rasterlabel:datetime_is": "the moment of the cutting: "
                                               "no layer says when it was "
                                               "taken"}
        properties = dict(when, created=stamp, title="%s" % name)
        properties.update({"rasterlabel:tile_id": tile_id or None,
                           "rasterlabel:roles": roles,
                           "rasterlabel:version": VERSION})
        # Only when an annotation campaign is open: a cutout needs none, and
        # a field that names no campaign is a claim about nothing.
        if self.campaign is not None:
            properties["rasterlabel:campaign"] = self.campaign.data.get("name", "")
            properties["rasterlabel:campaign_id"] = self.campaign.data.get("id", "")
        # A layer of classes that is the mask of a campaign says which
        # readings it holds, and how they were put together: one reading,
        # all of them, or their consensus. Only for such a layer; a map of
        # classes made anywhere else makes no claim about readings.
        readings = {}
        for src in self.sources:
            if src.get("role") == "classes" and src.get("readings"):
                got = src["readings"]
                readings[src["tag"]] = {
                    "mode": got.get("RASTERLABEL_READING_MODE", ""),
                    "readings": [r for r in got.get(
                        "RASTERLABEL_READINGS", "").split("; ") if r],
                    "rule": got.get("RASTERLABEL_READING_RULE", "")}
        if readings:
            properties["rasterlabel:readings"] = readings
        # The value each layer of classes holds where nobody labelled, when
        # it holds one: the same number as its nodata and its classification
        # entry, said once for the item.
        ignored = {src["tag"]: int(src["ignore"][0]) for src in self.sources
                   if src.get("role") == "classes" and src.get("ignore")
                   and src["ignore"][0] is not None}
        if ignored:
            properties["rasterlabel:ignore_index"] = ignored
        listed = self.stac_assets(assets)
        extensions = [PROJ_EXT]
        if any("raster:bands" in a for a in listed.values()):
            extensions.append(RASTER_EXT)
        if any("classification:classes" in a for a in listed.values()):
            extensions.append(CLASSIFICATION_EXT)
        item = {
            "type": "Feature", "stac_version": STAC_VERSION,
            "geometry": shape, "bbox": bbox,
            "stac_extensions": extensions,
            "id": name,
            "properties": dict(properties, **projection),
            "assets": listed,
            "links": [{"rel": "root", "href": "catalog.json",
                       "type": "application/json"},
                      {"rel": "parent", "href": "catalog.json",
                       "type": "application/json"},
                      {"rel": "self", "href": "%s.json" % name,
                       "type": "application/json"}]}
        written = self.dump_json(os.path.join(folder, "%s.json" % name), item)
        self.refresh_catalog()
        return written

    def dump_json(self, path, payload):
        try:
            write_atomic(path, json.dumps(payload, indent=2))
            return [path]
        except OSError as err:
            log("cannot write %s: %s" % (os.path.basename(path), err))
            return []

    def refresh_catalog(self):
        """The root of the catalogue, rebuilt from what is actually on disk.

        Rebuilt rather than appended to, so that a cutout deleted by hand or
        undone leaves no link behind pointing at a file that is gone.

        Linking every item in the folder would link an item whose files have
        been deleted by hand while its json stayed behind, and a reader of
        the catalogue would be sent to files that are not there. Such an
        item is left out of catalog.json and said in the log, once; its json
        is kept, never deleted: it is the record of what that cutout was."""
        folder = self.stac_folder()
        try:
            names = sorted(f for f in os.listdir(long_path(folder))
                           if f.endswith(".json") and f != "catalog.json")
        except OSError:
            return
        items, left_out = [], []
        for f in names:
            missing = self.missing_assets(os.path.join(folder, f))
            if missing:
                left_out.append((f, missing))
            else:
                items.append(f)
        said = getattr(self, "_left_out", None)
        if said is None:
            said = self._left_out = set()
        fresh = [(f, m) for f, m in left_out if f not in said]
        if fresh:
            log("%d STAC item%s left out of catalog.json because %s files "
                "are no longer on disk (the items are kept in %s): %s"
                % (len(fresh), "" if len(fresh) == 1 else "s",
                   "its" if len(fresh) == 1 else "their", folder,
                   "; ".join("%s (%s)" % (f, ", ".join(m[:3]))
                             for f, m in fresh[:5])))
            said.update(f for f, _ in fresh)
        name = tidy(os.path.basename(os.path.normpath(self.folder)), "cutouts")
        catalog = {
            "type": "Catalog",
            "stac_version": STAC_VERSION,
            "id": name,
            "title": "%s: %s" % (NAME, name),
            "description": (
                "Cutouts, one image item each. Every piece is on the pixel "
                "grid of the first layer that was cut, so the pieces stack. "
                "sampler.json beside this folder says what one piece is."),
            "links": ([{"rel": "root", "href": "catalog.json",
                        "type": "application/json"},
                       {"rel": "self", "href": "catalog.json",
                        "type": "application/json"}]
                      + [{"rel": "item", "href": f, "type": "application/json"}
                         for f in items])}
        self.dump_json(os.path.join(folder, "catalog.json"), catalog)

    @staticmethod
    def missing_assets(item_path):
        """The files an item lists that are not on disk; ["the item itself"]
        when it cannot be read as one."""
        try:
            with open(long_path(item_path), encoding="utf-8") as f:
                item = json.load(f)
            assets = item.get("assets") or {}
        except Exception:
            return ["the item itself cannot be read"]
        here = os.path.dirname(item_path)
        out = []
        for asset in assets.values():
            href = (asset or {}).get("href") or ""
            if not href or "://" in href:
                continue
            where = os.path.normpath(os.path.join(here, href))
            if not os.path.exists(long_path(where)):
                out.append(os.path.basename(where))
        return out

    def class_order(self):
        """YOLO counts its classes from zero, in one fixed order: the codes of
        the first layer cut as classes, as its style names them, so it is the
        same for every cutout and stays the same when a class is added later
        with a higher code. Not the campaign legend, which numbers what is
        drawn by hand and not what that layer holds. The ignore
        value is not a class, whatever the style calls it, and gets no
        index."""
        for s in self.sources:
            if s.get("role") != "classes":
                continue
            named = style_classes(s.get("layer"), s.get("band") or 1) or []
            ign = (s.get("ignore") or (None,))[0]
            return sorted([c for c in named
                           if ign is None or int(c["code"]) != int(ign)],
                          key=lambda c: c["code"])
        return []

    def class_colours(self, layer, band, codes, ignore=None):
        """The colours the classes PNG is painted with: the style of the layer
        cut, and for a code it does not name a colour of its own, the same one
        for that code in every cutout. Not the campaign legend, which says
        nothing about this layer. The ignore value is no class and is given
        none."""
        named = {c["code"]: c for c in (style_classes(layer, band) or [])
                 if ignore is None or c["code"] != ignore}
        out = list(named.values())
        for v in sorted(set(np.unique(codes).tolist()) - set(named)):
            if v and (ignore is None or v != ignore):
                out.append({"code": int(v), "name": "",
                            "colour": thematic_colour(int(v))})
        return out

    # ----------------------------------------------------------- the books
    CSV_COLUMNS = ["cutout", "tag", "role", "layer", "bands", "resampled",
                   "stretch", "tile_id", "xmin", "ymin", "xmax", "ymax",
                   "width_px", "height_px", "format", "side_m", "when",
                   "ignore_index"]

    @property
    def csv_path(self):
        return os.path.join(self.folder, "cutouts.csv")

    def upgrade_csv(self):
        """A manifest written by RasterLabel 1.0, with fewer columns, given
        the columns of this one before a row is added to it: every old row
        kept, the new columns empty. Through a temporary file, as every book
        here is rewritten, so an interruption leaves the old one whole. A
        column is only ever added at the end, so a reader that counts
        columns finds the old ones where they were. Returns the columns the
        file has now: a header that is not one of ours is left alone, and
        the rows are written to it as it is."""
        path = long_path(self.csv_path)
        try:
            with open(path, newline="", encoding="utf-8",
                      errors="replace") as f:
                header = next(csv.reader(f), None)
        except (OSError, csv.Error):
            return self.CSV_COLUMNS
        if not header or header == self.CSV_COLUMNS:
            return self.CSV_COLUMNS
        if header != self.CSV_COLUMNS[:len(header)]:
            return header
        spare = path + ".tmp"
        try:
            with open(path, newline="", encoding="utf-8",
                      errors="replace") as f:
                old = list(csv.DictReader(f))
            with open(spare, "w", newline="", encoding="utf-8") as f:
                writer = csv.DictWriter(f, self.CSV_COLUMNS, restval="",
                                        extrasaction="ignore")
                writer.writeheader()
                for r in old:
                    writer.writerow(r)
            os.replace(spare, path)
            log("cutouts.csv given the column%s %s of this build"
                % ("s" if len(self.CSV_COLUMNS) - len(header) > 1 else "",
                   ", ".join(self.CSV_COLUMNS[len(header):])))
            return self.CSV_COLUMNS
        except (OSError, csv.Error, ValueError) as err:
            log("cannot bring cutouts.csv up to this build: %s" % err,
                loud=True)
            try:
                os.remove(spare)
            except OSError:
                pass
            return header

    def append_csv(self, rows):
        fresh = not os.path.exists(long_path(self.csv_path))
        columns = self.CSV_COLUMNS if fresh else self.upgrade_csv()
        try:
            with open(long_path(self.csv_path), "a", newline="",
                      encoding="utf-8") as f:
                writer = csv.DictWriter(f, columns, restval="",
                                        extrasaction="ignore")
                if fresh:
                    writer.writeheader()
                for r in rows:
                    writer.writerow({k: csv_text(v) for k, v in r.items()})
        except (OSError, ValueError) as err:
            # The manifest is the only thing that knows which files belong to
            # which cutout, and undo reads it. Losing a row in silence means
            # losing the only handle on those files.
            log("cannot write the manifest: %s" % err, loud=True)

    def free_name(self):
        """A name no file in the folder is already using.

        A counter taken from the number of distinct names in cutouts.csv
        would be dangerous, because every writer here truncates what it finds.
        Lose that csv, or have one append fail (it only logs), and the counter
        would rewind onto names that already exist: a previous cutout, its
        mask, its pictures and its STAC item overwritten one after another
        without a word. Counting is fine as a starting guess. The folder has
        the last word, because the folder is where the damage would happen."""
        #
        # The number comes from the highest one in use anywhere in the
        # folder: the files, cutouts.csv, the footprints, and the stac folder.
        # Counting the names in cutouts.csv goes wrong as soon as somebody
        # deletes cutouts by hand: the count falls, the next name is one whose
        # STAC item is still in stac/, and that item is written over and
        # linked again from the catalogue with the files of another cutout.
        stem = tidy(self.prefix.text(), "cut")
        n = self.highest_in_use(stem) + 1
        first = n
        while True:
            name = "%s_%04d" % (stem, n)
            if not self.name_taken(name):
                break
            n += 1
        if n != first:
            log("cutout %s_%04d was taken: writing %s instead"
                % (stem, first, name))
        return name

    def name_taken(self, name):
        """Anything of this name in the folder or in its stac folder."""
        if glob_like(self.folder, name):
            return True
        stac = self.stac_folder()
        return os.path.isdir(long_path(stac)) and glob_like(stac, name)

    def highest_in_use(self, stem):
        """The highest number after stem_ that anything in the folder uses."""
        pattern = re.compile(r"^%s_(\d+)(?:[_.]|$)" % re.escape(stem))
        names = set(self.listed_names()) | set(self.footprint_names())
        for folder in (self.folder, self.stac_folder()):
            try:
                names.update(os.listdir(long_path(folder)))
            except OSError:
                pass
        top = 0
        for entry in names:
            m = pattern.match(entry or "")
            if m:
                top = max(top, int(m.group(1)))
        return top

    def manifest_rows(self):
        """The rows of cutouts.csv, or [] when there is none to read.

        errors="replace", and every exception caught, not only OSError. A
        cutouts.csv whose bytes are not UTF-8, which is what a spreadsheet on
        an Italian Windows writes if somebody opens and saves it, threw
        UnicodeDecodeError out of __init__ and the Cutouts module could never
        be opened again for that campaign. Counting is not worth that."""
        rows = self.read_manifest()
        return [] if rows is None else rows

    def read_manifest(self):
        """The rows of cutouts.csv, [] when the file does not exist, and None
        when it exists and cannot be read (held open by a spreadsheet, no
        permission, damaged). [] and None are different answers: the first
        says nothing is listed, the second says it is not known."""
        path = self.csv_path
        if not os.path.exists(long_path(path)):
            return []
        try:
            with open(long_path(path), newline="", encoding="utf-8",
                      errors="replace") as f:
                # names and tags as they were before csv_text quoted them
                return [csv_untext_row(r) for r in csv.DictReader(f)]
        except Exception as err:
            log("the cutouts manifest could not be read: %s" % err)
            return None

    def listed_names(self):
        return [r.get("cutout") or "" for r in self.manifest_rows()]

    def footprint_names(self):
        """The cutouts cutouts.gpkg has a footprint for."""
        path = os.path.join(self.folder, "cutouts.gpkg")
        if not os.path.exists(long_path(path)):
            return []
        ds = None
        try:
            ds = ogr.Open(path, 0)
            layer = ds.GetLayerByName("cutouts")
            return [f.GetField("cutout") or "" for f in layer]
        except Exception:
            return []
        finally:
            ds = None

    def count_existing(self):
        """How many cutouts the folder holds: those cutouts.csv lists that
        still have their files on disk.

        Files deleted by hand are part of life: somebody clears out a few bad
        pieces in Explorer and leaves the books behind. The count is not the
        names in cutouts.csv whatever is on disk: the ones whose files
        are gone are kept in self.gone, shown on the panel and said in the
        log, together with the footprints and the STAC items of cutouts no
        longer there. Nothing is changed or deleted on the strength of it: a
        row or an item is the record of what was cut."""
        self.gone = []
        try:
            rows = self.manifest_rows()
            if not rows:
                return 0
            try:
                present = set(os.listdir(long_path(self.folder)))
            except OSError:
                present = set()
            order, found = [], {}
            for row in rows:
                name = row.get("cutout") or ""
                if not name:
                    continue
                if name not in found:
                    order.append(name)
                    found[name] = []
                prefix = "%s_%s_%s" % (name, row.get("tag") or "",
                                       row.get("role") or "")
                found[name].append(any(f.startswith(prefix + ".")
                                       for f in present))
            self.gone = [n for n in order if not any(found[n])]
            partly = [n for n in order if any(found[n]) and not all(found[n])]
            self.report_books(present, partly)
            return len(order) - len(self.gone)
        except Exception as err:
            log("the cutouts manifest could not be counted: %s" % err)
            return 0

    def report_books(self, present, partly):
        """Say, in the log, what the books list and the disk no longer has."""
        def some(names):
            return ", ".join(names[:8]) + (", ..." if len(names) > 8 else "")
        if self.gone:
            log("%d cutouts listed in cutouts.csv have no file left on disk: "
                "%s. Their rows are kept; nothing was deleted."
                % (len(self.gone), some(self.gone)))
        if partly:
            log("%d cutouts have lost some of their files: %s"
                % (len(partly), some(partly)))
        loose = [n for n in self.footprint_names()
                 if n and not any(f.startswith(n + "_") for f in present)]
        if loose:
            log("%d footprints in cutouts.gpkg belong to cutouts no longer on "
                "disk: %s" % (len(loose), some(loose)))
        stac = self.stac_folder()
        try:
            items = sorted(f for f in os.listdir(long_path(stac))
                           if f.endswith(".json") and f != "catalog.json")
        except OSError:
            items = []
        orphans = [f for f in items
                   if self.missing_assets(os.path.join(stac, f))]
        if orphans:
            log("%d STAC items describe files no longer on disk, and are left "
                "out of catalog.json from the next cutout on: %s"
                % (len(orphans), some(orphans)))

    def rewrite_csv(self, keep):
        """The manifest rewritten whole, through a temporary file.

        Truncating the real one and writing into it means that an interruption
        anywhere in the middle leaves a manifest that is half of two different
        versions, and the manifest is the only thing that knows which files
        belong to which cutout."""
        path = long_path(self.csv_path)
        spare = path + ".tmp"
        try:
            with open(spare, "w", newline="", encoding="utf-8") as f:
                f.write("".join(keep))
            os.replace(spare, path)
            return True
        except OSError as err:
            log("cannot rewrite %s: %s" % (os.path.basename(path), err))
            try:
                os.remove(spare)
            except OSError:
                pass
            return False

    def undo(self):
        if not self.written:
            iface.messageBar().pushMessage(
                NAME, "nothing cut in this session", level=LEVEL_INFO, duration=2)
            return
        name, files = self.written.pop()
        # The manifest is read BEFORE anything is deleted. Read afterwards, a
        # manifest that could not be read would leave the rasters already gone
        # and the campaign still describing them: do the thing that can fail
        # while nothing has been destroyed yet.
        lines = []
        if os.path.exists(long_path(self.csv_path)):
            try:
                with open(long_path(self.csv_path), newline="",
                          encoding="utf-8", errors="replace") as f:
                    lines = f.readlines()
            except Exception as err:
                log("the cutouts manifest could not be read, so nothing was "
                    "removed: %s" % err, loud=True)
                self.written.append((name, files))
                return
        refused = []
        for path in files:
            main = long_path(path)
            for p in (main, long_path(path + ".aux.xml")):
                try:
                    os.remove(p)
                except FileNotFoundError:
                    pass
                except OSError as err:
                    if p == main:
                        # On Windows a file another program still holds open
                        # cannot be removed. Saying "removed from disk" about it
                        # is the kind of lie that is found out months later.
                        refused.append((p, err))
        # An empty manifest would raise IndexError on lines[0], and AFTER the
        # rasters had already been deleted, so the campaign json and the
        # counter would be left describing files that were gone. A header is
        # kept only if there is one to keep.
        if lines:
            head = lines[:1] if lines[0].startswith("cutout,") else []
            body = lines[len(head):]
            # The name sits in the file as csv_text wrote it, or plainly, as
            # RasterLabel 1.0 wrote it: a folder cut with both has both.
            starts = (csv_text(name) + ",", name + ",")
            keep = head + [l for l in body if not l.startswith(starts)]
            self.rewrite_csv(keep)
        # The footprint and the sampler note go with it. Otherwise Undo would
        # leave the polygon of a cutout that no longer exists in cutouts.gpkg,
        # and sampler.json still counting it among the shapes of the folder.
        self.remove_footprint(name)
        self.forget_detection(name)
        if self.shapes_on_disk():
            self.write_sampler()
        else:
            try:
                os.remove(long_path(os.path.join(self.folder, "sampler.json")))
            except OSError:
                pass
        if os.path.isdir(long_path(self.stac_folder())):
            self.refresh_catalog()
        self.count = max(0, self.count - 1)
        self.show_state()
        if refused:
            log("%s was taken out of the manifest, but %d of its files could "
                "not be removed and are still on disk: %s"
                % (name, len(refused),
                   "; ".join("%s (%s)" % (os.path.basename(p), err)
                             for p, err in refused[:3])), loud=True)
        else:
            log("%s removed from disk" % name)

    def remove_footprint(self, name):
        """Take a cutout's polygon out of cutouts.gpkg. Never raises."""
        path = os.path.join(self.folder, "cutouts.gpkg")
        if not os.path.exists(long_path(path)):
            return 0
        ds = None
        try:
            ds = ogr.Open(path, 1)
            layer = ds.GetLayerByName("cutouts")
            layer.SetAttributeFilter("cutout = '%s'" % name.replace("'", "''"))
            fids = [f.GetFID() for f in layer]
            layer.SetAttributeFilter(None)
            for fid in fids:
                layer.DeleteFeature(fid)
            return len(fids)
        except Exception as err:
            log("the footprint of %s could not be taken out of cutouts.gpkg: "
                "%s" % (name, err), loud=True)
            return 0
        finally:
            ds = None

    def show_folder(self):
        # makedirs first: on a campaign where nothing has been cut yet there is
        # nothing to open, and a button that does nothing looks broken
        try:
            os.makedirs(self.folder or self.default_folder(), exist_ok=True)
        except OSError:
            pass
        try:
            QDesktopServices.openUrl(QUrl.fromLocalFile(self.folder))
        except Exception:
            QMessageBox.information(self, NAME, self.folder)

    def save(self):
        """Nothing to save: every cutout is on disk when it is written, and
        there is no campaign to write to."""
        iface.messageBar().pushMessage(NAME, "%d cutouts in %s"
                                       % (self.count, self.folder),
                                       level=LEVEL_INFO, duration=3)

    def unsaved(self):
        return False

# ---------------------------------------------------------------------
# ---- sections_objects ------------------------------------------------
# ---------------------------------------------------------------------

class Held(object):
    """One setting of the reading the panel holds, read the way Annotate
    reads its check box or its spin box. The filter Annotate puts on the
    tables is then put on them from here too, the same one, rather than a
    second copy of it that could drift away from the first."""

    def __init__(self, read):
        self.read = read

    def isChecked(self):
        return bool(self.read())

    def value(self):
        return self.read()


class ReadingFilter(object):
    """The filter of the reading in hand, put on the tables of a campaign
    with no module open to do it.

    Annotate and Objects filter the tables as they open, and the tables are
    drawn by that filter alone. A campaign opened by itself, before either
    is pressed, would show every operator and every pass on top of each other
    in the colours of the legend until Annotate was pressed. This is the
    same filter, the very methods of Annotate lent over, set from the
    reading the panel holds: the map looks the same before Annotate is
    pressed as after."""

    OPERATOR_BLANK = AnnotationSection.OPERATOR_BLANK
    apply_filter = AnnotationSection.__dict__["apply_filter"]
    filter_layer = AnnotationSection.__dict__["filter_layer"]
    hiding = AnnotationSection.__dict__["hiding"]
    layer = AnnotationSection.__dict__["layer"]

    def __init__(self, panel):
        self.panel = panel
        self.campaign = panel.campaign
        self.tiled = bool(self.campaign.data.get("with_tiles"))
        held = lambda: panel.reading() or {}      # noqa: E731
        self.by_operator = Held(lambda: held().get("by_operator", True))
        self.blind = Held(lambda: held().get("blind", True))
        self.pass_no = Held(lambda: int(panel.which_pass()))
        self.only_current = Held(lambda: False)

    @property
    def polygons(self):
        return self.layer("polygons")

    def current_tile_id(self):
        return None

    def operator_name(self):
        return operator_word(self.panel.who_is_drawing())

    def show_blind(self):
        """Nothing to say: there is no strip when no module is open."""


class ObjectsSection(QGroupBox):
    """Boxes with a class on them: what detection is trained on.

    Boxes are free to overlap and free to be redrawn. Nothing is clipped,
    nothing is subtracted, and the annotation polygons are not touched: the
    two products live side by side in the same campaign and are exported
    separately."""

    def __init__(self, panel):
        super().__init__("")
        self.panel = panel
        self.campaign = panel.campaign
        reference = find_mine(self.campaign.data["id"], "boxes") \
            or find_mine(self.campaign.data["id"], "tiles") \
            or find_mine(self.campaign.data["id"], "polygons")
        self.geometry = Geometry(self.campaign,
                                 reference.crs() if reference is not None else None)
        self.tiled = self.campaign.data["with_tiles"]
        self.class_name = None
        self.selected = None
        self.tool = None
        self._tool_before = tool_in_hand()   # what the map had before this
        self._buttons = []
        self.since_save = 0             # edits since the boxes last reached disk
        # The reading is the panel's, as in Annotate: who draws, which pass,
        # and whether the other readings are hidden. Without it every box
        # would be stamped with the campaign's creator and pass 1, whoever
        # drew it, in front of every other reading's boxes.
        self.by_operator = Held(
            lambda: self.held_reading().get("by_operator", True))
        self.blind = Held(lambda: self.held_reading().get("blind", True))
        self.pass_no = Held(lambda: int(self.panel.which_pass()))
        self.only_current = Held(lambda: False)
        self.build()
        self.apply_filter()
        self.show_blind()
        time_open(self, "objects")

    # ----------------------------------------------------------- the journal
    def note(self, action, timing=None, **fields):
        """One row of the campaign's journal of working time, as Annotate
        writes it, filed under Objects."""
        return time_note(self, "objects", action, timing, **fields)

    def pop_timing(self):
        timing = getattr(self, "timing", None)
        self.timing = None
        return timing

    def box_note(self, action, rect, **fields):
        """A row about a box: where it is and how large."""
        try:
            centre = rect.center()
            fields.setdefault("x", centre.x())
            fields.setdefault("y", centre.y())
            fields.setdefault("area_m2", self.geometry.area(
                QgsGeometry.fromRect(rect)))
        except Exception:
            pass
        return time_mark(self, action, **fields)

    # ----------------------------------------------------------- the panel
    def build(self):
        follows_width(self)
        outer = QVBoxLayout(self)
        outer.setContentsMargins(8, 8, 8, 8)
        outer.setSpacing(7)

        self.current_label = QLabel("")
        self.current_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        f = self.current_label.font()
        f.setPointSize(max(f.pointSize() + 1, 11))
        f.setBold(True)
        self.current_label.setFont(f)
        self.current_label.setFixedHeight(banner_height(self.current_label))
        self.current_label.setToolTip("The class a new box is given.")

        # What the next click on the map does, under the class it will be
        # given, as in Annotate.
        self.tool_caption = OneLine()
        self.tool_caption.setObjectName("quiet")
        self.tool_caption.setAlignment(Qt.AlignmentFlag.AlignCenter)

        self.class_grid = QGridLayout()
        self.class_grid.setContentsMargins(0, 0, 0, 0)
        self.class_grid.setSpacing(4)

        self.deck = Deck()
        self.deck.after = self.reflow
        legend = QVBoxLayout()
        legend.setSpacing(4)
        legend.addWidget(self.current_label)
        legend.addWidget(self.tool_caption)
        legend.addSpacing(2)
        legend.addLayout(self.class_grid)
        self.deck.add(legend, 3)

        self.b_tool = self._tool(
            "Boxes",
            "Drag on empty ground to draw a box.\nClick one to pick it up, then "
            "drag its middle to move it\nor a corner to stretch it. Delete "
            "removes it,\nEsc puts it down, " + ctrl_name() + " and click gives it the class\n"
            "you are holding.")
        self.b_tool.clicked.connect(shielded(self.use_tool, "Boxes"))
        self.b_tool.toggled.connect(lambda *_: self.show_tool_caption())
        self.tools = QButtonGroup(self)
        self.tools.setExclusive(True)
        self.tools.addButton(self.b_tool)

        # The same words as Annotate: what leaves a mark, what mends it, and
        # Save under them. Delete last in its row, where the hand slows down.
        tools = QVBoxLayout()
        tools.setSpacing(8)
        tools.addWidget(heading("SHAPE", plain(spread([self.b_tool], gap=4))))
        tools.addWidget(heading("EDIT", plain(spread([
            self._act("Undo", "Undo the last box.", self.undo),
            self._act("Delete", "Remove the box you have picked up.",
                      self.delete_selected, danger=True)], gap=4))))
        tools.addSpacing(4)
        tools.addLayout(spread([primary(self._act(
            "Save", "Write the boxes to the package.", self.save))]))
        self.deck.add(tools, 2)

        self.settings_box = QVBoxLayout()
        self.settings_box.setSpacing(5)
        self.fold = QToolButton()
        self.fold.setText(" Settings")
        self.fold.setCheckable(True)
        self.fold.setArrowType(Qt.ArrowType.RightArrow)
        self.fold.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextBesideIcon)
        self.fold.setAutoRaise(True)
        self.fold.setObjectName("fold")
        self.fold.setFocusPolicy(Qt.FocusPolicy.TabFocus)
        self.fold.toggled.connect(self.show_settings)
        self.settings_box.addWidget(self.fold, 0, Qt.AlignmentFlag.AlignLeft)

        self.settings = follows_width(QWidget())
        inner = QVBoxLayout(self.settings)
        inner.setContentsMargins(8, 0, 0, 2)
        inner.setSpacing(5)
        self.smallest = QDoubleSpinBox()
        self.smallest.setRange(self.geometry.pixel_m[0], 100.0)
        self.smallest.setDecimals(2)
        self.smallest.setSuffix(" m")
        self.smallest.setFixedWidth(FIELD_W)
        self.smallest.setValue(round(MIN_BOX_PX * self.geometry.pixel_m[0], 2))
        self.smallest.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.smallest.setToolTip(
            "A rectangle with a side shorter than this is a misclick, not an\n"
            "object, and is thrown away instead of being written.")
        self.smallest.valueChanged.connect(self.show_smallest)
        self.smallest_px = QLabel("")
        self.smallest_px.setObjectName("quiet")
        inner.addLayout(self._field("smallest", self.smallest, self.smallest_px))

        # The same setting, with the same default, as in Annotate: boxes sat
        # in an edit buffer until somebody pressed Save, and an afternoon of
        # them could be lost to a locked package nobody was told about.
        self.autosave = QSpinBox()
        self.autosave.setRange(0, 200)
        self.autosave.setValue(AUTOSAVE)
        self.autosave.setSuffix(" boxes")
        self.autosave.setFixedWidth(FIELD_W)
        self.autosave.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.autosave.setToolTip(
            "Writes the boxes to the package by itself every so many changes.\n"
            "Zero turns it off and nothing is written until you press Save.\n\n"
            "A save, by hand or by itself, closes the undo history: Undo\n"
            "cannot take back a box that has been written.")
        inner.addLayout(self._field("autosave", self.autosave))
        self.settings.setVisible(False)
        self.settings_box.addWidget(self.settings)
        self.deck.add(self.settings_box, 2)

        # Who the boxes are filed under, always in sight: there is no box
        # for it here as there is in Annotate, only the button that opens
        # the window to change it.
        self.reading_label = QLabel("")
        self.reading_label.setWordWrap(True)
        self.reading_label.setObjectName("quiet")
        self.reading_button = QToolButton()
        self.reading_button.setText("Change")
        self.reading_button.setAutoRaise(True)
        self.reading_button.setFocusPolicy(Qt.FocusPolicy.TabFocus)
        self.reading_button.setToolTip(
            "Who is drawing, in which pass, and whether only this pass is\n"
            "shown. Every box is filed under that reading.")
        self.reading_button.clicked.connect(
            shielded(self.change_reading, "Who is drawing"))
        reading_row = QHBoxLayout()
        reading_row.setSpacing(4)
        reading_row.addWidget(self.reading_label, 1)
        reading_row.addWidget(self.reading_button, 0,
                              Qt.AlignmentFlag.AlignTop)

        self.tally = QLabel("")
        self.tally.setWordWrap(True)
        self.tally.setObjectName("quiet")
        tail = QVBoxLayout()
        tail.setSpacing(5)
        tail.addLayout(reading_row)
        tail.addWidget(self.tally)
        self.deck.add(tail, 2)

        self.deck.deal(force=True)
        outer.addWidget(self.deck)

        self.rebuild_class_buttons()
        self.show_smallest()
        self.show_tally()

    _tool = AnnotationSection.__dict__["_tool"]
    _act = AnnotationSection.__dict__["_act"]
    _field = AnnotationSection.__dict__["_field"]
    show_settings = AnnotationSection.__dict__["show_settings"]
    chip_room = AnnotationSection.__dict__["chip_room"]
    chip_columns = AnnotationSection.__dict__["chip_columns"]
    natural_columns = AnnotationSection.__dict__["natural_columns"]
    reflow = AnnotationSection.__dict__["reflow"]
    fit_names = AnnotationSection.__dict__["fit_names"]
    show_tool_caption = AnnotationSection.__dict__["show_tool_caption"]
    CAPTIONS = AnnotationSection.CAPTIONS
    resizeEvent = AnnotationSection.__dict__["resizeEvent"]
    _style = AnnotationSection.__dict__["_style"]
    settle = AnnotationSection.__dict__["settle"]
    show_current_class = AnnotationSection.__dict__["show_current_class"]
    current_colour = AnnotationSection.__dict__["current_colour"]
    current_code = AnnotationSection.__dict__["current_code"]
    rebuild_class_buttons = AnnotationSection.__dict__["rebuild_class_buttons"]
    # The chips it borrows can be renamed and added to, so the four methods
    # behind that gesture come with them. They were not lent at first and the
    # plus was built here with nothing behind it: a button that raises the
    # moment it is pressed, in a module nobody had pressed yet.
    class_by_code = AnnotationSection.__dict__["class_by_code"]
    start_rename = AnnotationSection.__dict__["start_rename"]
    cancel_rename = AnnotationSection.__dict__["cancel_rename"]
    finish_rename = AnnotationSection.__dict__["finish_rename"]
    add_class = AnnotationSection.__dict__["add_class"]
    # The filter of the readings, as Annotate applies it, on the boxes too.
    OPERATOR_BLANK = AnnotationSection.OPERATOR_BLANK
    apply_filter = AnnotationSection.__dict__["apply_filter"]
    filter_layer = AnnotationSection.__dict__["filter_layer"]
    hiding = AnnotationSection.__dict__["hiding"]
    layer = AnnotationSection.__dict__["layer"]

    @property
    def polygons(self):
        return self.layer("polygons")

    # ----------------------------------------------------------- the reading
    def held_reading(self):
        ask = getattr(self.panel, "reading", None)
        try:
            return (ask() if callable(ask) else None) or {}
        except Exception as err:
            log("cannot read the reading the panel holds: %s" % err)
            return {}

    def operator_name(self):
        return operator_word(self.panel.who_is_drawing())

    def my_reading(self):
        return (self.operator_name(), int(self.panel.which_pass()))

    @staticmethod
    def box_reading(f):
        """(operator, pass) of a box, read the way every export and Check
        read them."""
        values = []
        for name in ("operator", "pass_no"):
            try:
                values.append(f[name])
            except (KeyError, IndexError):
                values.append(None)
        return operator_word(values[0]), pass_number(values[1])

    def has_pass(self):
        layer = self.boxes
        return layer is not None and "pass_no" in layer.fields().names()

    def is_mine(self, f):
        """Whether a box belongs to the reading in hand. In a table that has
        no pass, by its operator alone."""
        who, p = self.box_reading(f)
        me, mine = self.my_reading()
        return who == me and (p == mine or not self.has_pass())

    def is_hidden(self, f):
        """Whether the filter keeps a box off the screen: the same two
        clauses apply_filter writes, operator and pass."""
        who, p = self.box_reading(f)
        me, mine = self.my_reading()
        if self.by_operator.isChecked() and who != me:
            return True
        return bool(self.hiding() and self.has_pass() and p != mine)

    def show_blind(self):
        """Who the boxes are filed under, and what is hidden from them."""
        if not self.held_reading():
            self.reading_label.setText("")
            return
        me, p = self.my_reading()
        text = "drawing as <b>%s, pass %d</b>" % (escape(me), p)
        if self.hiding():
            text += ", blind: only the boxes of this pass are shown"
        elif self.by_operator.isChecked():
            text += ": the boxes of the other operators are hidden"
        self.reading_label.setText(text)

    def change_reading(self):
        if not self.panel.change_reading():
            return
        self.select_box(None)
        if self.tool is not None:
            self.tool.show_selection()
        self.apply_filter()
        self.show_blind()
        self.show_tally()

    def not_yours(self, fid):
        """Refuse to touch a box of another reading. True when refused.

        A second reader who pressed on the first reader's box picked it up
        and moved it, or deleted it, and the first reading changed under a
        name that never touched it. The second reader draws a box of their
        own instead, over it if need be: boxes are free to overlap."""
        layer = self.boxes
        if layer is None or fid is None:
            return False
        f = layer.getFeature(fid)
        if f is None or self.is_mine(f):
            return False
        self.select_box(None)
        if self.tool is not None:
            self.tool.show_selection()
        iface.messageBar().pushMessage(
            NAME, "that box belongs to another reading and stays as it is: "
            "draw a box of your own", level=LEVEL_WARNING, duration=4)
        log("a box of another reading was left alone")
        return True

    def choose_class(self, name):
        self.class_name = name
        self.rebuild_class_buttons()
        if self.tool is not None:
            self.tool.refresh_colour()
        time_mark(self, "class", class_code=self.current_code())

    def show_smallest(self, *args):
        px = self.geometry.pixel_m[0]
        self.smallest_px.setText("%d px" % (int(round(self.smallest.value() / px))
                                            if px else 0))

    def show_tally(self):
        boxes = [f for f in self.all_boxes() if not self.is_hidden(f)]
        if not boxes:
            self.tally.setText("no box yet: drag on the image to draw one")
            return
        counts = {}
        for f in boxes:
            counts[f["class_name"]] = counts.get(f["class_name"], 0) + 1
        rows = ["<table cellspacing=3><tr><td><b>%d boxes</b></td><td></td></tr>"
                % len(boxes)]
        for c in self.campaign.active_classes():
            n = counts.get(c["name"], 0)
            if n:
                rows.append("<tr><td><span style='color:%s'>&#9632;</span> %s</td>"
                            "<td align=right>%d</td></tr>" % (c["colour"], c["name"], n))
        rows.append("</table>")
        self.tally.setText("".join(rows))

    # ----------------------------------------------------------- the layer
    @property
    def boxes(self):
        return find_mine(self.campaign.data["id"], "boxes")

    def all_boxes(self):
        layer = self.boxes
        return [] if layer is None else list(layer.getFeatures())

    def box_at(self, point):
        """The smallest box under the cursor, so a box inside another one can
        still be picked up."""
        layer = self.boxes
        if layer is None:
            return None
        p = QgsGeometry.fromPointXY(point)
        hits = [f for f in layer.getFeatures()
                if f.hasGeometry() and f.geometry().intersects(p)]
        if not hits:
            return None
        # Only the boxes of the reading in hand can be picked up. A press on
        # another reading's box draws a new one, which is what a second
        # reader has to do: their reading of that object, not a move of the
        # first one's. Said when the other box is in sight; a hidden one
        # stays as unseen as it is.
        mine = [f for f in hits if self.is_mine(f)]
        if mine:
            return min(mine, key=lambda f: f.geometry().boundingBox().area())
        seen = [f for f in hits if not self.is_hidden(f)]
        if seen:
            who, p_no = self.box_reading(seen[0])
            iface.messageBar().pushMessage(
                NAME, "that box is %s's, pass %d: another reading, which "
                "stays as it is. Drag to draw your own." % (who, p_no),
                level=LEVEL_INFO, duration=4)
        return None

    def select_box(self, fid):
        self.selected = fid
        layer = self.boxes
        if layer is not None:
            layer.removeSelection()
            if fid is not None:
                layer.select(fid)

    def selected_rect(self):
        layer = self.boxes
        if layer is None or self.selected is None:
            return None
        f = layer.getFeature(self.selected)
        if f is None or not f.hasGeometry():
            return None
        return f.geometry().boundingBox()

    def tile_holding(self, rect):
        """Which tile a box belongs to, decided by its middle, so a box that
        sticks out of a tile still belongs to the tile it was drawn in."""
        if not self.tiled:
            return ""
        tiles = find_mine(self.campaign.data["id"], "tiles")
        if tiles is None:
            return ""
        middle = QgsGeometry.fromPointXY(
            QgsPointXY(rect.center().x(), rect.center().y()))
        for f in tiles.getFeatures():
            if f.hasGeometry() and f.geometry().intersects(middle):
                return str(f["tile_id"])
        return ""

    # ----------------------------------------------------------- editing
    def too_small(self, rect):
        side = self.smallest.value()
        wide = self.geometry.measure.measureLine(
            QgsPointXY(rect.xMinimum(), rect.yMinimum()),
            QgsPointXY(rect.xMaximum(), rect.yMinimum()))
        tall = self.geometry.measure.measureLine(
            QgsPointXY(rect.xMinimum(), rect.yMinimum()),
            QgsPointXY(rect.xMinimum(), rect.yMaximum()))
        # A failed measurement must not delete. It fails as zero, and as NaN
        # or infinity, which a plain "<= 0" would let through: a box measured
        # NaN would never be too small and would be stored with no width and
        # no height.
        if not (0 < wide < float("inf") and 0 < tall < float("inf")):
            wide = rect.width() / max(self.geometry.pixel_crs[0], 1e-12) \
                * self.geometry.pixel_m[0]
            tall = rect.height() / max(self.geometry.pixel_crs[1], 1e-12) \
                * self.geometry.pixel_m[1]
        return wide < side or tall < side, wide, tall

    def create_box(self, rect):
        layer = self.boxes
        if layer is None or self.class_name is None:
            return
        small, wide, tall = self.too_small(rect)
        if small:
            iface.messageBar().pushMessage(
                NAME, "%.2f by %.2f m: smaller than the %.2f m you asked for"
                % (wide, tall, self.smallest.value()), level=LEVEL_INFO, duration=3)
            return
        if not layer.isEditable():
            layer.startEditing()
        layer.beginEditCommand("box %s" % self.class_name)
        f = QgsFeature(layer.fields())
        f.setGeometry(QgsGeometry.fromRect(rect))
        f["class_name"] = self.class_name
        f["class_code"] = self.current_code()
        f["tile_id"] = self.tile_holding(rect)
        f["operator"] = self.panel.who_is_drawing()
        if "pass_no" in layer.fields().names():
            f["pass_no"] = self.panel.which_pass()
        f["width_m"] = round(wide, 3)
        f["height_m"] = round(tall, 3)
        f["created"] = now()
        layer.addFeature(f)
        layer.endEditCommand()
        layer.triggerRepaint()
        self.show_tally()
        self.keep_safe()
        log("box %s, %.2f by %.2f m" % (self.class_name, wide, tall))
        self.box_note("box", rect, class_code=self.current_code(),
                      tile_id=f["tile_id"] or "")
        self.ticked()

    def keep_safe(self):
        """Write the boxes that are not saved into the recovery net.

        Boxes live in an edit buffer like the polygons, and a crash loses the
        buffer. The net is brought up to date at every edit: when a box is
        drawn, stretched, given another class or deleted, when the last edit
        is undone and when the boxes are saved. Otherwise after a crash those
        edits would come back as they had been at the last stroke, without a
        word. Undoing the last edit leaves the buffer as it was before it,
        and a buffer with nothing pending removes the file."""
        try:
            self.panel.keep_safe()
        except Exception as err:
            log("the recovery snapshot was not brought up to date: %s" % err)

    def reshape_box(self, rect):
        layer = self.boxes
        if layer is None or self.selected is None:
            return
        if self.not_yours(self.selected):
            return
        small, wide, tall = self.too_small(rect)
        if small:
            iface.messageBar().pushMessage(
                NAME, "a box cannot be smaller than %.2f m" % self.smallest.value(),
                level=LEVEL_WARNING, duration=3)
            return
        if not layer.isEditable():
            layer.startEditing()
        layer.beginEditCommand("reshape box")
        layer.changeGeometry(self.selected, QgsGeometry.fromRect(rect))
        fields = layer.fields()
        for name, value in (("width_m", round(wide, 3)),
                            ("height_m", round(tall, 3)),
                            ("tile_id", self.tile_holding(rect))):
            index = fields.indexOf(name)
            if index >= 0:
                layer.changeAttributeValue(self.selected, index, value)
        layer.endEditCommand()
        layer.triggerRepaint()
        self.keep_safe()
        self.box_note("box_reshape", rect, tile_id=self.tile_holding(rect))
        self.ticked()

    def assign_class_at(self, point):
        hit = self.box_at(point)
        if hit is None or self.class_name is None:
            return
        if self.not_yours(hit.id()):
            return
        layer = self.boxes
        if not layer.isEditable():
            layer.startEditing()
        layer.beginEditCommand("reclass box")
        fields = layer.fields()
        for name, value in (("class_name", self.class_name),
                            ("class_code", self.current_code())):
            index = fields.indexOf(name)
            if index >= 0:
                layer.changeAttributeValue(hit.id(), index, value)
        layer.endEditCommand()
        layer.triggerRepaint()
        self.select_box(hit.id())
        self.show_tally()
        self.keep_safe()
        self.box_note("box_reclass", hit.geometry().boundingBox(),
                      class_code=self.current_code(),
                      from_code=hit["class_code"], tile_id=hit["tile_id"])
        self.ticked()

    def delete_selected(self):
        layer = self.boxes
        if layer is None or self.selected is None:
            iface.messageBar().pushMessage(
                NAME, "click a box first, then Delete", level=LEVEL_INFO, duration=2)
            return
        if self.not_yours(self.selected):
            return
        if not layer.isEditable():
            layer.startEditing()
        gone = layer.getFeature(self.selected)
        layer.beginEditCommand("delete box")
        layer.deleteFeature(self.selected)
        layer.endEditCommand()
        layer.triggerRepaint()
        self.select_box(None)
        if self.tool is not None:
            self.tool.show_selection()
        self.show_tally()
        self.keep_safe()
        try:
            self.box_note("box_delete", gone.geometry().boundingBox(),
                          from_code=gone["class_code"],
                          tile_id=gone["tile_id"])
        except Exception:
            self.box_note("box_delete", None)
        self.ticked()

    def undo(self):
        layer = self.boxes
        if layer is not None and layer.isEditable() and layer.undoStack().canUndo():
            layer.undoStack().undo()
            layer.triggerRepaint()
            self.select_box(None)
            if self.tool is not None:
                self.tool.show_selection()
            self.show_tally()
            self.keep_safe()
            time_mark(self, "undo", tool="key")

    def ticked(self):
        """One more change to the boxes. The net has been written already;
        this decides whether the package is written too, every so many
        changes, as Annotate does."""
        self.since_save += 1
        every = self.autosave.value()
        if every and self.since_save >= every:
            # Zeroed by a save that worked, not here: a refused one is tried
            # again at the next change.
            self.save(quiet=True)

    def save(self, quiet=False):
        """Write the boxes down, and say how it went: in the message bar, as
        Annotate does. Saying nothing, in the log only, would let a package
        that refused the boxes be found out when the work was already gone
        from the screen."""
        layer = self.boxes
        if layer is None:
            return
        written = 0
        if layer.isEditable():
            picked = self.selected_identity()
            if not layer.commitChanges():
                errors = layer.commitErrors()
                log("cannot save the boxes: %s" % errors)
                iface.messageBar().pushMessage(
                    NAME, "not everything could be saved. boxes: %s"
                    % "; ".join(errors[:3]), level=LEVEL_CRITICAL, duration=9)
                self.keep_safe()
                return
            written = 1
            self.reselect(picked)
        self.since_save = 0
        if quiet:
            log("boxes saved by itself")
        else:
            log("boxes saved")
            iface.messageBar().pushMessage(
                NAME, "saved, %d layer%s written"
                % (written, "" if written == 1 else "s"),
                level=LEVEL_INFO, duration=2)
        self.keep_safe()
        self.show_tally()
        time_mark(self, "save", tool="" if quiet else "button",
                  note="by itself" if quiet else "")

    def selected_identity(self):
        """What it takes to find the selected box again after a save: a box
        not yet saved has a temporary id, and the save gives it a new one."""
        layer = self.boxes
        if layer is None or self.selected is None or self.selected >= 0:
            return None
        f = layer.getFeature(self.selected)
        if f is None or not f.hasGeometry():
            return None
        return self.selected, f.geometry().asWkt(), f["created"]

    def reselect(self, picked):
        """Pick the box up again under the id the save gave it. If it cannot
        be told apart, nothing stays selected, which is better than a
        selection that points at nothing and a Delete that does nothing."""
        if picked is None:
            return
        old, wkt, created = picked
        found = None
        layer = self.boxes
        if layer is not None:
            for f in layer.getFeatures():
                if f.hasGeometry() and f["created"] == created \
                        and f.geometry().asWkt() == wkt:
                    found = f.id()
                    break
        self.select_box(found)
        if self.tool is not None:
            self.tool.show_selection()

    def unsaved(self):
        layer = self.boxes
        return layer is not None and layer.isEditable() and layer.isModified()

    # ----------------------------------------------------------- the tool
    def use_tool(self):
        if self.tool is None:
            self.tool = BoxTool(canvas(), self)
        self.b_tool.setChecked(True)
        self.tool.refresh_colour()
        canvas().setMapTool(self.tool)
        log("boxes: drag to draw, click to pick up, corners to stretch, "
            "Delete to remove, %s and click to change the class." % ctrl_name())

    def release_tools(self):
        time_close(self, "objects")
        hand_back_tool(getattr(self, "_tool_before", None), (self.tool,))
        layer = self.boxes
        if layer is not None:
            layer.removeSelection()

# ---------------------------------------------------------------------
# ---- export ----------------------------------------------------------
# ---------------------------------------------------------------------

# The formats that write a coordinate as decimal text through GDAL's own
# number formatter, the one that writes WKT. Left to itself it writes fifteen
# significant digits, about ten nanometres on a longitude, and a polygon cut
# against its neighbours can hold two vertices a thousandth of that apart:
# valid in the GeoPackage, where a double is kept as it is, and a ring that
# touches itself, or crosses itself, once both are written as the same
# fifteen digits. That is what turned two polygons of a real campaign invalid
# in its KML and its CSV, while the GeoPackage, the shapefile and the
# GeoJSON, which keep the double itself or seventeen digits, stayed valid. The
# same rounding made eight pairs of neighbours overlap there, by slivers ten
# nanometres wide.
TEXT_DRIVERS = ("CSV", "KML")

# Seventeen digits give back every double exactly, and only without
# rounding: GDAL's rounding trims 0.30000000000000004 to 0.3, which is
# another number. Recent GDAL reads both options every time it writes; GDAL
# 3.8, the one in QGIS 3.36, reads them once, the first time anything in the
# process writes WKT, and in QGIS that has happened by the time a campaign is
# open. So the options are set, then asked whether they work, and when they
# do not the coordinates GDAL wrote are written again, exactly.
FULL_PRECISION = {"OGR_WKT_PRECISION": "17", "OGR_WKT_ROUND": "NO"}

# The formats whose file is written whole, and that GDAL cannot write over.
# CSV and GeoJSON hold one table a file; the KML holds them all, in one go.
# Over an old KML, GDAL hands the file to its other KML driver, LIBKML,
# which can open it for update: the export would come out in another layout,
# every coordinate with an altitude of 0 and fifteen digits, whatever was asked.
WRITTEN_WHOLE = ("CSV", "GeoJSON", "KML")

NUMBER = re.compile(r"[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?")
# The WKT is the first column of every row GDAL writes, so it is looked for
# only at the start of a line: a note that quotes a polygon is text, and
# inside a quoted field a quote is always doubled, so no line of a note can
# start the way a row does.
GEOMETRY_TEXT = re.compile(
    r'^"((?:MULTI)?(?:POINT|LINESTRING|POLYGON)[ ZM]*\([^"]*\))"', re.M)
COORDINATES = re.compile(r"(<coordinates>)([^<]*)(</coordinates>)")


class full_precision:
    """FULL_PRECISION for the length of a with, on this thread only, and
    whatever was set before put back afterwards. Thread-local because QGIS
    draws the map on other threads, through the same GDAL."""

    def __enter__(self):
        local = hasattr(gdal, "SetThreadLocalConfigOption")
        self.get = gdal.GetThreadLocalConfigOption if local \
            else gdal.GetConfigOption
        self.set = gdal.SetThreadLocalConfigOption if local \
            else gdal.SetConfigOption
        self.before = {k: self.get(k, None) for k in FULL_PRECISION}
        for k, v in FULL_PRECISION.items():
            self.set(k, v)
        return self

    def __exit__(self, *exc):
        for k, v in self.before.items():
            self.set(k, v)
        return False


def coordinates_exact():
    """Whether GDAL, here and now, writes a coordinate as text that reads back
    as the very same double. Asked with full_precision in force, of the same
    formatter the CSV and KML writers use."""
    x, y = 0.1 + 0.2, 1.0 / 3.0
    try:
        point = ogr.Geometry(ogr.wkbPoint)
        point.AddPoint_2D(x, y)
        back = ogr.CreateGeometryFromWkt(point.ExportToWkt())
        return back.GetX() == x and back.GetY() == y
    except Exception:
        return False


def runs_of(geom):
    """The coordinates of a geometry, one run of numbers per ring, line or
    point, in the order a writer goes through them: x, y and z, if it has
    one, of every vertex."""
    if geom is None or geom.IsEmpty():
        return []
    if geom.GetGeometryCount():
        out = []
        for i in range(geom.GetGeometryCount()):
            out.extend(runs_of(geom.GetGeometryRef(i)))
        return out
    three = geom.GetCoordinateDimension() == 3
    run = []
    for i in range(geom.GetPointCount()):
        p = geom.GetPoint(i)
        run.extend(p[:3] if three else p[:2])
    return [run]


def exact_text(value):
    """A double as the shortest text that reads back as the very same
    double, and in plain decimals: repr writes a longitude a hair east of
    Greenwich as 1e-05, and a KML reader is not obliged to read that."""
    text = repr(float(value))
    if ("e" in text or "E" in text) and "n" not in text:
        text = format(Decimal(text), "f")
    return text


def renumbered(text, values):
    """text with its numbers replaced by values, written exactly: Python's
    repr of a float is the shortest text that reads back as the same double.
    None when the two do not match one for one, or a number written is not
    the value it stands for, rounded: then this is not the text it was
    taken to be, and it is left alone."""
    found = NUMBER.findall(text)
    if len(found) != len(values):
        return None
    for old, new in zip(found, values):
        if abs(float(old) - new) > 1e-9 * max(1.0, abs(new)):
            return None
    it = iter(values)
    return NUMBER.sub(lambda m: exact_text(next(it)), text)


def rewrite_coordinates(target, staged, tables, driver):
    """Write again, exactly, every coordinate GDAL wrote as text in target,
    from the geometries of staged it wrote them from: the same tables, the
    same features, in the same order. True if the file was rewritten.

    Only the numbers inside a geometry change: the WKT column of a CSV, the
    <coordinates> of a KML. Anything that does not line up, a feature skipped
    or a number that is not the one expected, leaves the file as GDAL wrote
    it, and the reading back after it says what that costs."""
    source = ogr.Open(long_path(staged))
    if source is None:
        return False
    runs = []
    for table in tables:
        layer = source.GetLayerByName(table)
        if layer is None:
            continue
        layer.ResetReading()
        for f in layer:
            g = f.GetGeometryRef()
            if g is None or g.IsEmpty():
                continue
            if driver == "CSV":
                # one WKT per feature: all its runs in one
                runs.append([v for run in runs_of(g) for v in run])
            else:
                runs.extend(runs_of(g))
    layer = source = None
    try:
        with open(long_path(target), "rb") as f:
            text = f.read().decode("latin-1")
    except OSError as err:
        log("cannot read %s back: %s" % (os.path.basename(target), err))
        return False
    pattern = GEOMETRY_TEXT if driver == "CSV" else COORDINATES
    pieces, at, n = [], 0, 0
    for m in pattern.finditer(text):
        if n >= len(runs):
            return False
        body = m.group(1) if driver == "CSV" else m.group(2)
        start = m.start(1) if driver == "CSV" else m.start(2)
        new = renumbered(body, runs[n])
        if new is None:
            return False
        pieces.append(text[at:start])
        pieces.append(new)
        at = start + len(body)
        n += 1
    if n != len(runs):
        return False
    pieces.append(text[at:])
    with open(long_path(target), "wb") as f:
        f.write("".join(pieces).encode("latin-1"))
    return True


def invalid_polygons(path, where=None):
    """How many polygons each table of a file holds that are not valid."""
    found = {}
    try:
        ds = ogr.Open(long_path(path))
        if ds is None:
            return found
        for i in range(ds.GetLayerCount()):
            layer = ds.GetLayerByIndex(i)
            if where:
                layer.SetAttributeFilter(where)
            bad = 0
            for f in layer:
                g = f.GetGeometryRef()
                if g is not None and ogr.GT_Flatten(g.GetGeometryType()) in (
                        ogr.wkbPolygon, ogr.wkbMultiPolygon) \
                        and not g.IsValid():
                    bad += 1
            found[layer.GetName()] = bad
        layer = ds = None
    except Exception as err:
        log("cannot read %s back: %s" % (os.path.basename(path), err))
    return found


def tables_have_system(source, tables):
    """Whether the tables of a package are in a coordinate system that can be
    turned into longitude and latitude.

    Not when a table has none, or only the stand-in a GeoPackage gives a table
    with no system: the GDAL of QGIS 3.36 reads that stand-in back as a
    geographic system, so asking only whether there is one said yes there."""
    try:
        ds = ogr.Open(source)
        if ds is None:
            return True
        for table in tables:
            layer = ds.GetLayerByName(table)
            if layer is None:
                continue
            srs = layer.GetSpatialRef()
            if srs is None or srs.IsLocal() \
                    or (srs.GetName() or "").strip() in PLACEHOLDER_SRS:
                return False
        layer = ds = None
    except Exception as err:
        log("cannot read the system of the tables: %s" % err)
    return True


def feature_counts(path, where=None):
    """How many features with a geometry each table of a file holds, by name,
    or None when the file cannot be read back.

    With a geometry, because a feature GDAL could not reproject is written
    all the same, with its geometry left out: counting rows, a table whose
    every shape was lost looked whole."""
    found = {}
    try:
        ds = ogr.Open(long_path(path))
        if ds is None:
            return None
        for i in range(ds.GetLayerCount()):
            layer = ds.GetLayerByIndex(i)
            if where:
                layer.SetAttributeFilter(where)
            n = 0
            for f in layer:
                g = f.GetGeometryRef()
                if g is not None and not g.IsEmpty():
                    n += 1
            found[layer.GetName()] = n
        layer = ds = None
    except Exception as err:
        log("cannot count what %s holds: %s" % (os.path.basename(path), err))
        return None
    return found


def defuse_csv(path):
    """The CSV GDAL wrote, with every text cell a spreadsheet would run as a
    formula given the quote csv_text puts in front of it. The class names are
    what a person typed, and a file that opens in Excel is read by the cell.

    The file is read row by row, never whole: an export of a large campaign
    is hundreds of megabytes of geometry. It is left exactly as GDAL wrote it
    when nothing needs changing, which is nearly always, and that is found
    out by reading it once; only otherwise is it written again, row by row,
    through a temporary file. Returns the number of cells changed. Given a
    folder, which is what GDAL makes of several tables in one CSV file, it
    does each .csv in it."""
    if os.path.isdir(long_path(path)):
        return sum(defuse_csv(os.path.join(path, n))
                   for n in sorted(os.listdir(long_path(path)))
                   if n.lower().endswith(".csv"))
    # The geometry of a large polygon as text is longer than the 128 KB a cell
    # may have for the csv module, and a file it stops in would go unchecked.
    old_limit = csv.field_size_limit(2 ** 31 - 1)
    try:
        with io.open(long_path(path), encoding="utf-8", newline="") as fh:
            ending = "\r\n" if fh.readline().endswith("\r\n") else "\n"
            fh.seek(0)
            if not any(csv_text(c) != c for row in csv.reader(fh)
                       for c in row):
                return 0
    except (OSError, csv.Error, UnicodeDecodeError, MemoryError) as err:
        log("cannot check %s for formulas: %s" % (os.path.basename(path), err))
        return 0
    finally:
        csv.field_size_limit(old_limit)
    changed = 0
    spare = path + ".tmp"
    csv.field_size_limit(2 ** 31 - 1)
    try:
        with io.open(long_path(path), encoding="utf-8", newline="") as src:
            with io.open(long_path(spare), "w", encoding="utf-8",
                         newline="") as out:
                writer = csv.writer(out, lineterminator=ending)
                for row in csv.reader(src):
                    for i, cell in enumerate(row):
                        safe = csv_text(cell)
                        if safe != cell:
                            row[i] = safe
                            changed += 1
                    writer.writerow(row)
        os.replace(long_path(spare), long_path(path))
    except (OSError, csv.Error, UnicodeDecodeError, MemoryError) as err:
        log("cannot write %s without its formulas: %s"
            % (os.path.basename(path), err), loud=True)
        try:
            os.remove(long_path(spare))
        except OSError:
            pass
        return 0
    finally:
        csv.field_size_limit(old_limit)
    return changed


def remove_output(target, fmt):
    """Take away a file this export wrote, and the files that go with it."""
    try:
        if fmt != "KML":
            ogr.GetDriverByName(fmt).DeleteDataSource(long_path(target))
    except Exception:
        pass
    sides = (".csvt", ".prj") if fmt == "CSV" else ()
    for path in [target] + [os.path.splitext(target)[0] + s for s in sides]:
        try:
            if os.path.exists(long_path(path)):
                os.remove(long_path(path))
        except OSError as err:
            log("cannot remove %s: %s" % (os.path.basename(path), err))


def write_vectors(source, recipe, stem):
    """Copy the chosen tables out of the package, in the chosen shape.

    gdal does the conversion, which means the field types, the projection and
    the geometry survive the trip instead of being rebuilt by hand and getting
    it subtly wrong. What is decided here is only what to ask it for.

    Three lists come back: the files written, the tables that could not be,
    and what is worth saying about the files that were."""
    choice = recipe.get("reading") or {}
    if choice.get("mode", "all") != "all":
        return write_reading(source, recipe, stem)
    # One set of files per operator: only meaningful for every reading
    # together, which is what the window offers it for.
    if recipe.get("arrange") == "operator" and choice.get("readings"):
        return write_per_operator(source, recipe, stem)
    folder = recipe["folder"]
    os.makedirs(long_path(folder), exist_ok=True)
    driver = recipe["driver"]
    tables = list(recipe["tables"])
    written, failed, notes = [], [], []

    # gdal is asked for a table that is not in the package and answers with a
    # complaint on the console and a perfectly valid empty file, which is the
    # worst of both: nothing said wrong, nothing written. So the package is
    # read first and a table that is not in it is called a failure here.
    try:
        probe = ogr.Open(source)
        present = set()
        if probe is not None:
            for i in range(probe.GetLayerCount()):
                present.add(probe.GetLayerByIndex(i).GetName())
        probe = None
    except Exception as err:
        log("cannot read the package: %s" % err)
        present = set()
    if present:
        failed = [t for t in tables if t not in present]
        tables = [t for t in tables if t in present]
    if not tables:
        return [], failed, notes

    # A campaign with no coordinate system, a picture or a world file without
    # one, has its coordinates in pixels or in units nobody named, and nothing
    # can turn those into degrees. Handed to GDAL to reproject all the same,
    # GeoJSON and KML come out with no feature at all and are said written,
    # or, with the GDAL of QGIS 3.36, with pixels labelled as degrees. The
    # manifest says whether there is a system (recipe "system"); the tables are
    # asked as well. Without one the coordinates go out as they were drawn,
    # and KML, which holds degrees and nothing else, is refused.
    system = bool(recipe.get("system", True)) \
        and tables_have_system(source, tables)
    if not system and driver == "KML":
        notes.append("KML holds longitude and latitude only, and this "
                     "campaign has no coordinate system: nothing was written. "
                     "GeoPackage, Shapefile, GeoJSON or CSV write the "
                     "coordinates as they were drawn.")
        for note in notes:
            log(note, loud=True)
        return [], failed + tables, notes
    crs = recipe["crs"] if system else None
    # said whenever degrees were asked for, and for GeoJSON always: whoever
    # opens a GeoJSON reads its coordinates as longitude and latitude
    if not system and (recipe["crs"] or driver == "GeoJSON"):
        notes.append("the campaign has no coordinate system: the coordinates "
                     "are written as they were drawn, in pixels or in the "
                     "units of its world file, not in longitude and latitude")

    where = None
    if recipe["tile_id"]:
        # Every table carries the frame it belongs to, the frames included:
        # a frame's own tile_id is its name. So one clause narrows all four
        # down to the same piece of ground.
        # The name is quoted as SQLite quotes it, apostrophes doubled,
        # because a frame renamed by hand in the GeoPackage can carry one,
        # and an unquoted apostrophe breaks the clause and with it the
        # export. Not sql_text(): that is QGIS's quoting, where a
        # backslash escapes, and SQLite's has no such thing.
        where = "\"tile_id\" = '%s'" % (
            str(recipe["tile_id"]).replace("'", "''"))

    def options(layers, fmt, select):
        # Overwrite, because the names are fixed: <campaign>_<table>. Without
        # it, exporting a second time into the same folder would fail on the
        # file the first export wrote, and the window would blame the format.
        kwargs = {"format": fmt, "layers": list(layers),
                  "skipFailures": True, "accessMode": "overwrite"}
        if not system:
            # No system written either. The GDAL of QGIS 3.36 takes the
            # GeoPackage's stand-in for none for a geographic system, and a
            # shapefile would come out with a .prj saying its pixels were degrees.
            kwargs["dstSRS"] = "NULL"
            kwargs["reproject"] = False
        if select:
            if crs:
                kwargs["dstSRS"] = crs
                kwargs["reproject"] = True
            if where:
                kwargs["where"] = where
        if fmt == "CSV":
            kwargs["layerCreationOptions"] = ["GEOMETRY=AS_WKT",
                                              "CREATE_CSVT=YES"]
        elif fmt == "ESRI Shapefile":
            # The table of a shapefile is written in Latin-1 unless told
            # otherwise, and a class named in Chinese, Greek or Cyrillic came
            # out as question marks. UTF-8 also writes the .cpg that says so.
            kwargs["layerCreationOptions"] = ["ENCODING=UTF-8"]
        return gdal.VectorTranslateOptions(**kwargs)

    def translate(target, origin, opts, fmt):
        release_file(target)
        # Every call that reaches a file here goes through long_path: past
        # 260 characters SQLite cannot open the path as it is, and a
        # GeoPackage near that length was said to be a failure of the format.
        # The name that is logged and handed back stays the plain one.
        if fmt in WRITTEN_WHOLE and os.path.exists(long_path(target)):
            # Overwrite is not enough for these: GDAL opens the old file,
            # cannot take its one table out of it, says so on the console
            # and hands back the file as it was, which read as a success, or,
            # for a KML, rewrites it through LIBKML (see WRITTEN_WHOLE).
            # Exporting again into the same folder left the first export in
            # place, and the window said it had written it.
            try:
                if fmt != "KML":
                    ogr.GetDriverByName(fmt).DeleteDataSource(
                        long_path(target))
                if os.path.exists(long_path(target)):
                    os.remove(long_path(target))
            except Exception as err:
                log("cannot replace %s: %s" % (os.path.basename(target), err))
                return False
            for side in (".csvt", ".prj") if fmt == "CSV" else ():
                old = long_path(os.path.splitext(target)[0] + side)
                if os.path.exists(old):
                    os.remove(old)
        try:
            out = gdal.VectorTranslate(long_path(target), origin,
                                       options=opts)
        except Exception as err:
            log("cannot write %s: %s" % (os.path.basename(target), err))
            return False
        ok = out is not None
        out = None
        return ok

    with full_precision():
        rewrite = driver in TEXT_DRIVERS and not coordinates_exact()
        # When the digits cannot be asked for, the tables are first copied
        # as they will be written, reprojected and narrowed to the frame,
        # into a GeoPackage of their own, which keeps every double as it is;
        # the file is written from that, and its coordinates are then written
        # again from it, exactly.
        origin, stage = source, None
        if rewrite:
            log("this GDAL (%s) writes coordinates as text with fifteen "
                "digits; the %s is given them back in full"
                % (gdal.__version__, driver))
            stage = tempfile.mkdtemp(prefix="rasterlabel_export_")
            origin = os.path.join(stage, "as_written.gpkg")
            if not translate(origin, source, options(tables, "GPKG", True),
                             "GPKG"):
                shutil.rmtree(stage, ignore_errors=True)
                return [], failed + tables, notes
        try:
            if recipe["one_file"]:
                jobs = [(os.path.join(folder, stem + recipe["extension"]),
                         tables)]
            else:
                jobs = [(os.path.join(folder, "%s_%s%s" % (
                    stem, table, recipe["extension"])), [table])
                    for table in tables]
            for target, layers in jobs:
                if not translate(target, origin,
                                 options(layers, driver, stage is None),
                                 driver):
                    failed += layers
                    continue
                written.append((target, layers))
                if rewrite and not rewrite_coordinates(target, origin,
                                                       layers, driver):
                    log("the coordinates of %s are left as GDAL wrote them, "
                        "with fifteen digits" % os.path.basename(target))
                if driver == "CSV":
                    defuse_csv(target)
        finally:
            if stage is not None:
                shutil.rmtree(stage, ignore_errors=True)

    # Read back, every format, how many features of each table came out with
    # their geometry. GDAL is told to skip what it cannot write rather than
    # stop, and what it skips would be nowhere to be seen: a feature it cannot
    # reproject comes out with no geometry, a table it cannot reproject at
    # all comes out empty, and either file would be said written. A table that lost
    # shapes is said; a file that holds none of what it was asked for is taken
    # away and called a failure.
    wanted = feature_counts(source, where) or {}
    for target, layers in list(written):
        got = feature_counts(target)
        if got is None:
            continue
        asked = [t for t in layers if wanted.get(t)]
        empty = []
        for table in asked:
            have = got.get(table, 0) if len(layers) > 1 \
                else sum(got.values())
            if have >= wanted[table]:
                continue
            notes.append("%s: %d of the %d features of %s came out with "
                         "their geometry"
                         % (os.path.basename(target), have, wanted[table],
                            table))
            if have == 0:
                empty.append(table)
        if asked and len(empty) == len(asked):
            remove_output(target, driver)
            written.remove((target, layers))
            failed += layers
            notes.append("%s held nothing and was taken away"
                         % os.path.basename(target))
        else:
            failed += empty

    # Read back, every format: a polygon valid in the package and not in the
    # file is said, table by table, and not left to be found in another
    # program. One that was already invalid in the package is no news.
    before = invalid_polygons(source, where)
    for target, layers in written:
        after = invalid_polygons(target)
        for name, bad in sorted(after.items()):
            table = layers[0] if len(layers) == 1 else name
            more = bad - before.get(table, 0)
            if more > 0:
                notes.append("%s: %d polygon%s of %s came out invalid"
                             % (os.path.basename(target), more,
                                "" if more == 1 else "s", table))
    for note in notes:
        log(note, loud=True)
    return [t for t, _ in written], failed, notes


def write_per_operator(source, recipe, stem):
    """write_vectors once for each operator, every pass of that operator in
    the same files, the operator in their names: <stem>_<OPERATOR>_<table>.

    Each set is written the way a single reading is (write_reading), so the
    pass stays an attribute of every mark and every check on the way out is
    the one the other exports have. The three lists come back joined."""
    written, failed, notes = [], [], []
    for one in operator_sets(recipe["reading"]["readings"]):
        choice = {"mode": "one", "readings": one["readings"],
                  "tag": one["tag"], "label": one["operator"]}
        w, f, n = write_reading(source, dict(recipe, arrange=None,
                                             reading=choice),
                                "%s_%s" % (stem, one["tag"]))
        written += w
        failed += [t for t in f if t not in failed]
        notes += n
    return written, failed, notes


# What a format writes beside its main file, which belongs to the export as
# much as the file does: the type and projection files of a CSV, the parts of
# a shapefile.
SIDECARS = (".csvt", ".prj", ".cpg", ".dbf", ".shx")


def pack_zip(folder, files, name):
    """Every file an export wrote, and what goes beside each, in one .zip in
    the folder. Returns (its path, how many files it holds).

    The names inside are relative to the folder, with forward slashes, so the
    archive says nothing of where it was made. Written under a temporary name
    and renamed when whole: a crash or a full disk leaves the old archive as
    it was, or none, never half of one. Raises OSError, with the temporary
    file taken away."""
    members = {}
    for path in files:
        base = os.path.splitext(path)[0]
        for each in [path] + [base + s for s in SIDECARS]:
            if os.path.isfile(long_path(each)):
                arc = os.path.relpath(each, folder).replace(os.sep, "/")
                if not arc.startswith(".."):
                    members[arc] = each
    target = os.path.join(folder, name)
    tmp = target + ".tmp"
    try:
        with open(long_path(tmp), "wb") as raw:
            with zipfile.ZipFile(raw, "w", zipfile.ZIP_DEFLATED) as pack:
                for arc in sorted(members):
                    pack.write(long_path(members[arc]), arc)
            raw.flush()
            os.fsync(raw.fileno())
        os.replace(long_path(tmp), long_path(target))
    except Exception as err:
        try:
            if os.path.exists(long_path(tmp)):
                os.remove(long_path(tmp))
        except OSError:
            pass
        raise OSError("the archive could not be written: %s" % err)
    return target, len(members)


def write_reading(source, recipe, stem):
    """write_vectors for one reading, or for a consensus.

    The tables are first copied into a GeoPackage of their own holding only
    what goes out: the reading chosen, narrowed to the frame when one was
    asked for, with the polygons replaced by their consensus when that was
    asked for. That copy is then written out the way the whole package
    always is, so every format, every digit and every check on the way out
    is the same for a reading as for the campaign."""
    stage = tempfile.mkdtemp(prefix="rasterlabel_reading_")
    try:
        staged = os.path.join(stage, "reading.gpkg")
        try:
            narrowed_package(source, staged, recipe["tables"],
                             recipe.get("tile_id"), recipe["reading"])
        except Exception as err:
            log("cannot narrow the package to %s: %s"
                % (recipe["reading"].get("label", "the reading"), err),
                loud=True)
            return [], list(recipe["tables"]), []
        return write_vectors(staged, dict(recipe, reading=None, tile_id=None),
                             stem)
    finally:
        shutil.rmtree(stage, ignore_errors=True)


def narrowed_package(source, target, tables, tile_id, choice):
    """A GeoPackage of the chosen tables holding only the chosen readings.

    A mark is in a reading by its operator and its pass, read through the
    same operator_word and pass_number as everywhere else, so "Massi" with no
    pass and "MASSI" in pass 1 are one reading here too. The frames belong
    to nobody and go out whole; the tile filter applies to them as it
    always did."""
    mode = choice.get("mode", "all")
    keep = {tuple(r) for r in choice.get("readings") or []}
    src = ogr.Open(source)
    if src is None:
        raise IOError("cannot read %s" % os.path.basename(source))
    out = ogr.GetDriverByName("GPKG").CreateDataSource(target)
    if out is None:
        raise IOError("cannot make a working copy for the reading")
    try:
        for table in tables:
            lyr = src.GetLayerByName(table)
            if lyr is None:
                continue
            defn = lyr.GetLayerDefn()
            new = out.CreateLayer(table, lyr.GetSpatialRef(),
                                  defn.GetGeomType(), ["GEOMETRY_NAME=geom"])
            for i in range(defn.GetFieldCount()):
                new.CreateField(defn.GetFieldDefn(i))
            frame = defn.GetFieldIndex("tile_id")
            if mode == "consensus" and table == "polygons":
                for name in ("votes", "readings"):
                    if defn.GetFieldIndex(name) < 0:
                        new.CreateField(ogr.FieldDefn(name, ogr.OFTInteger))
                made = new.GetLayerDefn()
                # the pass, when every reading in the vote is of one pass
                passes = sorted({p for _, p in keep})
                one_pass = passes[0] if len(passes) == 1 else None
                # a frame is voted by the readings that covered it; one frame
                # asked for is measured alone
                voters = consensus_voters(
                    source, keep, shares=reading_shares(source, [tile_id])
                    if tile_id else None)
                for row in consensus_polygons(lyr, keep, tile_id, voters):
                    f = ogr.Feature(made)
                    f.SetGeometry(row["geometry"])
                    for name, value in (
                            ("class_name", row["class_name"]),
                            ("class_code", row["class_code"]),
                            ("tile_id", row["tile_id"]),
                            ("pass_no", one_pass),
                            ("operator", "CONSENSUS"),
                            ("created", now()),
                            ("votes", row["votes"]),
                            ("readings", row["readings"])):
                        if made.GetFieldIndex(name) >= 0 and value is not None:
                            f.SetField(name, value)
                    new.CreateFeature(f)
                    f = None
                continue
            who = defn.GetFieldIndex("operator")
            when = defn.GetFieldIndex("pass_no")
            made = new.GetLayerDefn()
            for f in lyr:
                if tile_id and (frame < 0
                                or str(f.GetField(frame)) != str(tile_id)):
                    continue
                if table in READING_TABLES and (
                        operator_word(f.GetField(who) if who >= 0 else None),
                        pass_number(f.GetField(when) if when >= 0 else None)) \
                        not in keep:
                    continue
                copy = ogr.Feature(made)
                copy.SetFrom(f)
                new.CreateFeature(copy)
                copy = None
            new = None
            lyr = None
    finally:
        out = None
        src = None


def polygonal(geom):
    """The polygons of a geometry, as one multipolygon, or None.

    An intersection of two polygons that share a border holds that border as
    a line too, and a multipolygon table cannot take a collection."""
    if geom is None or geom.IsEmpty():
        return None
    kind = ogr.GT_Flatten(geom.GetGeometryType())
    if kind == ogr.wkbPolygon:
        out = ogr.ForceToMultiPolygon(geom.Clone())
    elif kind == ogr.wkbMultiPolygon:
        out = geom.Clone()
    elif kind == ogr.wkbGeometryCollection:
        out = ogr.Geometry(ogr.wkbMultiPolygon)
        for i in range(geom.GetGeometryCount()):
            part = polygonal(geom.GetGeometryRef(i))
            if part is not None:
                for j in range(part.GetGeometryCount()):
                    out.AddGeometry(part.GetGeometryRef(j))
    else:
        return None
    if out.IsEmpty() or out.GetArea() <= 0:
        return None
    return out


def solid(geom):
    """polygonal(), with nothing as an empty multipolygon rather than None,
    for the sums that go on being worked on."""
    out = polygonal(geom)
    return out if out is not None else ogr.Geometry(ogr.wkbMultiPolygon)


def consensus_polygons(layer, readings, tile_id=None, voters=None):
    """The ground a strict majority of these readings give the same class,
    frame by frame, split by how many of them do.

    The same rule as the consensus of the whole raster, on the geometry
    instead of on the pixels: inside one reading the mark drawn last wins
    where two overlap, as it does when the reading is burned, and a piece
    of ground goes out in a class when more than half of the readings give
    it that class. Each row says how many did, in votes, out of how many,
    in readings. Ground the readings do not agree on goes out in no class.

    voters is campaign.consensus_voters' answer: the readings of a frame are
    those that covered it, so a frame read by 2 of 4 readings is voted by
    those 2 and the row says "readings: 2". None: every reading votes in
    every frame."""
    readings = [tuple(r) for r in readings]
    defn = layer.GetLayerDefn()
    who = defn.GetFieldIndex("operator")
    when = defn.GetFieldIndex("pass_no")
    frame = defn.GetFieldIndex("tile_id")
    code_at = defn.GetFieldIndex("class_code")
    name_at = defn.GetFieldIndex("class_name")
    ground, names = {}, {}
    layer.ResetReading()
    for f in layer:
        g = f.GetGeometryRef()
        if g is None or g.IsEmpty():
            continue
        r = (operator_word(f.GetField(who) if who >= 0 else None),
             pass_number(f.GetField(when) if when >= 0 else None))
        if r not in readings:
            continue
        tid = f.GetField(frame) if frame >= 0 else None
        if tile_id and str(tid) != str(tile_id):
            continue
        try:
            code = int(f.GetField(code_at) or 0)
        except (TypeError, ValueError):
            code = 0
        if code <= 0:
            continue
        if name_at >= 0:
            names.setdefault(code, f.GetField(name_at))
        own = ground.setdefault((tid, r), {})
        g = polygonal(g)
        if g is None:
            continue
        for other in list(own):
            if other != code:
                left = polygonal(own[other].Difference(g))
                if left is None:
                    del own[other]
                else:
                    own[other] = left
        own[code] = solid(own[code].Union(g)) if code in own else g
    out = []
    for tid in sorted({t for t, _ in ground}, key=lambda t: str(t)):
        here = voters_in(voters, tid, readings)
        readings_here = [r for r in readings if r in here]
        n = len(readings_here)
        need = majority(n)
        codes = sorted({c for (t, r), own in ground.items()
                        if t == tid and r in here for c in own})
        for code in codes:
            # levels[k] is the ground at least k + 1 of the readings give
            # this class, built one reading at a time
            levels = []
            for r in readings_here:
                g = ground.get((tid, r), {}).get(code)
                if g is None or g.IsEmpty():
                    continue
                top = len(levels)
                new_top = (solid(levels[top - 1].Intersection(g)) if top
                           else None)
                for k in range(top - 1, 0, -1):
                    levels[k] = solid(levels[k].Union(
                        solid(levels[k - 1].Intersection(g))))
                if top:
                    levels[0] = solid(levels[0].Union(g))
                else:
                    levels.append(g)
                if new_top is not None:
                    levels.append(new_top)
            for k in range(need, len(levels) + 1):
                piece = levels[k - 1]
                if k < len(levels) and not levels[k].IsEmpty():
                    piece = piece.Difference(levels[k])
                piece = polygonal(piece)
                if piece is None:
                    continue
                out.append({"geometry": piece, "class_code": code,
                            "class_name": names.get(code), "tile_id": tid,
                            "votes": k, "readings": n})
    return out

# ---------------------------------------------------------------------
# ---- doctor ----------------------------------------------------------
# ---------------------------------------------------------------------

# Reading every feature of a campaign with a hundred thousand polygons in it in
# order to answer a question about shape would take minutes and tell nobody
# anything new. These are the ceilings, and the report says when it hit one: a
# check that quietly looked at a tenth of the data and said "fine" would be worse
# than no check.
MANY_FEATURES = 20000
MANY_FRAMES = 400
# Comparing every polygon of a frame against every other is quadratic. Two
# hundred thousand pairs is a second or two; the point of the ceiling is that
# pressing Check on a very large campaign must not look like a hang.
MANY_PAIRS = 200000
# Geometry is written as the origin plus a whole number of pixels. A thousandth
# of a pixel is far beyond any rounding the program itself does and far below
# anything a hand edit would produce by accident.
OFF_GRID = 1e-3

OK, NOTE, BAD = "ok", "note", "problem"


class Finding(object):

    def __init__(self, level, what, detail=""):
        self.level = level
        self.what = what
        self.detail = detail

    def __str__(self):
        mark = {OK: "  ok   ", NOTE: "  note ", BAD: "  PROBLEM "}[self.level]
        return mark + self.what + (("\n           " + self.detail)
                                   if self.detail else "")


# =====================================================================
#  What is running
# =====================================================================
WANTED_DRIVERS = [("GTiff", "raster", "GeoTIFF, which every cutout is written as"),
                  ("GPKG", "vector", "the GeoPackage a campaign lives in"),
                  ("PNG", "raster", "PNG cutouts"),
                  ("JPEG", "raster", "JPEG cutouts"),
                  ("ESRI Shapefile", "vector", "Shapefile export"),
                  ("GeoJSON", "vector", "GeoJSON export"),
                  ("KML", "vector", "KML export")]


def about_the_machine():
    out = []
    # The versions come from environment(), the same list the trouble window
    # puts in its report, and only from there. Adding platform, Python or
    # numpy lines here as well would make Check say each of them twice, in two
    # spellings ("Python 3.9.18" and "python 3.9.18"), and two places to keep
    # right means one of them is wrong: the system line is where Windows 11 is
    # told apart from Windows 10. The program's own name and build are left
    # to the first line of environment() for the same reason. What is checked
    # here for numpy is the one thing environment() cannot say, which is why
    # it is missing when it is.
    for label, value in environment():
        out.append(Finding(OK, "%-10s %s" % (label, value)))
    try:
        importlib.import_module("numpy")
    except Exception as err:
        out.append(Finding(BAD, "numpy cannot be imported",
                           "%s. Cutouts and Whole cannot work without it; it "
                           "normally comes with QGIS." % err))
    missing = []
    for name, kind, why in WANTED_DRIVERS:
        try:
            got = (gdal.GetDriverByName(name) if kind == "raster"
                   else ogr.GetDriverByName(name))
        except Exception:
            got = None
        if got is None:
            missing.append((name, why))
    if missing:
        out.append(Finding(NOTE, "this GDAL is missing %d of the formats"
                                 % len(missing),
                           "; ".join("%s (%s)" % (n, w) for n, w in missing)
                           + ". Everything else still works."))
    else:
        out.append(Finding(OK, "every format this program writes is available"))
    where = log_path()
    out.append(Finding(OK, "log file   %s" % where) if where else
               Finding(NOTE, "no log file is being written",
                       "it starts when a campaign or a correction is open, "
                       "beside its manifest."))
    return out


# =====================================================================
#  Whether the campaign still makes sense
# =====================================================================
MANIFEST_WANTS = [("program", "which program wrote it"),
                  ("id", "what the layers in the project are matched against"),
                  ("name", "what the layers are called"),
                  ("classes", "the legend"),
                  ("grid", "the pixel grid every geometry is snapped to")]
GRID_WANTS = [("crs", "the coordinate system"),
              ("origin", "the corner every edge is counted from"),
              ("pixel_m", "the pixel size in metres")]


def about_the_campaign(campaign):
    if campaign is None:
        # Not an alarm: Correct and Cutouts are used with no campaign at all.
        return [Finding(NOTE, "no annotation campaign is open",
                        "Annotate and Objects need one; Correct and Cutouts "
                        "do not.")]
    out = []
    data = campaign.data or {}

    # ---- the manifest
    for key, why in MANIFEST_WANTS:
        if key not in data:
            out.append(Finding(BAD, "the manifest has no '%s'" % key,
                               "it is %s." % why))
    grid = data.get("grid") or {}
    if not isinstance(grid, dict):
        # A hand edit, or a manifest written by something else. Everything below
        # would have asked a string for its keys.
        out.append(Finding(BAD, "the grid is not an object",
                           "it is a %s. This may not be a %s campaign."
                           % (type(grid).__name__, NAME)))
        grid = {}
    else:
        for key, why in GRID_WANTS:
            if key == "crs" and grid.get(key):
                # An EPSG code, or a whole WKT for a system that has
                # no code. Either has to be one QGIS can read back.
                crs = crs_from_text(str(grid.get(key)))
                if not crs.isValid():
                    out.append(Finding(
                        BAD, "the coordinate system of the manifest cannot be "
                        "read", "it says %s. Areas and lengths in metres "
                        "cannot be trusted until it names one QGIS knows."
                        % str(grid.get(key))[:80]))
                continue
            if key in grid and grid.get(key):
                continue
            if key == "crs" and key in grid:
                # Written and empty is not damage, it is the supported case:
                # a raster QGIS opens with no coordinate system declared. The
                # New dialog takes one on purpose (the README says a photograph
                # with no coordinate system is a perfectly good thing to
                # annotate), so calling it a PROBLEM would raise an alarm over
                # the thing the program advertises, which is how a report stops
                # being read.
                out.append(Finding(
                    NOTE, "the raster has no coordinate system",
                    "which is allowed: the drawing is done on the pixel grid "
                    "and every geometry is kept. What is lost is only the "
                    "metres: areas and lengths come from the pixel size in "
                    "the manifest, so they are as good as that number is. "
                    "Give the raster a CRS in QGIS if they have to be exact."))
                continue
            out.append(Finding(BAD, "the grid has no '%s'" % key,
                               "it is %s." % why))
    ref = str(from_folder(grid.get("reference_raster") or "",
                          campaign.folder) or "")
    # A campaign can be made on anything QGIS will open, and a basemap is a URL,
# not a path. Testing it with os.path.exists would report "it is not where it
# was" about something that was never a file and is perfectly fine.
    looks_like_a_file = ref and "://" not in ref and not ref.lower().startswith(
        ("wms", "xyz", "wmts", "wcs", "postgres", "mssql", "oracle", "memory"))
    if looks_like_a_file and not os.path.exists(ref.split("|")[0]):
        out.append(Finding(NOTE, "the reference raster is not where it was",
                           ref + ". Measurements still work, because the "
                           "grid is in the manifest; a new cutout cannot be cut."))
    elif ref and not looks_like_a_file:
        out.append(Finding(OK, "the reference raster is a service, not a file",
                           ref[:70]))
    if not out:
        out.append(Finding(OK, "the manifest has everything it needs"))

    # ---- the package and its tables
    #
    # Whatever happens here, the three checks at the bottom still run. They
    # are not skipped by an early return, because the case that would skip
    # them is the case that needs them: a package a sync client has moved or
    # locked, with an hour of drawing sitting in the buffers. The report must
    # say more than that the GeoPackage could not be opened: it must also say
    # what is still in memory.
    counts, tables = {}, set()
    readable = True
    if not os.path.exists(campaign.package_path):
        out.append(Finding(BAD, "the GeoPackage is missing",
                           campaign.package_path))
        readable = False
    else:
        try:
            ds = ogr.Open(campaign.package_path)
            if ds is None:
                out.append(Finding(BAD, "the GeoPackage cannot be opened",
                                   "it may be held open by another QGIS, by "
                                   "this one's edit session, or by a sync "
                                   "client."))
                readable = False
            else:
                for i in range(ds.GetLayerCount()):
                    lyr = ds.GetLayerByIndex(i)
                    tables.add(lyr.GetName())
                    counts[lyr.GetName()] = lyr.GetFeatureCount()
            ds = None
        except Exception as err:
            out.append(Finding(BAD, "the GeoPackage cannot be read", str(err)))
            readable = False
    if not readable:
        out.append(_writable(campaign.folder))
        out.extend(_pending(campaign))
        out.extend(_project_layers(campaign))
        out.extend(_moved_corrections(campaign))
        return out
    for table, _, _ in TABLES:
        if table not in tables:
            out.append(Finding(NOTE, "the package has no '%s' table" % table,
                               "a campaign made by an older build; it is added "
                               "the next time the campaign is opened."))
    out.append(Finding(OK, "tables   " + ", ".join(
        "%s %d" % (t, counts.get(t, 0)) for t, _, _ in TABLES)))

    # ---- can it be written
    out.append(_writable(campaign.folder))

    # ---- the legend against what is drawn
    out.extend(_legend_against_features(campaign, counts))

    # ---- shape
    out.extend(_shape(campaign, grid))

    # ---- points, in a campaign drawn in frames
    out.extend(_points_in_frames(campaign, grid))

    # ---- work that never reached the disk
    out.extend(_pending(campaign))

    # ---- the project's own layers
    out.extend(_project_layers(campaign))

    # ---- corrections that now have a campaign of their own
    out.extend(_moved_corrections(campaign))
    return out


def _writable(folder, what="campaign"):
    probe = os.path.join(folder, ".rasterlabel_check")
    try:
        with open(probe, "w") as fh:
            fh.write("x")
        os.remove(probe)
        return Finding(OK, "the %s folder can be written" % what)
    except Exception as err:
        return Finding(BAD, "the %s folder cannot be written" % what,
                       "%s. Nothing can be saved into it: fix this before "
                       "drawing anything else." % err)


def _legend_against_features(campaign, counts):
    """Codes and names on the features, against the legend in the manifest.

    This is the pair that has to agree. The map is painted by name and the masks
    are burned from the code, so a feature whose name is not in the legend is
    invisible, and a feature whose code is not in the legend comes out of an
    export as a number nobody can read back.
    """
    out = []
    classes = campaign.data.get("classes") or []
    by_code = {c.get("code"): c.get("name") for c in classes}
    by_name = {c.get("name"): c.get("code") for c in classes}
    retired = {c.get("name") for c in classes if c.get("retired")}
    unknown_codes, wrong_names, looked = {}, {}, 0
    capped = False
    for table, _, _ in TABLES:
        if table == "tiles" or counts.get(table, 0) == 0:
            continue
        lyr = find_mine(campaign.data.get("id", ""), table)
        if lyr is None:
            continue
        for f in lyr.getFeatures():
            looked += 1
            if looked > MANY_FEATURES:
                capped = True
                break
            try:
                code, name = f["class_code"], f["class_name"]
            except Exception:
                continue
            if code not in by_code:
                unknown_codes.setdefault(code, 0)
                unknown_codes[code] += 1
            elif name != by_code[code]:
                wrong_names.setdefault((name, code), 0)
                wrong_names[(name, code)] += 1
        if capped:
            break
    if unknown_codes:
        out.append(Finding(BAD, "%d things carry a class code the legend does "
                                "not have" % sum(unknown_codes.values()),
                           "codes " + ", ".join(str(c) for c in sorted(
                               unknown_codes, key=lambda x: str(x)))
                           + ". An export would write a number nobody can read "
                             "back. Open Classes and give those codes a name, or "
                             "reclassify the features."))
    if wrong_names:
        out.append(Finding(BAD, "%d things carry a name the legend gives to "
                                "another code" % sum(wrong_names.values()),
                           ", ".join("'%s' with code %s" % (n, c)
                                     for n, c in sorted(wrong_names,
                                                        key=str)[:6])
                           + ". The map paints by name, so these are drawn as "
                             "something they are not: press Classes and Ok, "
                             "which rewrites the names from the codes."))
    wide = sorted(c.get("code") for c in classes
                  if isinstance(c.get("code"), int)
                  and c.get("code") > MAX_CLASS_CODE)
    if wide:
        out.append(Finding(NOTE, "%d class code%s past %d"
                                 % (len(wide), "" if len(wide) == 1 else "s",
                                    MAX_CLASS_CODE),
                           "codes " + ", ".join(str(c) for c in wide[:6])
                           + ". A campaign hands out 1 to %d, and 255 is kept "
                             "for 'ignore'; these came from somewhere else. "
                             "Nothing is lost: a mask with them in it is "
                             "written in 16 bits instead of one byte, so check "
                             "that whatever reads it expects that."
                           % MAX_CLASS_CODE))
    if retired:
        out.append(Finding(NOTE, "%d retired class%s in the legend"
                                 % (len(retired), "" if len(retired) == 1 else "es"),
                           ", ".join(sorted(retired))
                           + ". Retired is normal: the number stays reserved so "
                             "nothing already exported changes meaning."))
    if not unknown_codes and not wrong_names:
        out.append(Finding(OK, "every class code and name agrees with the legend"
                               + (" (first %d things)" % MANY_FEATURES
                                  if capped else "")))
    if not by_name:
        out.append(Finding(BAD, "the legend is empty", "nothing can be drawn."))
    return out


def _shape(campaign, grid):
    """Are the frames still on the grid, do the outlines not cross themselves,
    and is the partition still a partition.

    All three are invariants the program maintains by construction, which is
    exactly why they are worth testing: an invariant that is never checked is
    a belief.
    """
    out = []
    try:
        ox, oy = [float(v) for v in grid.get("origin", (0.0, 0.0))]
        px, py = [abs(float(v)) for v in grid.get("pixel_crs")
                  or grid.get("pixel_m") or (1.0, 1.0)]
    except Exception:
        return [Finding(NOTE, "the grid cannot be read, so shape was not checked")]
    if not px or not py:
        return [Finding(NOTE, "the pixel size is zero, so shape was not checked")]

    lyr = find_mine(campaign.data.get("id", ""), "polygons")
    if lyr is None:
        return [Finding(NOTE, "the polygons layer is not in the project, so "
                              "shape was not checked")]

    # What is measured against the grid, and what is not.
    #
    # The frames are: a frame is placed on the grid by snapped_square, a cutout
    # is cut from it, and a frame half a pixel out offsets every image and every
    # mask cut from it for good. That is a defect and is reported as one.
    #
    # The polygons are not. A brush outline follows the hand, vertex by vertex,
    # and is never snapped to anything; checking it would say "4 polygons not
    # on the pixel grid" about four perfectly ordinary polygons, blame the
    # vertex tool for it, and say it about every campaign ever drawn. What is
    # exact at the pixel is the frame, the strip a line claims, the footprint
    # of a point, and the mask burned at export, which is rasterized on the
    # campaign grid with the centre rule and no resampling. The README says the
    # same.
    off_frames, frames_read, frames_unreadable = 0, 0, 0
    frames_left = False
    tiles_layer = find_mine(campaign.data.get("id", ""), "tiles")
    if tiles_layer is not None:
        for t in tiles_layer.getFeatures():
            if frames_read >= MANY_FRAMES:
                frames_left = True
                break
            tg = t.geometry()
            if tg is None or tg.isEmpty():
                continue
            frames_read += 1
            tb = tg.boundingBox()
            try:
                for value, origin, size in ((tb.xMinimum(), ox, px),
                                            (tb.xMaximum(), ox, px),
                                            (tb.yMinimum(), oy, py),
                                            (tb.yMaximum(), oy, py)):
                    whole = (value - origin) / size
                    if abs(whole - round(whole)) > OFF_GRID:
                        off_frames += 1
                        break
            except (ValueError, OverflowError, ZeroDivisionError):
                frames_unreadable += 1

    looked, capped, frames_capped, unreadable = 0, False, False, 0
    crossing = 0
    per_frame = {}
    # the class of each polygon in per_frame, in the same order: two polygons
    # of one class and one reading that meet are one polygon waiting to be
    # merged, which is a different thing to say than "share ground"
    per_class = {}
    frames_kept = set()
    for f in lyr.getFeatures():
        looked += 1
        if looked > MANY_FEATURES:
            capped = True
            break
        g = f.geometry()
        if g is None or g.isEmpty():
            continue
        # An outline that crosses itself. QGIS's vertex tool lets a vertex be
        # dragged across its own polygon's edge, and every later cut against
        # that bow tie fails: the brush stops settling anything near it.
        try:
            if not g.isGeosValid():
                crossing += 1
        except Exception:
            pass
        try:
            # The operator belongs in this key as much as the frame and the
            # pass do. Two people reading the same frame are meant to cover it
            # twice, each from scratch: that is what makes the two readings
            # comparable, and their polygons overlap each other almost
            # everywhere by design. Grouped by frame and pass alone, every one
            # of those pairs would be reported in red as "polygons share ground",
            # on a campaign where nothing is wrong, and the advice under it
            # would be to press Repair. A check that cries wolf about the one thing
            # the campaign is built to do is worse than no check.
            who = operator_word(f["operator"])
        except (KeyError, IndexError):
            who = operator_word(None)
        # Read through the same two functions measure_tile, the filter and
        # the exports read a reading through, so that what Check calls one
        # reading is what the save closed the frame by.
        try:
            key = (f["tile_id"], pass_number(f["pass_no"]), who)
        except Exception:
            key = (None, 1, who)
        # The ceiling counts frames, not readings: three operators on one frame
        # are one frame, and counting them as three switched the closed check
        # off on a campaign of a hundred and fifty frames read three times.
        if len(frames_kept) < MANY_FRAMES or key[0] in frames_kept:
            frames_kept.add(key[0])
            per_frame.setdefault(key, []).append(g)
            try:
                per_class.setdefault(key, []).append(f["class_name"])
            except (KeyError, IndexError):
                per_class.setdefault(key, []).append(None)
        else:
            frames_capped = True

    # What was actually looked at, said once and used by every claim below. A
    # claim measured on a tenth of a campaign must not be printed in the same
    # words as a claim measured on all of it, whether or not it found something.
    partial = []
    if capped:
        partial.append("only the first %d polygons were read" % MANY_FEATURES)
    if frames_capped:
        partial.append("only the first %d frames were kept" % MANY_FRAMES)
    seen_all = not partial

    if unreadable:
        out.append(Finding(NOTE, "%d polygon%s could not be measured"
                                 % (unreadable, "" if unreadable == 1 else "s"),
                           "their coordinates are not numbers, which means a "
                           "corrupt or truncated record. They were skipped; "
                           "everything else was still checked."))
    if crossing:
        out.append(Finding(BAD, "%d polygon outline%s cross%s itself"
                                % (crossing, "" if crossing == 1 else "s",
                                   "es" if crossing == 1 else ""),
                           "a vertex dragged across an edge of its own polygon "
                           "makes a bow tie, and nothing can be cut against "
                           "it. Press Repair in Annotate on that frame: it "
                           "untangles the outline into the polygons it "
                           "encloses before anything else."
                           + ("" if seen_all else
                              " And %s, so there may be more."
                              % " and ".join(partial))))
    if frames_unreadable:
        out.append(Finding(NOTE, "%d frame%s could not be measured"
                                 % (frames_unreadable,
                                    "" if frames_unreadable == 1 else "s"),
                           "their coordinates are not numbers, which means a "
                           "corrupt or truncated record."))
    if off_frames:
        out.append(Finding(BAD, "%d frame%s not on the pixel grid"
                                % (off_frames, "" if off_frames == 1 else "s"),
                           "every cutout and every mask taken from them is "
                           "offset by a fraction of a pixel from the image, "
                           "and nothing in the files says so. A frame is "
                           "placed on the grid when it is made, so one off it "
                           "was moved by something else: the QGIS vertex tool "
                           "on the frames layer, or an import."))
    elif frames_left:
        # "every frame" would be a claim about frames that were never read
        out.append(Finding(NOTE, "the first %d frame%s sit on the pixel grid"
                                 % (frames_read, "" if frames_read == 1 else "s"),
                           "the rest were not measured. This says the "
                           "campaign is big, not that the rest is clean."))
    elif frames_read:
        out.append(Finding(OK, "every frame sits on the pixel grid",
                           "which is what the cutouts and the masks are cut "
                           "on. Brush outlines are vector and follow the hand; "
                           "the mask is burned on the campaign grid at export, "
                           "so it still lines up with the image pixel for "
                           "pixel."))
    # And with no frame at all there is nothing to say. A branch here used to
    # print "not everything was looked at" followed by an empty reason on every
    # campaign drawn without frames, a warning about frames it never had.

    # Not "more than nothing". A border GEOS computed twice, once for each side,
    # leaves an intersection of the order of 1e-16 m2 between two polygons that
    # meet exactly; a vertex move followed by the trim does it about one time in
    # five. Counted as an overlap, it made Check say "1 pair share ground" and
    # Repair, which rightly ignores it, answer "0 overlaps resolved".
    # (joint_of reads that same threshold, so the two cannot drift apart)
    overlaps = 0
    same_class = 0          # of the overlaps, those between polygons of one class
    unmerged = 0            # neighbours of one class that share a border only
    pairs = 0
    stopped = False
    for key, geoms in per_frame.items():
        if stopped:
            break               # and out of the frames too, not just the pairs
        if len(geoms) < 2:
            continue
        for i in range(len(geoms)):
            for j in range(i + 1, len(geoms)):
                if pairs >= MANY_PAIRS:
                    stopped = True
                    break
                pairs += 1
                a, b = geoms[i], geoms[j]
                try:
                    how = joint_of(a, b, px, py)
                except Exception:
                    continue
                if how == "overlap":
                    overlaps += 1
                    if (per_class[key][i] is not None
                            and per_class[key][i] == per_class[key][j]):
                        same_class += 1
                elif (how == "border" and per_class[key][i] is not None
                        and per_class[key][i] == per_class[key][j]):
                    unmerged += 1
            if stopped:
                break
    if overlaps:
        out.append(Finding(BAD, "%d pair%s of polygons share ground"
                                % (overlaps, "" if overlaps == 1 else "s"),
                           "within one frame, one pass and one operator they "
                           "should not: press Repair in Annotate, which gives "
                           "the ground to the smaller one. Two operators "
                           "reading the same frame are not counted here, "
                           "because their readings are meant to cover it twice."
                           + ("" if not same_class else
                              " %d of the pair%s are polygons of one class, "
                              "which Repair also joins into one."
                              % (same_class, "" if same_class == 1 else "s"))
                           + ("" if seen_all and not stopped else
                              " And %s, so this is a floor, not a total."
                              % " and ".join(
                                  partial + (["the comparison stopped after "
                                              "%d pairs" % MANY_PAIRS]
                                             if stopped else [])))))
    elif capped or stopped or frames_capped:
        # Not a clean bill of health, and it must not read like one. The whole
        # value of this report is that what it says can be relied on, so a check
        # that ran out of patience says so instead of printing the same line a
        # finished check prints.
        out.append(Finding(NOTE, "no overlap found, but not everything was "
                                 "looked at",
                           "%s. Nothing here says the rest is clean: it says "
                           "the campaign is big. Repair in Annotate works on "
                           "the frame in hand whatever this found."
                           % ", ".join(
                               ([("only the first %d things were read"
                                  % MANY_FEATURES)] if capped else [])
                               + ([("only the first %d frames were kept"
                                    % MANY_FRAMES)] if frames_capped else [])
                               + ([("the comparison stopped after %d pairs"
                                    % MANY_PAIRS)] if stopped else []))))
    else:
        out.append(Finding(OK, "no two polygons of one reading share ground"))

    if unmerged:
        out.append(Finding(NOTE, "%d pair%s of neighbours of one class are "
                                 "still separate polygons"
                                 % (unmerged, "" if unmerged == 1 else "s"),
                           "same class, same reading and same frame, sharing a "
                           "border. A new mark or a moved vertex joins such "
                           "neighbours as they meet; these were drawn before "
                           "that, or with a QGIS tool. Nothing is wrong with "
                           "the pixels: press Repair in Annotate to join them, "
                           "in one step that Undo takes back."))
    out.extend(_closed_flags(campaign, per_frame, partial))
    return out


def _points_in_frames(campaign, grid):
    """In a campaign drawn in frames, does every point sit inside its frame.

    Areas and lines are clipped to the frame they are drawn in, and points are
    refused outside it, footprint and all. Points dropped by an earlier
    build were not: they went down wherever the click was, a point outside
    every frame was written with no frame at all, and the export burned its
    footprint on ground no frame covers. Those are found here, and so are
    points whose tile_id names a frame other than the one they sit in, which
    a move of that frame would leave behind.

    A note, not a problem: nothing is broken, and the mask says what was
    drawn. But a frame is meant to bound what is labelled, and these do not
    keep to it."""
    if not (campaign.data or {}).get("with_tiles"):
        return []
    points = find_mine(campaign.data.get("id", ""), "points")
    tiles = find_mine(campaign.data.get("id", ""), "tiles")
    if points is None or tiles is None:
        return []
    try:
        origin = tuple(float(v) for v in grid.get("origin", (0.0, 0.0)))
        # A manifest with no pixel size at all is judged on the point alone,
        # not on a square of one map unit that would have nothing to do with
        # the raster: a metre "pixel" on a 5 cm survey would call every point
        # near an edge outside.
        pixel = tuple(abs(float(v)) for v in grid.get("pixel_crs")
                      or grid.get("pixel_m") or (0.0, 0.0))
    except Exception:
        return [Finding(NOTE, "the grid cannot be read, so the points were "
                              "not checked against the frames")]
    # Every frame, not the first few hundred: a point in a frame past a cap
    # would have been counted outside every frame, which it is not. A frame is
    # one square, so reading them all costs little; the points are what is
    # capped. Each frame keeps its bounding box, so that a point is tested
    # with GEOS only against the frames that could hold it.
    frames, named_frames = [], {}
    for t in tiles.getFeatures():
        g = t.geometry()
        if g is None or g.isEmpty():
            continue
        try:
            tid = t["tile_id"]
        except (KeyError, IndexError):
            tid = None
        tid = str(tid) if tid is not None else ""
        try:
            b = g.boundingBox()
            bounds = (b.xMinimum(), b.yMinimum(), b.xMaximum(), b.yMaximum())
        except Exception:
            bounds = None
        frames.append((tid, g, bounds))
        named_frames.setdefault(tid, []).append((tid, g, bounds))
    try:
        has_size = "size_px" in [f.name() for f in points.fields()]
    except Exception:
        has_size = False
    outside, wrong, looked, capped = 0, 0, 0, False
    for f in points.getFeatures():
        looked += 1
        if looked > MANY_FEATURES:
            capped = True
            break
        g = f.geometry()
        if g is None or g.isEmpty():
            continue
        try:
            b = g.boundingBox()
            x, y = b.xMinimum(), b.yMinimum()
        except Exception:
            continue
        n = 1
        if has_size:
            try:
                n = max(1, int(f["size_px"] or 1))
            except (KeyError, IndexError, TypeError, ValueError):
                n = 1
        try:
            named = f["tile_id"]
        except (KeyError, IndexError):
            named = None
        named = "" if named is None else str(named)
        # The frame it names is asked first. Frames may overlap, and a point
        # in the overlap that names the second of the two is where it belongs:
        # taking the first frame that holds it would have called it misnamed.
        if _fits_one(named_frames.get(named, ()), x, y, n, origin, pixel):
            continue
        if _fits_one(frames, x, y, n, origin, pixel):
            wrong += 1
        else:
            outside += 1
    if looked == 0:
        return []
    partial = (" Only the first %d points were read, so there may be more."
               % MANY_FEATURES) if capped else ""
    out = []
    if outside:
        out.append(Finding(
            NOTE, "%d point%s outside every frame"
                  % (outside, "" if outside == 1 else "s"),
            "the point, or the square of pixels it stands for, is not wholly "
            "inside any frame, so the export labels ground no frame covers. "
            "Points are refused there now; these were dropped by an earlier "
            "build. To clean up: in Annotate take Points, untick \"only the "
            "current tile\" if it is ticked so that the ones with no "
            "frame are drawn, and right click each one to remove it (removing "
            "works anywhere), then drop it again "
            "inside the frame it belongs to, further in from the edge or with "
            "a smaller point size if it was its square that reached past the "
            "edge. In QGIS, Select by Expression on the points layer with "
            "\"tile_id\" = '' or \"tile_id\" IS NULL finds the ones that "
            "have no frame at all." + partial))
    if wrong:
        out.append(Finding(
            NOTE, "%d point%s inside a frame other than the one %s"
                  % (wrong, "" if wrong == 1 else "s",
                     "it names" if wrong == 1 else "they name"),
            "the tile_id says one frame and the point sits in another, so "
            "moving or deleting its frame would leave it behind. To clean "
            "up: select the frame it sits in, take Points, right click the "
            "point to remove it and drop it again, which writes the frame's "
            "name on it." + partial))
    if not out:
        out.append(Finding(
            OK if not capped else NOTE,
            "every point sits inside the frame it names" if not capped else
            "the first %d points sit inside the frame they name"
            % MANY_FEATURES,
            "" if not capped else "the rest were not read."))
    return out


def _fits_one(frames, x, y, n, origin, pixel):
    """Whether a point's footprint lies wholly inside one of these frames.

    The bounding box of each frame is compared first, which is plain
    arithmetic: thousands of points against hundreds of frames would
    otherwise be a million GEOS calls for a report that has to come back
    while the person waits."""
    for _, fg, bounds in frames:
        if bounds is not None and not (bounds[0] <= x <= bounds[2]
                                       and bounds[1] <= y <= bounds[3]):
            continue
        try:
            if footprint_fits(fg, x, y, n, origin, pixel):
                return True
        except Exception:
            continue
    return False


def _closed_flags(campaign, per_frame, partial=()):
    """Does the closed column agree with what is painted in the frame.

    closed is the column that says a frame is a complete reading and can be
    handed to somebody. It is written at save time from the coverage, so it can
    disagree with the drawing in exactly one way: the drawing changed and no save
    has happened since. A frame marked closed with a hole in it is the worst
    thing this program can produce, because it is wrong in a way that looks
    finished, and this is the only place that would ever notice.

    Measured on the plane rather than on the ellipsoid: it is a ratio of two
    areas in the same system, so the difference cancels, and this is a
    disagreement test rather than a measurement.
    """
    tiles = find_mine(campaign.data.get("id", ""), "tiles")
    if tiles is None or not per_frame:
        return []
    names = set()
    try:
        names = {f.name() for f in tiles.fields()}
    except Exception:
        pass
    if "closed" not in names:
        return [Finding(NOTE, "the frames have no 'closed' column",
                        "a campaign made by an older build.")]
    if partial:
        # Measured on what was read, a frame whose polygons lie past the
        # ceiling comes out 0% painted, and if it is marked closed it would be
        # reported as a PROBLEM about a frame nobody has looked at.
        return [Finding(NOTE, "the 'closed' column was not checked",
                        "%s, so the coverage of some frames is unknown."
                        % " and ".join(partial))]
    wrong, looked, left = [], 0, False
    for f in tiles.getFeatures():
        looked += 1
        if looked > MANY_FRAMES:
            left = True
            break
        try:
            tid = f["tile_id"]
            said = int(f["closed"] or 0)
            frame = f.geometry()
        except Exception:
            continue
        if frame is None or frame.isEmpty():
            continue
        whole = frame.area()
        if not whole:
            continue
        best, best_key = 0.0, None
        # The key is (frame, pass, operator) and is read by position, never
        # unpacked by shape. It was unpacked as two values; the operator was
        # then added to the key to stop two readings of one frame from being
        # called an overlap, and Check stopped with "too many values to
        # unpack" on every campaign with a frame in it. The best reading of
        # the frame, whoever made it, is what "closed" is compared with: one
        # reading on its own, never two operators added together, which is
        # what the save writes closed from too.
        for key, geoms in per_frame.items():
            if key[0] != tid:
                continue
            try:
                clipped = [g.intersection(frame) for g in geoms]
                clipped = [g for g in clipped if g is not None and not g.isEmpty()]
                if not clipped:
                    continue
                one = (QgsGeometry.unaryUnion(clipped) if len(clipped) > 1
                       else clipped[0])
                share = one.area() / whole
                if share > best:
                    best, best_key = share, key
            except Exception:
                continue
        really = best > CLOSED_SHARE
        if bool(said) != really:
            wrong.append((tid, said, best, best_key))
    if not wrong and left:
        # "every frame" would vouch for frames that were never read
        return [Finding(NOTE, "the 'closed' column agrees in the first %d "
                              "frames" % MANY_FRAMES,
                        "the rest were not compared. This says the campaign "
                        "is big, not that the rest is right.")]
    if not wrong:
        return [Finding(OK, "every frame's 'closed' column agrees with what is "
                            "painted in it")]
    shut = [w for w in wrong if w[1]]
    return [Finding(BAD if shut else NOTE,
                    "%d frame%s whose 'closed' column disagrees with the drawing"
                    % (len(wrong), "" if len(wrong) == 1 else "s"),
                    ", ".join("%s says %s and is %.1f%% painted%s"
                              % (tid, "closed" if said else "open", share * 100,
                                 " in its fullest reading, %s"
                                 % reading_label((key[2], key[1]))
                                 if key is not None else "")
                              for tid, said, share, key in wrong[:6])
                    + (". A frame marked closed is one somebody is told they "
                       "can hand over. Press Save: the column is rewritten from "
                       "the coverage every time." if shut else
                       ". Press Save and they will agree again."))]


def _pending(campaign):
    out = []
    waiting = []
    for role in EDITABLE_TABLES:
        lyr = find_mine(campaign.data.get("id", ""), role)
        if lyr is not None and lyr.isEditable() and lyr.isModified():
            waiting.append(role)
    if waiting:
        out.append(Finding(NOTE, "work not yet on disk in " + ", ".join(waiting),
                           "press Save. It is in the recovery file meanwhile."))
    # With the running session's name, or the file this very session wrote a
    # second ago would be reported as an afternoon somebody lost, with advice to
    # close the campaign and open it again to be asked about it.
    mine = ""
    try:
        from .launch import _RASTERLABEL
        if _RASTERLABEL:
            net = _RASTERLABEL[2].recovery
            mine = net.session if net is not None else ""
    except Exception:
        mine = ""
    left = snapshots_waiting(campaign.folder, mine,
                             campaign.data.get("id", ""))
    if left:
        out.append(Finding(NOTE, "%d recovery file%s from an earlier session"
                                 % (len(left), "" if len(left) == 1 else "s"),
                           "; ".join(describe_snapshot(h, r)
                                     for _, h, r in left[:3])
                           + ". Close the campaign and open it again to be "
                             "asked about them."))
    # And the files dealt with earlier. A file turned down at the question is
    # work that is not in the package, kept as text, and a campaign holding
    # one is not "everything on disk", so it is counted here even though the
    # file was renamed out of the way when "Not now" was answered.
    aside = snapshots_set_aside(campaign.folder, campaign.data.get("id", ""))
    if aside:
        dropped = [a for a in aside if a[1] == "discarded"]
        shown = sorted(aside, key=lambda a: a[1] != "discarded")[:4]
        out.append(Finding(
            NOTE, "%d recovery file%s set aside in %s%s" % (
                len(aside), "" if len(aside) == 1 else "s",
                os.path.join(os.path.basename(campaign.folder), "recovery"),
                ", %d of them discarded: that work is not in the package"
                % len(dropped) if dropped else ""),
            "; ".join("%s (%s): %s" % (
                os.path.basename(path),
                "discarded" if how == "discarded" else
                "put back, or declined by an earlier build",
                describe_snapshot(h, r)) for path, how, h, r in shown)
            + ". They are plain text. To be asked about a discarded one "
              "again, take .discarded off the end of its name and open the "
              "campaign again; do the same with .restored only after reading "
              "it, because work already put back would be put back twice. "
              "Delete them once nothing in them is wanted."))
    if not out:
        out.append(Finding(OK, "everything drawn is on disk"))
    return out


def _project_layers(campaign):
    """Layers in the project that read this package but are not marked as ours.

    A QGIS project saves its layers. Reopen the project and they come back; if
    the program does not recognise them it adds a second set on top, and the map
    draws everything twice. claim_strays fixes it at open, and this says whether
    it worked.
    """
    target = os.path.normcase(os.path.abspath(campaign.package_path))
    mine, theirs = 0, []
    for lyr in QgsProject.instance().mapLayers().values():
        try:
            here = os.path.normcase(os.path.abspath(source_of(lyr).split("|")[0]))
        except Exception:
            continue
        if here != target:
            continue
        if lyr.customProperty("rasterlabel/campaign"):
            mine += 1
        else:
            theirs.append(lyr.name())
    # And the other way round: marked as the campaign's and reading another
    # file, the original of a copied folder or the old place of a moved one.
    # Every stroke would go there, or nowhere (layers.drop_stale).
    elsewhere = [lyr for lyr in my_layers(campaign.data.get("id", ""))
                 if lyr.customProperty("rasterlabel/role")
                 in [t for t, _, _ in TABLES]
                 and not reads_file(lyr, campaign.package_path)]
    if elsewhere:
        return [Finding(BAD, "%d of the campaign's layer%s read another file "
                             "than its GeoPackage" % (
                                 len(elsewhere),
                                 "" if len(elsewhere) == 1 else "s"),
                        "; ".join("%s: %s%s" % (
                            lyr.name(), source_of(lyr),
                            "" if lyr.isValid() else ", not there")
                            for lyr in elsewhere[:5])
                        + ". What is drawn would not reach this campaign. "
                          "Close the campaign and open it again: they are "
                          "replaced by layers of its own file.")]
    if theirs:
        return [Finding(NOTE, "%d layer%s read this package but are not the "
                              "campaign's" % (len(theirs),
                                              "" if len(theirs) == 1 else "s"),
                        ", ".join(theirs[:6])
                        + ". The map may draw the same thing twice. Close the "
                          "campaign and open it again: the layers already there "
                          "are adopted instead of being doubled.")]
    return [Finding(OK, "%d layer%s in the project, all the campaign's"
                        % (mine, "" if mine == 1 else "s"))]


# =====================================================================
#  Whether the correction still makes sense
# =====================================================================
CORRECTION_WANTS = [("program", "which program wrote it"),
                    ("kind", "what kind of manifest this is"),
                    ("format", "the version of the manifest"),
                    ("id", "what its layer in the project is matched against"),
                    ("name", "what it is called"),
                    ("source", "the map it started from"),
                    ("band", "the band that holds the classes"),
                    ("working_copy", "the copy that is corrected"),
                    ("grid", "the pixel grid areas are measured on"),
                    ("classes", "the classes the chips are drawn with")]


def about_the_correction(book):
    """The correction campaign open in Correct, looked over as the campaign
    is: the manifest, the working copy, the map it came from, the classes
    against the codes in the copy, the log of operations. Nothing is
    repaired."""
    out = []
    data = book.data or {}
    for key, why in CORRECTION_WANTS:
        if key not in data:
            out.append(Finding(BAD, "the manifest has no '%s'" % key,
                               "it is %s." % why))
    grid = data.get("grid") or {}
    if not isinstance(grid, dict):
        out.append(Finding(BAD, "the grid is not an object",
                           "it is a %s." % type(grid).__name__))
        grid = {}
    text = str(grid.get("crs") or "")
    if text and not crs_from_text(text).isValid():
        out.append(Finding(BAD, "the coordinate system of the manifest cannot "
                                "be read",
                           "it says %s. Areas in m2 cannot be trusted until "
                           "it names one QGIS knows." % text[:80]))
    elif "crs" in grid and not text:
        out.append(Finding(NOTE, "the map has no coordinate system",
                           "which is allowed: areas are counted in the pixel "
                           "size of the manifest."))
    for key in ("origin", "pixel_m"):
        if grid and not grid.get(key):
            out.append(Finding(BAD, "the grid has no '%s'" % key,
                               "it is %s." % dict(GRID_WANTS)[key]))

    # ---- the working copy
    path = book.working_path
    ds = None
    if not path or not os.path.exists(path):
        out.append(Finding(BAD, "the working copy is missing", path or "?"))
    else:
        try:
            ds = gdal.Open(path)
        except Exception:
            ds = None
        if ds is None:
            out.append(Finding(BAD, "the working copy cannot be opened", path))
    if ds is not None:
        for look in (_copy_like_its_map, _changes_beside):
            try:
                out.extend(look(ds, path, data))
            except Exception as err:
                out.append(Finding(NOTE, "part of the working copy could not "
                                         "be looked at", str(err)))
        size = grid.get("size")
        # the grid QGIS draws the copy on, the one the strokes land on
        gt = pixel_grid(ds)
        if is_rotated(gt):
            out.append(Finding(BAD, "the working copy has a rotated pixel grid",
                               "Correct does not open it: a stroke would "
                               "change pixels beside the ones under it. Warp "
                               "the map north-up and correct that one."))
        drift = []
        if size and list(size) != [ds.RasterXSize, ds.RasterYSize]:
            drift.append("%d x %d pixels, the manifest says %d x %d"
                         % (ds.RasterXSize, ds.RasterYSize, size[0], size[1]))
        origin = grid.get("origin")
        if origin and gt and (abs(gt[0] - origin[0]) > 1e-6 * max(1, abs(gt[1]))
                              or abs(gt[3] - origin[1]) > 1e-6 * max(1, abs(gt[5]))):
            drift.append("its corner is %.6f, %.6f, the manifest says %.6f, "
                         "%.6f" % (gt[0], gt[3], origin[0], origin[1]))
        if drift:
            out.append(Finding(BAD, "the working copy is not on the grid of "
                                    "the manifest",
                               "; ".join(drift) + ". It was replaced or "
                               "edited by something else."))
        try:
            band = ds.GetRasterBand(int(data.get("band", 1)))
            nodata = band.GetNoDataValue()
            # a strip at a time: the band of a large map is not held whole
            present = set(codes_present(
                BandPlane(path, int(data.get("band", 1))), nodata))
        except Exception as err:
            present = None
            out.append(Finding(BAD, "the class band cannot be read", str(err)))
        if present is not None:
            listed = {c.get("code") for c in data.get("classes") or []}
            unnamed = sorted(present - listed)
            if unnamed:
                out.append(Finding(NOTE, "%d code%s in the copy without a class"
                                         % (len(unnamed),
                                            "" if len(unnamed) == 1 else "s"),
                                   ", ".join(str(v) for v in unnamed[:12])
                                   + ". Each is given a class when the "
                                     "correction is opened."))
            if nodata is not None and nodata in listed:
                out.append(Finding(BAD, "the nodata value is listed as a class",
                                   "%s. Painting it would erase pixels, not "
                                   "correct them: change it in Classes." % nodata))
            if not unnamed and not (nodata is not None and nodata in listed):
                out.append(Finding(OK, "every code in the copy has a class, %d "
                                       "in all" % len(listed)))
        ds = None

    # ---- the map it started from
    source = str(data.get("source") or "")
    if source and not os.path.exists(source.split("|")[0]):
        out.append(Finding(NOTE, "the map it started from is not where it was",
                           source + ". The copy is corrected all the same; "
                           "'show the original beside it' cannot work."))

    # ---- the log of operations against the count
    log_csv = os.path.join(os.path.dirname(path or book.folder), "operations.csv")
    rows = None
    if os.path.exists(log_csv):
        try:
            with open(log_csv, encoding="utf-8", errors="replace") as fh:
                rows = max(0, sum(1 for line in fh if line.strip()) - 1)
        except Exception:
            rows = None
    counted = int(data.get("operations", 0) or 0)
    if rows is not None and rows != counted:
        out.append(Finding(NOTE, "operations.csv has %d rows and the manifest "
                                 "counts %d" % (rows, counted),
                           "an undo keeps its row in the log, so the two can "
                           "differ; the log is the history."))
    elif rows is None and counted:
        out.append(Finding(NOTE, "the manifest counts %d operations and there "
                                 "is no operations.csv" % counted,
                           "the history of the strokes is not there."))

    out.append(_writable(book.folder, "correction"))
    return out


def _copy_like_its_map(ds, path, data):
    """The working copy against the map it corrects: the same bands, in the
    same order, with the same names, types and nodata. The correction of a
    thematic map is a thematic map, and a copy that is not the original band
    for band does not open the way the original does."""
    flag = None
    for b in range(1, ds.RasterCount + 1):
        if (ds.GetRasterBand(b).GetDescription() or "").lower() == FLAG_BAND_NAME:
            flag = b
    if flag is not None:
        return [Finding(NOTE, "the working copy still has the '%s' band of an "
                              "earlier build" % FLAG_BAND_NAME,
                        "it is moved to the file beside the copy the next "
                        "time Correct opens it, and the copy is left with the "
                        "bands of the map it corrects.")]
    source = str(data.get("source") or "").split("|")[0]
    if not source or not os.path.exists(source):
        return []
    try:
        src = gdal.Open(source)
    except Exception:
        src = None
    if src is None:
        return []
    wrong = []
    if src.RasterCount != ds.RasterCount:
        wrong.append("%d bands, the map has %d" % (ds.RasterCount,
                                                   src.RasterCount))
    else:
        for b in range(1, ds.RasterCount + 1):
            x, y = src.GetRasterBand(b), ds.GetRasterBand(b)
            if (x.GetDescription() or "") != (y.GetDescription() or ""):
                wrong.append("band %d is '%s', the map's is '%s'"
                             % (b, y.GetDescription(), x.GetDescription()))
            if x.DataType != y.DataType:
                wrong.append("band %d is %s, the map's is %s"
                             % (b, gdal.GetDataTypeName(y.DataType),
                                gdal.GetDataTypeName(x.DataType)))
            a, z = x.GetNoDataValue(), y.GetNoDataValue()
            if not (a == z or (a is not None and z is not None
                               and a != a and z != z)):
                wrong.append("band %d has nodata %s, the map's is %s"
                             % (b, z, a))
    src = None
    if wrong:
        return [Finding(NOTE, "the working copy is not the map it corrects "
                              "band for band",
                        "; ".join(wrong[:6]) + ". It opens differently from "
                        "the original.")]
    return [Finding(OK, "the working copy has the %d band%s of the map it "
                        "corrects, in its order" % (ds.RasterCount,
                                                    "" if ds.RasterCount == 1
                                                    else "s"))]


def _grid_words(gt):
    return "origin %g, %g, pixel %g x %g" % (gt[0], gt[3], gt[1], gt[5])


def _changes_beside(ds, path, data):
    """The record of which pixels a person changed, beside the copy, and
    the .qml the corrected map opens with."""
    out = []
    changes = changes_path_of(data, path)
    name = os.path.basename(changes)
    flagged = any((ds.GetRasterBand(b).GetDescription() or "").lower()
                  == FLAG_BAND_NAME for b in range(1, ds.RasterCount + 1))
    if not os.path.exists(long_path(changes)):
        if not flagged:
            out.append(Finding(NOTE, "%s is not beside the working copy" % name,
                               "the strokes still work; which pixels a person "
                               "changed is not known until it is there. Correct "
                               "starts a new, empty one when it opens."))
    else:
        try:
            rec = gdal.Open(changes)
        except Exception:
            rec = None
        if rec is None:
            out.append(Finding(BAD, "%s cannot be opened" % name, changes))
        elif (rec.RasterXSize, rec.RasterYSize) != (ds.RasterXSize,
                                                    ds.RasterYSize):
            out.append(Finding(BAD, "%s is not on the grid of the copy" % name,
                               "%d x %d pixels, the copy %d x %d. It is not "
                               "the record of this copy."
                               % (rec.RasterXSize, rec.RasterYSize,
                                  ds.RasterXSize, ds.RasterYSize)))
        elif pixel_grid(rec) != pixel_grid(ds):
            # a copy written by an earlier build for a picture with no
            # georeference: GDAL's default grid, which QGIS draws beside the
            # picture
            out.append(Finding(NOTE, "%s is not drawn where the copy is" % name,
                               "its grid is %s, the copy's %s. Correct puts it "
                               "on the grid of the copy the next time it opens."
                               % (_grid_words(pixel_grid(rec)),
                                  _grid_words(pixel_grid(ds)))))
        else:
            try:
                marked = band_marked(rec)
            except Exception:
                marked = None
            out.append(Finding(OK, "%s records %s pixel%s changed by a person"
                               % (name, "?" if marked is None else marked,
                                  "" if marked == 1 else "s")))
        rec = None
    style = style_of(path)
    if not os.path.exists(long_path(style)):
        out.append(Finding(NOTE, "%s is not beside the working copy"
                                 % os.path.basename(style),
                           "QGIS opens the corrected map without its classes "
                           "until it is there. Correct writes it when it opens."))
    else:
        out.append(Finding(OK, "%s is beside the copy: QGIS opens it with its "
                               "classes" % os.path.basename(style)))
    return out


def _moved_corrections(campaign):
    """Corrections the campaign manifest still lists and that have a campaign
    of their own, whose folder is not there."""
    out = []
    for item in campaign.data.get("corrections", []) or []:
        where = from_folder(item.get("moved_to"), campaign.folder)
        if where and not os.path.exists(where):
            out.append(Finding(NOTE, "correction '%s' was moved to its own "
                                     "campaign at %s, which is not there any "
                                     "more" % (item.get("name", "?"), where),
                               "the record in campaign.json is kept, with its "
                               "files, and nothing else depends on it."))
    return out


# =====================================================================
#  The report, and the window it is shown in
# =====================================================================
def reports_findings(owner):
    """The reports the manifest of a campaign or a correction lists whose
    folder is not there any more: moved, renamed or deleted by hand. Nothing
    at all while it lists none."""
    data = getattr(owner, "data", None) or {}
    folder = getattr(owner, "folder", None)
    if not folder or not data.get("reports"):
        return []
    gone = report_missing(data, folder)
    if not gone:
        return []
    return [Finding(NOTE, "%d report%s the manifest lists %s not there"
                    % (len(gone), "" if len(gone) == 1 else "s",
                       "is" if len(gone) == 1 else "are"),
                    ", ".join(str(e.get("folder") or "?") for e in gone[:4])
                    + (", ..." if len(gone) > 4 else ""))]


def more_findings(found, owner):
    """What the measuring modules have to say about this campaign or
    correction (measure.DOCTOR_CAMPAIGN and DOCTOR_CORRECTION): each one
    asked in turn, and one that fails says so instead of taking Check
    down with it."""
    out = []
    for ask in found or []:
        try:
            out.extend(ask(owner) or [])
        except Exception as err:
            out.append(Finding(NOTE, "a check of the measures could not run",
                               "%s: %s" % (getattr(ask, "__name__", "?"),
                                           err)))
    return out


def report(campaign, correction=None, campaign_too=True, more=None):
    """The report as text, with how many problems and notes it holds.

    campaign_too=False leaves the annotation campaign out altogether: the
    Check in CORRECTION reports on the correction and on what is running,
    and a line about the campaign there would answer a question nobody
    asked. more is {"campaign": [fn], "correction": [fn]}: what the
    measuring modules check, fn(owner) -> [Finding], added to each part."""
    more = more or {}
    machine = about_the_machine()
    camp = about_the_campaign(campaign) if campaign_too else []
    if campaign_too and campaign is not None:
        camp += more_findings(more.get("campaign"), campaign)
    fixes = about_the_correction(correction) if correction is not None else []
    if correction is not None:
        fixes += more_findings(more.get("correction"), correction)
    bad = [f for f in machine + camp + fixes if f.level == BAD]
    notes = [f for f in machine + camp + fixes if f.level == NOTE]
    lines = []
    if bad:
        lines.append("%d problem%s found." % (len(bad), "" if len(bad) == 1 else "s"))
    elif notes:
        lines.append("Nothing is broken. %d thing%s worth knowing."
                     % (len(notes), "" if len(notes) == 1 else "s"))
    else:
        lines.append("Everything checks out.")
    lines.append("")
    lines.append("WHAT IS RUNNING")
    lines.extend(str(f) for f in machine)
    if campaign_too:
        lines.append("")
        lines.append("THE CAMPAIGN")
        lines.extend(str(f) for f in camp)
    if correction is not None:
        lines.append("")
        lines.append("THE CORRECTION")
        lines.extend(str(f) for f in fixes)
    if campaign is not None or correction is not None:
        lines.append("")
        lines.append("WHERE")
    if campaign is not None:
        lines.append("  folder   %s" % campaign.folder)
        lines.append("  package  %s" % campaign.package_path)
    if correction is not None:
        lines.append("  correction  %s" % correction.folder)
        lines.append("  manifest    %s" % correction.manifest_path)
        lines.append("  copy        %s" % correction.working_path)
    if campaign is not None or correction is not None:
        where = log_path()
        if where:
            lines.append("  log      %s" % where)
    lines.append("")
    lines.append("Paste this into a bug report. It says which build it is, what "
                 "it was running on,")
    lines.append("and what the campaign looked like, which is most of what "
                 "anybody needs to begin.")
    # pasted into public issues: the home folder, and with it the name of
    # whoever is running, is written ~
    return without_home("\n".join(lines)), len(bad), len(notes)


def report_html(text):
    """The report as the window shows it: the problems first, in the colour
    of a problem, then every line in its section with its mark coloured,
    wrapped to the window. The text itself, the one that is copied, is not
    changed: this is only how it is read."""
    c = palette_colours()
    ink = {"PROBLEM": c["danger"], "note": c["step_ink"] if not c["dark"]
           else "#e6c86e", "ok": c["dim"]}
    # A finding is a row of two cells, its mark and its words, so every
    # message starts at the same column and a long one wraps under itself,
    # not back under the mark: one space after the mark left them ragged.
    try:
        mark = QFontMetrics(fixed_font()).horizontalAdvance("problem") + 12
    except Exception:
        mark = 64

    def finding(tag, colour, words, dim=None):
        return ("<table cellspacing='0' cellpadding='0' "
                "style='margin-left:12px'><tr>"
                "<td width='%d' valign='top' style='white-space:nowrap'>"
                "%s</td><td valign='top'%s>%s</td></tr></table>"
                % (mark, "<span style='color:%s'><b>%s</b></span>"
                   % (colour, tag) if tag else "",
                   " style='color:%s'" % dim if dim else "", words))
    rows, problems, level = [], [], None
    lines = text.splitlines()[1:]           # the first is the headline
    for line in lines:
        bare = line.strip()
        if not bare:
            rows.append("<div>&nbsp;</div>")
            level = None
            continue
        if not line.startswith(" "):
            rows.append("<div style='margin-top:4px'><b>%s</b></div>"
                        % escape(bare))
            level = None
            continue
        word = bare.split()[0]
        if word in ink and line.startswith("  " + word):
            level = word
            rest = bare[len(word):].strip()
            row = finding("problem" if word == "PROBLEM" else word,
                          ink[word], escape(rest))
            rows.append(row)
            if word == "PROBLEM":
                problems.append(row)
        else:
            # the detail under a finding, under its words, or a line of WHERE
            row = finding("", "", escape(bare), c["dim"]) if level else \
                ("<div style='margin-left:12px; color:%s'>%s</div>"
                 % (c["text"], escape(bare)))
            rows.append(row)
            if level == "PROBLEM":
                problems.append(row)
    head = ""
    if problems:
        head = ("<div><b>What is wrong</b></div>" + "".join(problems)
                + "<div>&nbsp;</div><div><b>The whole report</b></div>")
    return head + "".join(rows)


class Report(QDialog):
    """The report, in a window, with one button that matters: Copy."""

    def __init__(self, parent, text, bad, notes):
        super().__init__(parent)
        self.setWindowTitle("%s: Check" % NAME)
        self.text = text
        outer = QVBoxLayout(self)
        outer.setContentsMargins(12, 12, 12, 12)
        outer.setSpacing(8)
        headline = ("%d problem%s found" % (bad, "" if bad == 1 else "s") if bad
                    else "Nothing is broken" if notes else "Everything checks out")
        top = QLabel(headline)
        font = top.font()
        font.setBold(True)
        font.setPointSizeF(font.pointSizeF() * 1.1)
        top.setFont(font)
        if bad:
            top.setObjectName("warn")
        outer.addWidget(top)
        if notes and not bad:
            said = QLabel("%d thing%s worth knowing, marked note below."
                          % (notes, "" if notes == 1 else "s"))
            said.setObjectName("quiet")
            outer.addWidget(said)
        # Read as a list and wrapped to the window, in the fixed font of the
        # system so the columns of the versions line up. A raw dump would be cut
        # off at the right edge behind a scroll bar, with problems, notes and
        # fine lines all alike.
        box = QTextBrowser()
        box.setReadOnly(True)
        box.setOpenLinks(False)
        box.setFont(fixed_font())
        box.setHtml(report_html(text))
        box.setMinimumWidth(TROUBLE_W)
        box.setMinimumHeight(360)
        self.view = box
        outer.addWidget(box)
        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Close)
        copy = bb.addButton("Copy report", QDialogButtonBox.ButtonRole.ActionRole)
        copy.clicked.connect(self.copy)
        bb.rejected.connect(self.reject)
        outer.addWidget(bb)

    def copy(self):
        try:
            QApplication.clipboard().setText(self.text)
            log("the check report is on the clipboard")
        except Exception as err:
            log("the report could not be copied: %s" % err)


def check(parent, campaign, correction=None, campaign_too=True, more=None):
    """Look everything over and show it. Changes nothing.

    The work happens on the thread that draws the window, so on a large campaign
    the window stops answering for a few seconds. An hourglass is the answer: it
    says "working", which is the difference between waiting and believing the
    program has died. Doing it on another thread would mean reading QGIS
    layers from a thread that does not own them.
    """
    try:
        QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
    except Exception:
        pass
    try:
        text, bad, notes = report(campaign, correction, campaign_too, more)
    finally:
        try:
            QApplication.restoreOverrideCursor()
        except Exception:
            pass
    for line in text.splitlines():
        if line.strip():
            log("check: " + line.strip())
    d = Report(parent, text, bad, notes)
    d.setWindowModality(Qt.WindowModality.WindowModal)
    d.resize(TROUBLE_W + 60, 560)
    run_dialog(d)           # one place in the program knows how Qt spells exec
    return bad

